router.get("/", async (req, res) => {
  try {
    const distributorId = readString(req.auth?.distributorId);

    const firmId = readString(req.auth?.firmId);

    const firmName = readString(
      req.query.firmName
    );

    if (!distributorId || !firmId) {
      return res.status(400).json({
        success: false,
        message:
          "distributorId and firmId are required.",
      });
    }

    let setup = await GeneralSetup.findOne({
      distributorId,
      firmId,
      isActive: true,
    }).lean();

    if (!setup) {
      const defaultSetup =
        createDefaultGeneralSetup({
          distributorId,
          firmId,
          firmName,
        });

      try {
      const createdSetup =
        await GeneralSetup.create(
          defaultSetup
        );

      setup = createdSetup.toObject();
      } catch (error) {
        // Another request may have created the tenant's unique setup after
        // the read above. Return that document instead of failing the GET.
        if (error?.code !== 11000) throw error;
        setup = await GeneralSetup.findOne({ distributorId, firmId, isActive: true }).lean();
        if (!setup) throw error;
      }
    }

    return res.json({
      success: true,
      setup,
    });
  } catch (error) {
    console.error(
      "General Setup load error:",
      error
    );

    return res.status(500).json({
      success: false,
      message:
        "Failed to load General Setup.",
      error: error.message,
    });
  }
})

