router.get("/", requireDistributorAdmin, async (req, res) => {
    try {
      const distributorId = readString(req.auth?.distributorId);
      const firmId = readString(req.auth?.firmId);

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message: "Distributor and Firm are required.",
        });
      }

      const users = await User.find({
        distributorId,
        firmId,
        isActive: true,
      })
        .select("-password -oldPassword")
        .sort({ userName: 1 })
        .lean();

      const resultUsers = [];

      for (const user of users) {
        let security = await SecuritySetup.findOne({
          distributorId,
          firmId,
          userId: user.userId,
        });

        if (!security) {
          security = await SecuritySetup.create({
            distributorId,
            firmId,
            firmName: user.firmName,
            userId: user.userId,
            userName: user.userName,
            role: normalizeRole(user.role),
            permissions: createDefaultPermissions(
              normalizeRole(user.role)
            ),
          });
        }

        resultUsers.push({
          ...user,
          permissions: security.permissions,
        });
      }

      return res.json({
        success: true,

        operationGroups: DEFAULT_OPERATION_GROUPS,

        users: resultUsers,
      });

    } catch (error) {

      console.error(error);

      return res.status(500).json({
        success: false,
        message: "Unable to load security setup.",
      });

    }
  })

