router.get("/my-permissions", async (req, res) => {
    try {
      const distributorId = readString(req.auth?.distributorId);
      const firmId = readString(req.auth?.firmId);
      const userId = readString(req.auth?.userId);
      const role = normalizeRole(req.auth?.role);

      if (!distributorId || !firmId || !userId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId, firmId and userId are required.",
        });
      }

      /*
       * Distributor Admin
       * No need to read Security Setup.
       */
      if (role === "DISTRIBUTOR_ADMIN") {
        return res.json({
          success: true,
          isAdministrator: true,
          permissions: createDefaultPermissions("DISTRIBUTOR_ADMIN"),
        });
      }

      /*
       * Normal User
       */
      const security =
        await SecuritySetup.findOne({
          distributorId,
          firmId,
          userId,
          isActive: true,
        }).lean();

      if (!security) {
        return res.json({
          success: true,
          isAdministrator: false,
          permissions: createDefaultPermissions("USER"),
        });
      }

      return res.json({
        success: true,
        isAdministrator: false,
        permissions: security.permissions || {},
      });
    } catch (error) {
      console.error(
        "My Permission Error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Unable to load user permissions.",
      });
    }
  })

