    return res.json({
      success: true,
      profile: {
        userId: user.userId || user.userName || "",
        userName: user.userName || "",
        role: user.role || "USER",
        firmName: user.firmName || "",
        firmCode: user.firmCode || "",
        salesmanCode: user.salesmanCode || "",
        distributorId: user.distributorId || "",
        isActive: Boolean(user.isActive),
        email: user.email || "",
