app.get("/api/users", ensureConnection, requireRoles("DISTRIBUTOR_ADMIN"), async (req, res) => {
  try {
    const distributorId = String(
      req.query.distributorId || ""
    ).trim();

    const firmId = String(
      req.query.firmId || ""
    ).trim();

    const search = String(
      req.query.search || ""
    ).trim();

    const requestedPage = Number.parseInt(
      req.query.page,
      10
    );

    const requestedLimit = Number.parseInt(
      req.query.limit,
      10
    );

    const page =
      Number.isFinite(requestedPage) &&
        requestedPage > 0
        ? requestedPage
        : 1;

    const limit =
      Number.isFinite(requestedLimit) &&
        requestedLimit > 0
        ? Math.min(requestedLimit, 100)
        : 10;

    if (!distributorId || !firmId) {
      return res.status(400).json({
        success: false,
        message:
          "distributorId and firmId are required",
      });
    }

    const escapedSearch = search.replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );

    const filter = {
      distributorId,
      firmId,
      isActive: true,
    };

    if (escapedSearch) {
      const searchRegex = new RegExp(
        escapedSearch,
        "i"
      );

      filter.$or = [
        { userId: searchRegex },
        { userName: searchRegex },
        { role: searchRegex },
        { firmName: searchRegex },
      ];
    }

    const totalRecords =
      await User.countDocuments(filter);

    const totalPages = Math.max(
      1,
      Math.ceil(totalRecords / limit)
    );

    const currentPage = Math.min(
      page,
      totalPages
    );

    const skip =
      (currentPage - 1) * limit;

    const users = await User.find(filter)
      /*
      * Password fields are not needed in the list.
      * Do not send them unnecessarily.
      */
      .select("-password")
      .sort({
        createdAt: -1,
        _id: -1,
      })
      .skip(skip)
      .limit(limit)
      .lean();

    return res.json({
      success: true,

      users,

      count: users.length,

      pagination: {
        currentPage,
        page: currentPage,
        limit,
        totalRecords,
        totalPages,

        hasPreviousPage:
          currentPage > 1,

        hasNextPage:
          currentPage < totalPages,

        startRecord:
          totalRecords === 0
            ? 0
            : skip + 1,

        endRecord:
          totalRecords === 0
            ? 0
            : Math.min(
              skip + users.length,
              totalRecords
            ),
      },
    });
  } catch (error) {
    console.error(
      "❌ User Master pagination load error:",
      error
    );

    return res.status(500).json({
      success: false,
      message: "Failed to fetch users",
      error: error.message,
    });
  }
})

