              mobileNo:
                salesman.mobileNo || "",
              phoneNo:
                salesman.phoneNo || "",
            });
          }
        );
      }

      const salesmen = Array.from(
        salesmanMap.values()
      ).sort((first, second) =>
        String(
          first.salesmanName
        ).localeCompare(
          String(second.salesmanName)
