          type: "number",
        },
        {
          key: "areaName",
          label: "Area Name",
        },
        {
          key: "salesmanName",
          label:
            "Salesman Name",
        }
      );

      return res.json({
        success: true,
        count: rows.length,
        reportLevel,
        productWise,
        rows,

        columns:
          reportLevel ===
            "salesSummary"
            ? summaryColumns
            : detailColumns,
      });
    } catch (error) {
      console.error(
        "Party sales report error:",
        error
      );

      return res
        .status(500)
        .json({
          success: false,
          message:
            "Failed to generate party sales report.",
          error: error.message,
        });
    }
  }
