app.get(
  "/api/reports/party-sales",
  ensureConnection,
  securityRouter.authorizeRequest("REPORTS", "PARTY_WISE_SALES", "view"),
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const companyCode = String(
        req.query.companyCode || ""
      ).trim();

      const reportLevel = String(
        req.query.reportLevel ||
        "salesSummary"
      ).trim();

      const productWise =
        String(
          req.query.productWise ||
          "no"
        ).toLowerCase() === "yes";

      const withCreditNote =
        String(
          req.query.withCreditNote ||
          "no"
        ).toLowerCase() === "yes";

      const fromDate = String(
        req.query.fromDate || ""
      ).trim();

      const toDate = String(
        req.query.toDate || ""
      ).trim();

      const orderBy = String(
        req.query.orderBy ||
        "partyName"
      ).trim();

      /*
      * Convert comma-separated query parameters
      * into cleaned arrays.
      */
      const parseCsv = (value) =>
        String(value || "")
          .split(",")
          .map((item) =>
            item.trim()
          )
          .filter(Boolean);

      const selectedPartyCodes =
        parseCsv(
          req.query.selectedPartyCodes
        );

      const selectedAreaCodes =
        parseCsv(
          req.query.selectedAreaCodes
        );

      const selectedSalesmanCodes =
        parseCsv(
          req.query
            .selectedSalesmanCodes
        );

      /*
      * Basic validation.
      */
      if (
        !distributorId ||
        !firmId
      ) {
        return res
          .status(400)
          .json({
            success: false,
            message:
              "distributorId and firmId are required.",
          });
      }

      if (
        !fromDate ||
        !toDate
      ) {
        return res
          .status(400)
          .json({
            success: false,
            message:
              "From Date and To Date are required.",
          });
      }

      if (fromDate > toDate) {
        return res
          .status(400)
          .json({
            success: false,
            message:
              "From Date cannot be greater than To Date.",
          });
      }

      if (
        reportLevel ===
        "selectedParty" &&
        selectedPartyCodes.length ===
        0
      ) {
        return res
          .status(400)
          .json({
            success: false,
            message:
              "Select at least one party.",
          });
      }

      /*
      * Prepare sales bill filter.
      */
      const match = {
        distributorId,
        firmId,
        isActive: true,

        IsBillCancelled: {
          $ne: true,
        },

        BillStatus: {
          $ne: "CANCELLED",
        },

        BillDate: {
          $gte: fromDate,
          $lte: toDate,
        },
      };

      if (companyCode) {
        match.CompanyCode =
          companyCode;
      }

      if (
        selectedPartyCodes.length >
        0
      ) {
        match.PartyCode = {
          $in: selectedPartyCodes,
        };
      }

      if (
        selectedAreaCodes.length >
        0
      ) {
        match.AreaCode = {
          $in: selectedAreaCodes,
        };
      }

      if (
        selectedSalesmanCodes.length >
        0
      ) {
        match.SalesmanCode = {
          $in:
            selectedSalesmanCodes,
        };
      }

      /*
      * Load all matching sales bills.
      */
      const bills =
        await SalesHeader.find(
          match
        )
          .sort({
            BillDate: 1,
            BillSeries: 1,
            BillNo: 1,
          })
          .lean();

      /*
      * Return an empty report cleanly.
      */
      if (bills.length === 0) {
        return res.json({
          success: true,
          count: 0,
          reportLevel,
          productWise,
          rows: [],
          columns: [],
        });
      }

      /*
      * Safely convert different possible
      * numeric field formats.
      */
      const toNumber = (
        ...values
      ) => {
        for (const value of values) {
          if (
            value !== undefined &&
            value !== null &&
            value !== ""
          ) {
            const number =
              Number(value);

            if (
              !Number.isNaN(number)
            ) {
              return number;
            }
          }
        }

        return 0;
      };

      /*
      * Read the first available property
      * from an invoice item.
      */
      const getItemValue = (
        item,
        ...keys
      ) => {
        for (const key of keys) {
          if (
            item?.[key] !==
            undefined &&
            item?.[key] !== null
          ) {
            return item[key];
          }
        }

        return "";
      };

      /*
      * Read product code and product name
      * from all supported invoice formats.
      *
      * Some invoices store:
      * product: "986523 - BOURNVILLA 250 GM"
      */
      const getProductDetails = (
        item = {}
      ) => {
        const combinedProduct =
          String(
            getItemValue(
              item,
              "product",
              "Product",
              "productDisplay",
              "productDescription"
            ) || ""
          ).trim();

        let productCode =
          String(
            getItemValue(
              item,
              "productCode",
              "ProductCode",
              "prodCode",
              "ProdCode",
              "productId",
              "ProductId",
              "code"
            ) || ""
          ).trim();

        let productName =
          String(
            getItemValue(
              item,
              "productName",
              "ProductName",
              "prodName",
              "ProdName",
              "name"
            ) || ""
          ).trim();

        if (combinedProduct) {
          const separatorIndex =
            combinedProduct.indexOf(
              " - "
            );

          if (
            separatorIndex >= 0
          ) {
            const parsedCode =
              combinedProduct
                .slice(
                  0,
                  separatorIndex
                )
                .trim();

            const parsedName =
              combinedProduct
                .slice(
                  separatorIndex +
                  3
                )
                .trim();

            if (!productCode) {
              productCode =
                parsedCode;
            }

            if (!productName) {
              productName =
                parsedName;
            }
          } else if (
            !productName
          ) {
            productName =
              combinedProduct;
          }
        }

        return {
          productCode,
          productName,
        };
      };

      /*
      * Collect every product code used in
      * the selected sales invoices.
      */
      const soldProductCodes = [
        ...new Set(
          bills
            .flatMap((bill) => {
              const items =
                Array.isArray(
                  bill.items
                )
                  ? bill.items
                  : [];

              return items.map(
                (item) =>
                  getProductDetails(
                    item
                  ).productCode
              );
            })
            .filter(Boolean)
        ),
      ];

      /*
      * Load matching product master rows.
      * This provides product-name fallback
      * where old invoices only have code.
      */
      const productMasters =
        soldProductCodes.length >
          0
          ? await Product.find({
            distributorId,
            firmId,

            productCode: {
              $in:
                soldProductCodes,
            },
          })
            .select({
              productCode: 1,
              productName: 1,
              companyId: 1,
              companyName: 1,
            })
            .lean()
          : [];

      const productMasterMap =
        new Map(
          productMasters.map(
            (product) => [
              String(
                product.productCode ||
                ""
              ).trim(),
              product,
            ]
          )
        );

      /*
      * Load every Mas_Stock row for the
      * products appearing in selected bills.
      *
      * PRate, SRate, MRP and Batch are read
      * from this collection.
      */
      const stockRows =
        soldProductCodes.length >
          0
          ? await Stock.find({
            distributorId,
            firmId,

            ProdCode: {
              $in:
                soldProductCodes,
            },
          })
            .select({
              _id: 1,
              GDCode: 1,
              ProdCode: 1,
              Batch: 1,
              MRP: 1,
              PRate: 1,
              SRate: 1,
              Qty: 1,
              MfgDt: 1,
              ExpDt: 1,
              BoxPack: 1,
              InBoxPack: 1,
              IsLocked: 1,
            })
            .lean()
          : [];

      /*
      * Create product-wise stock lookup.
      * A product can have several batches,
      * MRP values and godowns.
      */
      const stockProductMap =
        new Map();

      stockRows.forEach(
        (stock) => {
          const productCode =
            String(
              stock.ProdCode ||
              ""
            ).trim();

          if (!productCode) {
            return;
          }

          if (
            !stockProductMap.has(
              productCode
            )
          ) {
            stockProductMap.set(
              productCode,
              []
            );
          }

          stockProductMap
            .get(productCode)
            .push(stock);
        }
      );

      /*
      * Normalize batch value so empty batch
      * and "." can be matched consistently.
      */
      const normalizeBatch = (
        value
      ) => {
        const batch = String(
          value ?? ""
        ).trim();

        return batch || ".";
      };

      /*
      * Find the most accurate Mas_Stock row
      * for one sales invoice item.
      *
      * Matching priority:
      * 1. Product + Godown + Batch + MRP
      * 2. Product + Batch + MRP
      * 3. Product + Godown + Batch
      * 4. Product + Batch
      * 5. Product + Godown + MRP
      * 6. Product + MRP
      * 7. Product + Godown
      * 8. First product stock row
      */
      const findItemStock = (
        bill,
        item,
        productCode
      ) => {
        if (!productCode) {
          return null;
        }

        const stockOptions =
          stockProductMap.get(
            productCode
          ) || [];

        if (
          stockOptions.length ===
          0
        ) {
          return null;
        }

        const selectedBatch =
          item?.selectedBatch &&
            typeof item
              .selectedBatch ===
            "object"
            ? item.selectedBatch
            : {};

        const godownCode =
          String(
            bill.GDCode ||
            item.GDCode ||
            item.gdCode ||
            selectedBatch.GDCode ||
            selectedBatch.gdCode ||
            ""
          ).trim();

        const batch =
          normalizeBatch(
            getItemValue(
              item,
              "batchNo",
              "BatchNo",
              "batch",
              "Batch"
            ) ||
            selectedBatch.batchNo ||
            selectedBatch.BatchNo ||
            selectedBatch.batch ||
            selectedBatch.Batch
          );

        const mrp = toNumber(
          getItemValue(
            item,
            "mrp",
            "MRP",
            "productMrp",
            "ProductMRP"
          ),
          selectedBatch.mrp,
          selectedBatch.MRP
        );

        const sameGodown = (
          stock
        ) =>
          !godownCode ||
          String(
            stock.GDCode || ""
          ).trim() === godownCode;

        const sameBatch = (
          stock
        ) =>
          normalizeBatch(
            stock.Batch
          ) === batch;

        const sameMrp = (
          stock
        ) =>
          mrp <= 0 ||
          Number(
            stock.MRP || 0
          ) === mrp;

        return (
          stockOptions.find(
            (stock) =>
              sameGodown(stock) &&
              sameBatch(stock) &&
              sameMrp(stock)
          ) ||
          stockOptions.find(
            (stock) =>
              sameBatch(stock) &&
              sameMrp(stock)
          ) ||
          stockOptions.find(
            (stock) =>
              sameGodown(stock) &&
              sameBatch(stock)
          ) ||
          stockOptions.find(
            (stock) =>
              sameBatch(stock)
          ) ||
          stockOptions.find(
            (stock) =>
              sameGodown(stock) &&
              sameMrp(stock)
          ) ||
          stockOptions.find(
            (stock) =>
              sameMrp(stock)
          ) ||
          stockOptions.find(
            (stock) =>
              sameGodown(stock)
          ) ||
          stockOptions[0] ||
          null
        );
      };

      /*
      * Build one report row for every
      * product in every matching invoice.
      */
      const detailRows = [];

      bills.forEach((bill) => {
        const items =
          Array.isArray(
            bill.items
          )
            ? bill.items
            : [];

        /*
        * Sales Details and Selected Party
        * Product Wise require actual items.
        *
        * For older header-only invoices,
        * keep one blank product row only
        * when products were not requested.
        */
        const productsRequired =
          reportLevel ===
          "salesDetails" ||
          productWise;

        const reportItems =
          items.length > 0
            ? items
            : productsRequired
              ? []
              : [{}];

        reportItems.forEach(
          (
            item,
            itemIndex
          ) => {
            const selectedBatch =
              item?.selectedBatch &&
                typeof item
                  .selectedBatch ===
                "object"
                ? item.selectedBatch
                : {};

            const {
              productCode,
              productName:
              savedProductName,
            } =
              getProductDetails(
                item
              );

            const productMaster =
              productMasterMap.get(
                productCode
              );

            const productName =
              savedProductName ||
              productMaster
                ?.productName ||
              "";

            const stockRow =
              findItemStock(
                bill,
                item,
                productCode
              );

            const qty = toNumber(
              getItemValue(
                item,
                "qty",
                "Qty",
                "quantity",
                "Quantity",
                "saleQty",
                "SaleQty"
              )
            );

            const freeQty =
              toNumber(
                getItemValue(
                  item,
                  "freeQty",
                  "FreeQty",
                  "freeQuantity"
                )
              );

            /*
            * Sale rate first uses the actual
            * invoice rate. Mas_Stock SRate is
            * used only when invoice rate is absent.
            */
            const salesRate =
              toNumber(
                getItemValue(
                  item,
                  "salesRate",
                  "SalesRate",
                  "saleRate",
                  "SaleRate",
                  "sRate",
                  "SRate",
                  "rate",
                  "Rate"
                ),
                selectedBatch.salesRate,
                selectedBatch.SalesRate,
                selectedBatch.sRate,
                selectedBatch.SRate,
                stockRow?.SRate
              );

            /*
            * Purchase rate uses Mas_Stock PRate
            * where it is not saved in invoice item.
            */
            const purchaseRate =
              toNumber(
                getItemValue(
                  item,
                  "purchaseRate",
                  "PurchaseRate",
                  "pRate",
                  "PRate",
                  "prate"
                ),
                selectedBatch
                  .purchaseRate,
                selectedBatch
                  .PurchaseRate,
                selectedBatch.pRate,
                selectedBatch.PRate,
                selectedBatch.PRate,
                stockRow?.PRate
              );

            const mrp = toNumber(
              getItemValue(
                item,
                "mrp",
                "MRP",
                "productMrp",
                "ProductMRP"
              ),
              selectedBatch.mrp,
              selectedBatch.MRP,
              stockRow?.MRP
            );

            const batch =
              normalizeBatch(
                getItemValue(
                  item,
                  "batchNo",
                  "BatchNo",
                  "batch",
                  "Batch"
                ) ||
                selectedBatch
                  .batchNo ||
                selectedBatch
                  .BatchNo ||
                selectedBatch
                  .batch ||
                selectedBatch
                  .Batch ||
                stockRow?.Batch
              );

            const godownCode =
              String(
                bill.GDCode ||
                stockRow
                  ?.GDCode ||
                ""
              ).trim();

            const godownName =
              String(
                bill.Godown ||
                godownCode ||
                ""
              ).trim();

            const stockQty =
              toNumber(
                stockRow?.Qty
              );

            const mfgDate =
              String(
                getItemValue(
                  item,
                  "mfgDate",
                  "MfgDate",
                  "MfgDt",
                  "manufacturingDate"
                ) ||
                selectedBatch
                  .mfgDate ||
                selectedBatch
                  .MfgDt ||
                stockRow?.MfgDt ||
                ""
              );

            const expiryDate =
              String(
                getItemValue(
                  item,
                  "expiryDate",
                  "ExpiryDate",
                  "expDate",
                  "ExpDate",
                  "ExpDt"
                ) ||
                selectedBatch
                  .expiryDate ||
                selectedBatch
                  .expDate ||
                selectedBatch
                  .ExpDt ||
                stockRow?.ExpDt ||
                ""
              );

            const grossAmount =
              toNumber(
                getItemValue(
                  item,
                  "grossAmount",
                  "GrossAmount",
                  "grossAmt",
                  "GrossAmt"
                ),
                qty * salesRate
              );

            const schemePercent =
              toNumber(
                getItemValue(
                  item,
                  "schemePercent",
                  "SchemePercent",
                  "schemePer",
                  "SchemePer",
                  "scheme",
                  "schPercent",
                  "schPer",
                  "schPct",
                  "SchPercent"
                )
              );

            const schemeAmount =
              toNumber(
                getItemValue(
                  item,
                  "schemeAmount",
                  "SchemeAmount",
                  "schemeAmt",
                  "schAmount",
                  "schAmt",
                  "SchAmount"
                )
              );

            const cashDiscountPercent =
              toNumber(
                getItemValue(
                  item,
                  "cashDiscountPercent",
                  "CashDiscountPercent",
                  "cashDiscountPer",
                  "cdPercent",
                  "cdPer",
                  "CDPct",
                  "CDPercent"
                )
              );

            const cashDiscountAmount =
              toNumber(
                getItemValue(
                  item,
                  "cashDiscountAmount",
                  "CashDiscountAmount",
                  "cashDiscountAmt",
                  "cdAmount",
                  "cdAmt",
                  "CDAmount"
                )
              );

            const tprPercent =
              toNumber(
                getItemValue(
                  item,
                  "tprPercent",
                  "TPRPercent",
                  "tprPer",
                  "TPRPer"
                )
              );

            const tprAmount =
              toNumber(
                getItemValue(
                  item,
                  "tprAmount",
                  "TPRAmount",
                  "tprAmt",
                  "TPRAmt"
                )
              );

            const cgstPercent =
              toNumber(
                getItemValue(
                  item,
                  "cgstPercent",
                  "CGSTPercent",
                  "cgstPer"
                )
              );

            const sgstPercent =
              toNumber(
                getItemValue(
                  item,
                  "sgstPercent",
                  "SGSTPercent",
                  "sgstPer"
                )
              );

            const igstPercent =
              toNumber(
                getItemValue(
                  item,
                  "igstPercent",
                  "IGSTPercent",
                  "igstPer"
                )
              );

            const gstPercent =
              igstPercent ||
              cgstPercent +
              sgstPercent ||
              toNumber(
                getItemValue(
                  item,
                  "gstPercent",
                  "GSTPercent",
                  "gst",
                  "GST"
                )
              );

            const cgstAmount =
              toNumber(
                getItemValue(
                  item,
                  "cgstAmount",
                  "CGSTAmount",
                  "cgstAmt"
                )
              );

            const sgstAmount =
              toNumber(
                getItemValue(
                  item,
                  "sgstAmount",
                  "SGSTAmount",
                  "sgstAmt"
                )
              );

            const igstAmount =
              toNumber(
                getItemValue(
                  item,
                  "igstAmount",
                  "IGSTAmount",
                  "igstAmt"
                )
              );

            const gstAmount =
              cgstAmount +
              sgstAmount +
              igstAmount;

            const taxableAmount =
              toNumber(
                getItemValue(
                  item,
                  "taxableAmount",
                  "TaxableAmount",
                  "taxableValue",
                  "TaxableValue"
                ),
                grossAmount -
                schemeAmount -
                cashDiscountAmount -
                tprAmount
              );

            const calculatedNet =
              taxableAmount +
              gstAmount;

            const originalItemNet =
              toNumber(
                getItemValue(
                  item,
                  "netAmount",
                  "NetAmount",
                  "netAmt",
                  "amount",
                  "Amount"
                ),
                calculatedNet
              );

            /*
            * CreditNoteAmount is stored at
            * bill-header level.
            *
            * Apply it only to the first item
            * row so it is not deducted once
            * for every product.
            */
            const creditNoteAmount =
              withCreditNote &&
                itemIndex === 0
                ? toNumber(
                  bill
                    .CreditNoteAmount
                )
                : 0;

            const netAmount =
              originalItemNet -
              creditNoteAmount;

            detailRows.push({
              rowId: `${String(
                bill._id
              )}-${itemIndex}`,

              srNo:
                detailRows.length +
                1,

              trn: "SALES",

              billDate:
                bill.BillDate || "",

              billSeries:
                bill.BillSeries ||
                "",

              billNo:
                bill.BillNo ?? "",

              billReference: [
                bill.BillSeries,
                bill.BillNo,
              ]
                .filter(
                  (value) =>
                    value !==
                    undefined &&
                    value !==
                    null &&
                    value !== ""
                )
                .join("-"),

              billType:
                bill.BillType ||
                "",

              companyCode:
                bill.CompanyCode ||
                "",

              companyName:
                bill.CompanyName ||
                "",

              partyCode:
                bill.PartyCode ||
                "",

              partyName:
                bill.PartyName ||
                "",

              productCode,
              productName,

              batch,
              mrp,
              qty,
              freeQty,

              salesRate,
              purchaseRate,

              godownCode,
              godownName,
              stockQty,

              mfgDate,
              expiryDate,

              grossAmount,

              tprPercent,
              tprAmount,

              schemePercent,
              schemeAmount,

              cashDiscountPercent,
              cashDiscountAmount,

              taxableAmount,

              gstPercent,
              cgstPercent,
              cgstAmount,
              sgstPercent,
              sgstAmount,
              igstPercent,
              igstAmount,
              gstAmount,

              creditNoteAmount,
              netAmount,

              areaCode:
                bill.AreaCode ||
                "",

              areaName:
                bill.AreaName ||
                "",

              salesmanCode:
                bill.SalesmanCode ||
                "",

              salesmanName:
                bill.SalesmanName ||
                "",
            });
          }
        );
      });

      let rows = detailRows;

      /*
      * Sales Summary is grouped by party.
      *
      * When Product Wise is Yes, summary
      * is grouped by party and product.
      *
      * Selected Party is intentionally not
      * grouped because it must show each bill.
      */
      if (
        reportLevel ===
        "salesSummary"
      ) {
        const groupedRows =
          new Map();

        detailRows.forEach(
          (row) => {
            const groupKey =
              productWise
                ? `${row.partyCode}__${row.productCode}`
                : row.partyCode ||
                row.partyName;

            if (
              !groupedRows.has(
                groupKey
              )
            ) {
              groupedRows.set(
                groupKey,
                {
                  rowId:
                    groupKey,

                  srNo: 0,

                  partyCode:
                    row.partyCode,

                  partyName:
                    row.partyName,

                  ...(productWise
                    ? {
                      productCode:
                        row.productCode,

                      productName:
                        row.productName,

                      qty: 0,
                    }
                    : {}),

                  grossAmount: 0,
                  tprAmount: 0,
                  schemeAmount: 0,
                  cashDiscountAmount: 0,
                  taxableAmount: 0,
                  gstAmount: 0,
                  creditNoteAmount: 0,
                  netAmount: 0,

                  areaName:
                    row.areaName,

                  salesmanName:
                    row.salesmanName,
                }
              );
            }

            const group =
              groupedRows.get(
                groupKey
              );

            if (productWise) {
              group.qty +=
                toNumber(
                  row.qty
                );
            }

            group.grossAmount +=
              toNumber(
                row.grossAmount
              );

            group.tprAmount +=
              toNumber(
                row.tprAmount
              );

            group.schemeAmount +=
              toNumber(
                row.schemeAmount
              );

            group.cashDiscountAmount +=
              toNumber(
                row.cashDiscountAmount
              );

            group.taxableAmount +=
              toNumber(
                row.taxableAmount
              );

            group.gstAmount +=
              toNumber(
                row.gstAmount
              );

            group.creditNoteAmount +=
              toNumber(
                row.creditNoteAmount
              );

            group.netAmount +=
              toNumber(
                row.netAmount
              );
          }
        );

        rows = Array.from(
          groupedRows.values()
        );
      }

      /*
      * Sort final report rows.
      */
      const sortText = (
        value
      ) =>
        String(value || "")
          .trim()
          .toLowerCase();

      rows.sort(
        (first, second) => {
          if (
            orderBy ===
            "partyCode"
          ) {
            return sortText(
              first.partyCode
            ).localeCompare(
              sortText(
                second.partyCode
              )
            );
          }

          if (
            orderBy === "trn"
          ) {
            const firstSeries =
              sortText(
                first.billSeries
              );

            const secondSeries =
              sortText(
                second.billSeries
              );

            const seriesResult =
              firstSeries.localeCompare(
                secondSeries
              );

            if (
              seriesResult !== 0
            ) {
              return seriesResult;
            }

            return (
              Number(
                first.billNo || 0
              ) -
              Number(
                second.billNo || 0
              )
            );
          }

          if (
            orderBy ===
            "areaName"
          ) {
            return sortText(
              first.areaName
            ).localeCompare(
              sortText(
                second.areaName
              )
            );
          }

          if (
            orderBy ===
            "salesmanName"
          ) {
            return sortText(
              first.salesmanName
            ).localeCompare(
              sortText(
                second
                  .salesmanName
              )
            );
          }

          if (
            orderBy ===
            "netAmountDesc"
          ) {
            return (
              Number(
                second.netAmount ||
                0
              ) -
              Number(
                first.netAmount ||
                0
              )
            );
          }

          if (
            orderBy ===
            "productName"
          ) {
            return sortText(
              first.productName
            ).localeCompare(
              sortText(
                second.productName
              )
            );
          }

          const partyResult =
            sortText(
              first.partyName
            ).localeCompare(
              sortText(
                second.partyName
              )
            );

          if (
            partyResult !== 0
          ) {
            return partyResult;
          }

          const dateResult =
            sortText(
              first.billDate
            ).localeCompare(
              sortText(
                second.billDate
              )
            );

          if (
            dateResult !== 0
          ) {
            return dateResult;
          }

          return (
            Number(
              first.billNo || 0
            ) -
            Number(
