        },
        {
          key: "areaName",
          label: "Area Name",
        },
        {
          key: "salesmanName",
          label:
            "Salesman Name",
        }
      );

      return res.json({
        success: true,
        count: rows.length,
        reportLevel,
        productWise,
        rows,

        columns:
          reportLevel ===
            "salesSummary"
            ? summaryColumns
            : detailColumns,
      });
    } catch (error) {
