bills.forEach((bill) => {
        const items =
          Array.isArray(
            bill.items
          )
            ? bill.items
            : [];

        /*
        * Sales Details and Selected Party
        * Product Wise require actual items.
        *
        * For older header-only invoices,
        * keep one blank product row only
        * when products were not requested.
        */
        const productsRequired =
          reportLevel ===
          "salesDetails" ||
          productWise;

        const reportItems =
          items.length > 0
            ? items
            : productsRequired
              ? []
              : [{}];

        reportItems.forEach(
          (
            item,
            itemIndex
          ) => {
            const selectedBatch =
              item?.selectedBatch &&
                typeof item
                  .selectedBatch ===
                "object"
                ? item.selectedBatch
                : {};

            const {
              productCode,
              productName:
              savedProductName,
            } =
              getProductDetails(
                item
              );

            const productMaster =
              productMasterMap.get(
                productCode
              );

            const productName =
              savedProductName ||
              productMaster
                ?.productName ||
              "";

            const stockRow =
              findItemStock(
                bill,
                item,
                productCode
              );

            const qty = toNumber(
              getItemValue(
                item,
                "qty",
                "Qty",
                "quantity",
                "Quantity",
                "saleQty",
                "SaleQty"
              )
            );

            const freeQty =
              toNumber(
                getItemValue(
                  item,
                  "freeQty",
                  "FreeQty",
                  "freeQuantity"
                )
              );

            /*
            * Sale rate first uses the actual
            * invoice rate. Mas_Stock SRate is
            * used only when invoice rate is absent.
            */
            const salesRate =
              toNumber(
                getItemValue(
                  item,
                  "salesRate",
                  "SalesRate",
                  "saleRate",
                  "SaleRate",
                  "sRate",
                  "SRate",
                  "rate",
                  "Rate"
                ),
                selectedBatch.salesRate,
                selectedBatch.SalesRate,
                selectedBatch.sRate,
                selectedBatch.SRate,
                stockRow?.SRate
              );

            /*
            * Purchase rate uses Mas_Stock PRate
            * where it is not saved in invoice item.
            */
            const purchaseRate =
              toNumber(
                getItemValue(
                  item,
                  "purchaseRate",
                  "PurchaseRate",
                  "pRate",
                  "PRate",
                  "prate"
                ),
                selectedBatch
                  .purchaseRate,
                selectedBatch
                  .PurchaseRate,
                selectedBatch.pRate,
                selectedBatch.PRate,
                selectedBatch.PRate,
                stockRow?.PRate
              );

            const mrp = toNumber(
              getItemValue(
                item,
                "mrp",
                "MRP",
                "productMrp",
                "ProductMRP"
              ),
              selectedBatch.mrp,
              selectedBatch.MRP,
              stockRow?.MRP
