                selectedBatch
                  .batchNo ||
                selectedBatch
                  .BatchNo ||
                selectedBatch
                  .batch ||
                selectedBatch
                  .Batch ||
                stockRow?.Batch
              );

            const godownCode =
              String(
                bill.GDCode ||
                stockRow
                  ?.GDCode ||
                ""
              ).trim();

            const godownName =
              String(
                bill.Godown ||
                godownCode ||
                ""
              ).trim();

            const stockQty =
              toNumber(
                stockRow?.Qty
              );

            const mfgDate =
              String(
                getItemValue(
