              );

            const grossAmount =
              toNumber(
                getItemValue(
                  item,
                  "grossAmount",
                  "GrossAmount",
                  "grossAmt",
                  "GrossAmt"
                ),
                qty * salesRate
              );

            const schemePercent =
              toNumber(
                getItemValue(
                  item,
