                  "SchemePercent",
                  "schemePer",
                  "SchemePer",
                  "scheme",
                  "schPercent",
                  "schPer",
                  "schPct",
                  "SchPercent"
                )
              );

            const schemeAmount =
              toNumber(
                getItemValue(
                  item,
