                  "CashDiscountAmount",
                  "cashDiscountAmt",
                  "cdAmount",
                  "cdAmt",
                  "CDAmount"
                )
              );

            const tprPercent =
              toNumber(
                getItemValue(
                  item,
                  "tprPercent",
                  "TPRPercent",
                  "tprPer",
                  "TPRPer"
                )
              );

            const tprAmount =
              toNumber(
                getItemValue(
                  item,
                  "tprAmount",
                  "TPRAmount",
                  "tprAmt",
                  "TPRAmt"
                )
              );

            const cgstPercent =
              toNumber(
                getItemValue(
                  item,
                  "cgstPercent",
                  "CGSTPercent",
                  "cgstPer"
                )
              );

            const sgstPercent =
              toNumber(
                getItemValue(
                  item,
                  "sgstPercent",
                  "SGSTPercent",
                  "sgstPer"
                )
              );

            const igstPercent =
              toNumber(
                getItemValue(
                  item,
                  "igstPercent",
                  "IGSTPercent",
                  "igstPer"
                )
              );

            const gstPercent =
              igstPercent ||
              cgstPercent +
              sgstPercent ||
              toNumber(
                getItemValue(
                  item,
                  "gstPercent",
                  "GSTPercent",
                  "gst",
                  "GST"
                )
              );

            const cgstAmount =
              toNumber(
                getItemValue(
                  item,
                  "cgstAmount",
                  "CGSTAmount",
                  "cgstAmt"
                )
              );

            const sgstAmount =
              toNumber(
                getItemValue(
                  item,
                  "sgstAmount",
                  "SGSTAmount",
                  "sgstAmt"
                )
              );

            const igstAmount =
              toNumber(
                getItemValue(
                  item,
                  "igstAmount",
                  "IGSTAmount",
                  "igstAmt"
                )
              );

            const gstAmount =
