                getItemValue(
                  item,
                  "taxableAmount",
                  "TaxableAmount",
                  "taxableValue",
                  "TaxableValue"
                ),
                grossAmount -
                schemeAmount -
                cashDiscountAmount -
                tprAmount
              );

            const calculatedNet =
              taxableAmount +
              gstAmount;

            const originalItemNet =
              toNumber(
                getItemValue(
                  item,
                  "netAmount",
                  "NetAmount",
                  "netAmt",
                  "amount",
                  "Amount"
                ),
                calculatedNet
              );

            /*
            * CreditNoteAmount is stored at
            * bill-header level.
            *
            * Apply it only to the first item
            * row so it is not deducted once
            * for every product.
            */
            const creditNoteAmount =
