                )
                .join("-"),

              billType:
                bill.BillType ||
                "",

              companyCode:
                bill.CompanyCode ||
                "",

              companyName:
                bill.CompanyName ||
                "",

              partyCode:
                bill.PartyCode ||
                "",

              partyName:
                bill.PartyName ||
                "",

              productCode,
              productName,

              batch,
              mrp,
              qty,
              freeQty,

              salesRate,
              purchaseRate,

              godownCode,
              godownName,
              stockQty,

              mfgDate,
              expiryDate,

              grossAmount,

              tprPercent,
              tprAmount,

              schemePercent,
              schemeAmount,

              cashDiscountPercent,
              cashDiscountAmount,

              taxableAmount,

              gstPercent,
              cgstPercent,
              cgstAmount,
              sgstPercent,
              sgstAmount,
              igstPercent,
              igstAmount,
              gstAmount,

              creditNoteAmount,
              netAmount,

              areaCode:
                bill.AreaCode ||
                "",

              areaName:
                bill.AreaName ||
                "",

              salesmanCode:
                bill.SalesmanCode ||
                "",

              salesmanName:
                bill.SalesmanName ||
                "",
            });
          }
        );
      })

