            "productName"
          ) {
            return sortText(
              first.productName
            ).localeCompare(
              sortText(
                second.productName
              )
            );
          }

          const partyResult =
            sortText(
              first.partyName
            ).localeCompare(
              sortText(
                second.partyName
              )
            );

