app.get(
  "/api/companies",
  ensureConnection,

  securityRouter.authorizeRequest(
    "MASTER",
    "COMPANY",
    "view"
  ),

  async (req, res) => {

    const {
      distributorId,
      firmId,
    } = req.security;

    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      const companies = await Company.find({
        distributorId,
        firmId,
        isActive: true,
      })
        .sort({
          companyName: 1,
          companyCode: 1,
        })
        .lean();

      return res.json({
        success: true,
        count: companies.length,
        companies,
      });
    } catch (error) {
      console.error(
        "Company load error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to fetch companies",
        error: error.message,
      });
    }
  }
)

