app.get(
  "/api/products/list",
  ensureConnection,
  securityRouter.authorizeRequest(
    "master",
    "PRODUCT",
    "view"
  ),
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const companyCode = String(
        req.query.companyCode || ""
      ).trim();

      const groupCode = String(
        req.query.groupCode || ""
      ).trim();

      const categoryCode = String(
        req.query.categoryCode || ""
      ).trim();

      const requestedPage = Number.parseInt(
        req.query.page,
        10
      );

      const requestedLimit = Number.parseInt(
        req.query.limit,
        10
      );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(requestedLimit, 100)
          : 20;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      /*
      * Main filters.
      */
      const filter = {
        distributorId,
        firmId,

        /*
        * Include active records and old records
        * where isActive may not exist.
        */
        isActive: {
          $ne: false,
        },
      };

      /*
      * Store all optional filters inside $and.
      *
      * This avoids conflicts between:
      * - product search
      * - company filter
      * - group filter
      * - category filter
      */
      const andConditions = [];

      if (companyCode) {
        andConditions.push({
          $or: [
            {
              CompanyCode: companyCode,
            },
            {
              companyCode,
            },
            {
              CompCode: companyCode,
            },
          ],
        });
      }

      if (groupCode) {
        andConditions.push({
          $or: [
            {
              GroupCode: groupCode,
            },
            {
              groupCode,
            },
          ],
        });
      }

      if (categoryCode) {
        andConditions.push({
          $or: [
            {
              CategoryCode: categoryCode,
            },
            {
              categoryCode,
            },
          ],
        });
      }

      /*
      * Backend product search.
      */
      if (search) {
        const escapedSearch = search.replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

        const searchRegex = new RegExp(
          escapedSearch,
          "i"
        );

        andConditions.push({
          $or: [
            {
              ProdCode: searchRegex,
            },
            {
              productCode: searchRegex,
            },
            {
              code: searchRegex,
            },

            {
              ProdName: searchRegex,
            },
            {
              productName: searchRegex,
            },
            {
              name: searchRegex,
            },

            {
              ShortCode: searchRegex,
            },
            {
              shortCode: searchRegex,
            },

            {
              EANNo: searchRegex,
            },
            {
              EANCode: searchRegex,
            },
            {
              eanCode: searchRegex,
            },
            {
              barcode: searchRegex,
            },

            {
              CompanyCode: searchRegex,
            },
            {
              companyCode: searchRegex,
            },

            {
              CompanyName: searchRegex,
            },
            {
              companyName: searchRegex,
            },

            {
              GroupCode: searchRegex,
            },
            {
              groupCode: searchRegex,
            },

            {
              GroupName: searchRegex,
            },
            {
              groupName: searchRegex,
            },

            {
              CategoryCode: searchRegex,
            },
            {
              categoryCode: searchRegex,
            },

            {
              CategoryName: searchRegex,
            },
            {
              categoryName: searchRegex,
            },

            {
              HSNCode: searchRegex,
            },
            {
              hsnCode: searchRegex,
            },
            {
              hsn: searchRegex,
            },
          ],
        });
      }

      if (andConditions.length > 0) {
        filter.$and = andConditions;
      }

      /*
      * Count matching records.
      */
      const totalRecords =
        await Product.countDocuments(filter);

      const totalPages = Math.max(
        1,
        Math.ceil(totalRecords / limit)
      );

      /*
      * Prevent requesting a page greater than
      * the available page count.
      */
      const currentPage = Math.min(
        page,
        totalPages
      );

      const skip =
        (currentPage - 1) * limit;

      /*
      * Fetch only the current page.
      */
      const products = await Product.find(
        filter
      )
        .sort({
          ProdName: 1,
          productName: 1,
          ProdCode: 1,
          productCode: 1,
          _id: 1,
        })
        .skip(skip)
        .limit(limit)
        .lean();

      return res.status(200).json({
        success: true,

        products,

        count: products.length,

        pagination: {
          currentPage,
          page: currentPage,
          limit,

          totalRecords,
          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage < totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip + products.length,
                totalRecords
              ),
        },
      });
    } catch (error) {
      console.error(
        "Product Master pagination error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Product Master",
        error: error.message,
      });
    }
  }
)

