app.get(
  "/api/accounts/list",
  ensureConnection,
  securityRouter.authorizeRequest(
    "MASTER",
    "ACCOUNT",
    "view"
  ),
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const requestedPage = Number.parseInt(
        req.query.page,
        10
      );

      const requestedLimit = Number.parseInt(
        req.query.limit,
        10
      );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 20;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      const filter = {
        distributorId,
        firmId,

        /*
        * This includes:
        * - active accounts
        * - old accounts where isActive does not exist
        */
        isActive: {
          $ne: false,
        },
      };

      /*
      * Backend search.
      */
      if (search) {
        const escapedSearch =
          search.replace(
            /[.*+?^${}()|[\]\\]/g,
            "\\$&"
          );

        const searchRegex =
          new RegExp(
            escapedSearch,
            "i"
          );

        filter.$or = [
          {
            accountCode:
              searchRegex,
          },
          {
            accountName:
              searchRegex,
          },
          {
            contactPerson:
              searchRegex,
          },
          {
            mobileNo:
              searchRegex,
          },
          {
            phoneNo:
              searchRegex,
          },
          {
            emailId:
              searchRegex,
          },
          {
            town:
              searchRegex,
          },
          {
            state:
              searchRegex,
          },
          {
            pinCode:
              searchRegex,
          },
          {
            gstNo:
              searchRegex,
          },
          {
            tinNo:
              searchRegex,
          },
          {
            panNo:
              searchRegex,
          },
          {
            areaCode:
              searchRegex,
          },
          {
            address:
              searchRegex,
          },
        ];
      }

      /*
      * Count matching accounts.
      */
      const totalRecords =
        await Account.countDocuments(
          filter
        );

      const totalPages = Math.max(
        1,
        Math.ceil(
          totalRecords / limit
        )
      );

      /*
      * Prevent loading a page greater than
      * the available total pages.
      */
      const currentPage = Math.min(
        page,
        totalPages
      );

      const skip =
        (currentPage - 1) *
        limit;

      /*
      * Load only the current Account Master page.
      *
      * All fields are returned because the same row
      * is passed to the Edit Account form.
      */
      const accounts =
        await Account.find(filter)
          .select(
            [
              "accountCode",
              "accountName",
              "openingDate",
              "address",
              "town",
              "state",
              "pinCode",
              "phoneNo",
              "mobileNo",
              "emailId",
              "tinNo",
              "openingBal",
              "openingBalType",
              "openingTransactions",
              "contactPerson",
              "invType",
              "taxOn",
              "panNo",
              "foodLicense",
              "gstNo",
              "billToAdd1",
              "tanNo",
              "gstType",
              "gstDate",
              "gstClsDate",
              "add2",
              "tcsPercent",
              "allowInPurchase",
              "drugLicNo",
              "drugExpDate",
              "creditDays",
              "creditBills",
              "lockDays",
              "creditAmt",
              "blackListed",
              "lastBillDate",
              "lastInvoiceDate",
              "areaCode",
              "distributorId",
              "firmId",
              "firmName",
              "isActive",
              "createdAt",
              "updatedAt",
            ].join(" ")
          )
          .sort({
            accountName: 1,
            accountCode: 1,
            _id: 1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res.status(200).json({
        success: true,

        accounts,

        count: accounts.length,

        pagination: {
          currentPage,
          page: currentPage,
          limit,

          totalRecords,
          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip +
                accounts.length,
                totalRecords
              ),
        },
      });
    } catch (error) {
      console.error(
        "Account Master pagination error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Account Master",
        error: error.message,
      });
    }
  }
)

