app.get(
  "/api/other-accounts/list",
  ensureConnection,
  securityRouter.authorizeRequest(
    "master",
    "OTHER_ACCOUNT",
    "view"
  ),
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const requestedPage = Number.parseInt(
        req.query.page,
        10
      );

      const requestedLimit = Number.parseInt(
        req.query.limit,
        10
      );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 20;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      const filter = {
        distributorId,
        firmId,

        /*
        * Include active records and older records
        * where isActive may not exist.
        */
        isActive: {
          $ne: false,
        },
      };

      if (search) {
        const escapedSearch =
          search.replace(
            /[.*+?^${}()|[\]\\]/g,
            "\\$&"
          );

        const searchRegex =
          new RegExp(
            escapedSearch,
            "i"
          );

        filter.$or = [
          {
            accountCode:
              searchRegex,
          },
          {
            accountName:
              searchRegex,
          },
          {
            accountGroup:
              searchRegex,
          },
          {
            mobileNo:
              searchRegex,
          },
          {
            phoneNo:
              searchRegex,
          },
          {
            emailId:
              searchRegex,
          },
          {
            town:
              searchRegex,
          },
          {
            state:
              searchRegex,
          },
          {
            pinCode:
              searchRegex,
          },
          {
            gstNo:
              searchRegex,
          },
          {
            tinNo:
              searchRegex,
          },
          {
            panNo:
              searchRegex,
          },
          {
            bankAccountNo:
              searchRegex,
          },
          {
            ifscCode:
              searchRegex,
          },
          {
            branchName:
              searchRegex,
          },
          {
            remark:
              searchRegex,
          },
        ];
      }

      const totalRecords =
        await OtherAccount.countDocuments(
          filter
        );

      const totalPages = Math.max(
        1,
        Math.ceil(
          totalRecords / limit
        )
      );

      const currentPage = Math.min(
        page,
        totalPages
      );

      const skip =
        (currentPage - 1) *
        limit;

      const otherAccounts =
        await OtherAccount.find(filter)
          .sort({
            accountName: 1,
            accountCode: 1,
            _id: 1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res.status(200).json({
        success: true,

        otherAccounts,

        count:
          otherAccounts.length,

        pagination: {
          currentPage,
          page: currentPage,
          limit,

          totalRecords,
          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip +
                otherAccounts.length,
                totalRecords
              ),
        },
      });
    } catch (error) {
      console.error(
        "Other Account Master pagination error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Other Account Master",
        error: error.message,
      });
    }
  }
)

