app.get("/api/firms", ensureConnection, requireRoles("DISTRIBUTOR_ADMIN"), async (req, res) => {
  try {
    const distributorId = String(
      req.query.distributorId || ""
    ).trim();

    const search = String(
      req.query.search || ""
    ).trim();

    /*
    * Safe pagination values.
    *
    * Existing frontend calls without page and limit
    * will automatically load page 1 with 10 records.
    */
    const requestedPage = Number.parseInt(
      req.query.page,
      10
    );

    const requestedLimit = Number.parseInt(
      req.query.limit,
      10
    );

    const page =
      Number.isFinite(requestedPage) &&
        requestedPage > 0
        ? requestedPage
        : 1;

    /*
    * Maximum 100 records per request prevents
    * accidental very large API responses.
    */
    const limit =
      Number.isFinite(requestedLimit) &&
        requestedLimit > 0
        ? Math.min(requestedLimit, 100)
        : 10;

    if (!distributorId) {
      return res.status(400).json({
        success: false,
        message: "distributorId is required",
      });
    }

    /*
    * Escape special regular-expression characters
    * entered in the search box.
    */
    const escapedSearch = search.replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );

    const filter = {
      distributorId,
      isActive: true,
    };

    /*
    * Search is applied before count, skip and limit.
    * This means pagination works on filtered records.
    */
    if (escapedSearch) {
      const searchRegex = new RegExp(
        escapedSearch,
        "i"
      );

      filter.$or = [
        { firmCode: searchRegex },
        { firmName: searchRegex },
        { city: searchRegex },
        { state: searchRegex },
        { mobileNo: searchRegex },
        { phoneNo: searchRegex },
        { gstNo: searchRegex },
        { email: searchRegex },
      ];
    }

    /*
    * Count matching records first so frontend
    * can calculate pagination buttons.
    */
    const totalRecords =
      await Register.countDocuments(filter);

    const totalPages =
      Math.max(
        1,
        Math.ceil(totalRecords / limit)
      );

    /*
    * If the requested page is greater than the
    * available pages, return the last valid page.
    */
    const currentPage =
      Math.min(page, totalPages);

    const skip =
      (currentPage - 1) * limit;

    const firms = await Register.find(
      filter,
      {
        password: 0,
      }
    )
      .sort({
        firmName: 1,
        _id: 1,
      })
      .skip(skip)
      .limit(limit)
      .lean();

    return res.json({
      success: true,

      firms,

      pagination: {
        currentPage,
        page: currentPage,
        limit,
        totalRecords,
        totalPages,

        hasPreviousPage:
          currentPage > 1,

        hasNextPage:
          currentPage < totalPages,

        startRecord:
          totalRecords === 0
            ? 0
            : skip + 1,

        endRecord:
          totalRecords === 0
            ? 0
            : Math.min(
              skip + firms.length,
              totalRecords
            ),
      },
    });
  } catch (error) {
    console.error(
      "❌ Firm pagination load error:",
      error
    );

    return res.status(500).json({
      success: false,
      message: "Failed to fetch firms",
      error: error.message,
    });
  }
})

