app.get(
  "/api/gst/list",
  ensureConnection,
  securityRouter.authorizeRequest(
    "master",
    "GST",
    "view"
  ),
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(
          requestedPage
        ) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(
          requestedLimit
        ) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 10;

      if (
        !distributorId ||
        !firmId
      ) {
        return res
          .status(400)
          .json({
            success: false,
            message:
              "distributorId and firmId are required",
          });
      }

      const filter = {
        distributorId,
        firmId,

        /*
        * Include active GST records and
        * older records where isActive
        * may not be present.
        */
        isActive: {
          $ne: false,
        },
      };

      if (search) {
        const escapedSearch =
          search.replace(
            /[.*+?^${}()|[\]\\]/g,
            "\\$&"
          );

        const searchRegex =
          new RegExp(
            escapedSearch,
            "i"
          );

        const numericSearch =
          Number(search);

        filter.$or = [
          {
            gstCode:
              searchRegex,
          },
          {
            purchaseType:
              searchRegex,
          },
          {
            salesType:
              searchRegex,
          },
        ];

        /*
        * Allow exact search by GST percentage.
        * For example: 5, 12, 18 or 28.
        */
        if (
          Number.isFinite(
            numericSearch
          )
        ) {
          filter.$or.push({
            vatPercent:
              numericSearch,
          });
        }
      }

      const totalRecords =
        await GST.countDocuments(
          filter
        );

      const totalPages =
        Math.max(
          1,
          Math.ceil(
            totalRecords /
            limit
          )
        );

      /*
      * If requested page becomes invalid
      * after deletion, return the last
      * available page.
      */
      const currentPage =
        Math.min(
          page,
          totalPages
        );

      const skip =
        (currentPage - 1) *
        limit;

      const gstList =
        await GST.find(filter)
          .sort({
            vatPercent: 1,
            gstCode: 1,
            _id: 1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res
        .status(200)
        .json({
          success: true,

          gstList,

          count:
            gstList.length,

          pagination: {
            currentPage,
            page:
              currentPage,
            limit,

            totalRecords,
            totalPages,

            hasPreviousPage:
              currentPage > 1,

            hasNextPage:
              currentPage <
              totalPages,

            startRecord:
              totalRecords === 0
                ? 0
                : skip + 1,

            endRecord:
              totalRecords === 0
                ? 0
                : Math.min(
                  skip +
                  gstList.length,
                  totalRecords
                ),
          },
        });
    } catch (error) {
      console.error(
        "GST Master pagination error:",
        error
      );

      return res
        .status(500)
        .json({
          success: false,
          message:
            "Failed to load GST Master",
          error:
            error.message,
        });
    }
  }
)

