app.get(
  "/api/salesmen/list",
  ensureConnection,
  securityRouter.authorizeRequest(
    "master",
    "SALESMAN",
    "view"
  ),
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(
          requestedPage
        ) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(
          requestedLimit
        ) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 20;

      if (
        !distributorId ||
        !firmId
      ) {
        return res
          .status(400)
          .json({
            success: false,
            message:
              "distributorId and firmId are required",
          });
      }

      const filter = {
        distributorId,
        firmId,

        /*
        * Include active records and older
        * records where isActive may not exist.
        */
        isActive: {
          $ne: false,
        },
      };

      if (search) {
        const escapedSearch =
          search.replace(
            /[.*+?^${}()|[\]\\]/g,
            "\\$&"
          );

        const searchRegex =
          new RegExp(
            escapedSearch,
            "i"
          );

        filter.$or = [
          {
            salesmanCode:
              searchRegex,
          },
          {
            salesmanName:
              searchRegex,
          },
          {
            salesmanType:
              searchRegex,
          },
          {
            mobileNo:
              searchRegex,
          },
          {
            phoneNo:
              searchRegex,
          },
          {
            emailId:
              searchRegex,
          },
          {
            town:
              searchRegex,
          },
          {
            state:
              searchRegex,
          },
          {
            pinCode:
              searchRegex,
          },
          {
            qualification:
              searchRegex,
          },
          {
            reference:
              searchRegex,
          },
          {
            imeiNo:
              searchRegex,
          },
          {
            address:
              searchRegex,
          },
        ];
      }

      const totalRecords =
        await Salesman.countDocuments(
          filter
        );

      const totalPages =
        Math.max(
          1,
          Math.ceil(
            totalRecords /
            limit
          )
        );

      /*
      * If requested page becomes invalid
      * after deletion, return the last
      * available page.
      */
      const currentPage =
        Math.min(
          page,
          totalPages
        );

      const skip =
        (currentPage - 1) *
        limit;

      const salesmen =
        await Salesman.find(filter)
          .sort({
            salesmanName: 1,
            salesmanCode: 1,
            _id: 1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res
        .status(200)
        .json({
          success: true,

          salesmen,

          count:
            salesmen.length,

          pagination: {
            currentPage,
            page:
              currentPage,
            limit,

            totalRecords,
            totalPages,

            hasPreviousPage:
              currentPage > 1,

            hasNextPage:
              currentPage <
              totalPages,

            startRecord:
              totalRecords === 0
                ? 0
                : skip + 1,

            endRecord:
              totalRecords === 0
                ? 0
                : Math.min(
                  skip +
                  salesmen.length,
                  totalRecords
                ),
          },
        });
    } catch (error) {
      console.error(
        "Salesman Master pagination error:",
        error
      );

      return res
        .status(500)
        .json({
          success: false,
          message:
            "Failed to load Salesman Master",
          error:
            error.message,
        });
    }
  }
)

