  "/api/customer-banks/list",
  ensureConnection,
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const requestedPage = Number.parseInt(
        req.query.page,
        10
      );

      const requestedLimit = Number.parseInt(
        req.query.limit,
        10
      );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 20;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      const filter = {
        distributorId,
        firmId,

        /*
        * Include active records and old records
        * where isActive may not exist.
        */
        isActive: {
          $ne: false,
        },
      };

      if (search) {
        const escapedSearch =
          search.replace(
            /[.*+?^${}()|[\]\\]/g,
            "\\$&"
          );

        const searchRegex =
          new RegExp(
            escapedSearch,
            "i"
          );

        filter.$or = [
          {
            bankCode:
              searchRegex,
          },
          {
            bankName:
              searchRegex,
          },
          {
            accountNumber:
              searchRegex,
          },
          {
            ifscCode:
              searchRegex,
          },
          {
            branchName:
              searchRegex,
          },
          {
            accountType:
              searchRegex,
          },
          {
            clearingType:
              searchRegex,
          },
          {
            customerName:
              searchRegex,
          },
          {
            customerCode:
              searchRegex,
          },
          {
            mobileNo:
              searchRegex,
          },
          {
            emailId:
              searchRegex,
          },
          {
            upiId:
              searchRegex,
          },
          {
            beneficiaryName:
              searchRegex,
          },
          {
            swiftCode:
              searchRegex,
          },
          {
            micrCode:
              searchRegex,
          },
          {
            panNumber:
              searchRegex,
          },
          {
            remarks:
              searchRegex,
          },
        ];
      }

      const totalRecords =
        await CustomerBank.countDocuments(
          filter
        );

      const totalPages = Math.max(
        1,
        Math.ceil(
          totalRecords / limit
        )
      );

      /*
      * Keep the requested page inside
      * the currently available page range.
      */
      const currentPage = Math.min(
        page,
        totalPages
      );

      const skip =
        (currentPage - 1) *
        limit;

      const customerBanks =
        await CustomerBank.find(filter)
          .sort({
            bankName: 1,
            bankCode: 1,
            _id: 1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res.json({
        success: true,

        customerBanks,

        count:
          customerBanks.length,

        pagination: {
          currentPage,
          page: currentPage,
          limit,
          totalRecords,
          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip +
                customerBanks.length,
                totalRecords
              ),
        },
      });
    } catch (error) {
      console.error(
        "Customer Bank Master pagination error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Customer Bank Master",
        error:
          error.message,
      });
    }
  }
)

