        Number(
          item.quantity ??
          item.qty ??
          item.Qty ??
          0
        ) +
        Number(
          item.free ??
          item.Free ??
          0
        );

      const finalPurchaseRate = Number(
        item.purRate ??
        item.purchaseRate ??
        item.PurchaseRate ??
        item.pRate ??
        item.PRate ??
        item.prate ??
        item.selectedBatch?.purRate ??
        item.selectedBatch?.purchaseRate ??
        item.selectedBatch?.PurchaseRate ??
        item.selectedBatch?.pRate ??
        item.selectedBatch?.PRate ??
        0
      );

      const finalSalesRate = Number(
        item.salesRate ??
        item.SalesRate ??
        item.sRate ??
        item.SRate ??
        item.rate ??
        item.selectedBatch?.salesRate ??
        item.selectedBatch?.SalesRate ??
        item.selectedBatch?.sRate ??
        item.selectedBatch?.SRate ??
        0
      );

      if (!prodCode) {
        throw new Error(
          "Product code is missing in Purchase item."
        );
      }

      if (
        !Number.isFinite(mrp) ||
        mrp <= 0
      ) {
        throw new Error(
          `Valid MRP is required for product ${prodCode}.`
        );
      }

      if (
        !Number.isFinite(qty) ||
        qty <= 0
      ) {
        throw new Error(
          `Quantity is required for product ${prodCode}.`
        );
      }

      if (
        !Number.isFinite(finalPurchaseRate) ||
        finalPurchaseRate <= 0
      ) {
        throw new Error(
          `Purchase Rate is required for product ${prodCode}, batch ${batchNo}, MRP ${mrp}.`
        );
      }

      if (typeof process !== "undefined" && process.env.DEBUG_PURCHASE_STOCK === "true") {
        console.log(
          "PURCHASE STOCK SAVE DEBUG:",
          {
            prodCode,
            batchNo,
            mrp,
            qty,
            finalPurchaseRate,
            finalSalesRate,
            rawPurRate:
              item.purRate,
          }
        );
      }

      const updatedStock =
        await Stock.findOneAndUpdate(
          {
            distributorId,
            firmId,
            GDCode: gdCode,
            ProdCode: prodCode,
            Batch: batchNo,
            MRP: mrp,
          },
          {
            $setOnInsert: {
              distributorId,
              firmId,

              GDCode: gdCode,
              ProdCode: prodCode,
              Batch: batchNo,
              MRP: mrp,
            },

            $set: {
              firmName,
              isActive: true,

              ExpDt:
                item.expDate ||
                item.selectedBatch?.expDate ||
                null,

              MfgDt:
                item.mfgDate ||
                item.selectedBatch?.mfgDate ||
                null,

              PRate:
                finalPurchaseRate,

              SRate:
                finalSalesRate,

              IsLocked:
                item.isLocked ||
                item.selectedBatch?.isLocked ||
                "N",

              BoxPack: Number(
                item.boxPack ??
                item.BoxPack ??
                item.selectedBatch?.boxPack ??
                item.selectedBatch?.BoxPack ??
                1
              ),

              InBoxPack: Number(
                item.inBoxPack ??
                item.inboxPack ??
                item.InBoxPack ??
                item.selectedBatch?.inBoxPack ??
                item.selectedBatch?.inboxPack ??
                item.selectedBatch?.InBoxPack ??
                item.ratePerUnit ??
                1
              ),
            },

            $inc: {
              Qty: qty,
            },
          },
          {
            upsert: true,
            new: true,
            session,
            runValidators: true,
            setDefaultsOnInsert: true,
          }
        );

     
    }

    await commitTransactionReliably(session);

    const nextVouNo = assignedVouNo + 1;

    res.status(201).json({
      success: true,
      message: "Purchase saved successfully",
      data: {
        header: header[0],
      },
      nextVouNo,
    });
  } catch (error) {
    if (session.inTransaction()) await session.abortTransaction();

    console.error("Purchase save error:", error);

    if (error.code === 11000) {
      return res.status(409).json({
        success: false,
        message: "This purchase voucher number already exists for this series",
      });
    }

    res.status(error.statusCode === 400 ? 400 : 500).json({
      success: false,
      message: error.message || "Purchase save failed",
    });
  } finally {
    session.endSession();
  }
})

