        req.query.company || ""
      ).trim();

      const gdCode = String(
        req.query.gdCode ||
        req.query.godownCode ||
        ""
      ).trim();

      const godownName = String(
        req.query.godownName ||
        req.query.branchName ||
        ""
      ).trim();

      const invoiceNumber = String(
        req.query.invoiceNumber || ""
      ).trim();

      const minAmountText = String(
        req.query.minAmount || ""
      ).trim();

      const maxAmountText = String(
        req.query.maxAmount || ""
      ).trim();

      const requestedPage = Number.parseInt(
        req.query.page,
        10
      );

      const requestedLimit = Number.parseInt(
        req.query.limit,
        10
      );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(requestedLimit, 100)
          : 10;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      /*
      * Escape user-entered search text before
      * creating MongoDB regular expressions.
      */
      const escapeRegex = (value) =>
        String(value || "").replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      const containsRegex = (value) =>
        new RegExp(
          escapeRegex(value),
          "i"
        );

      const exactRegex = (value) =>
        new RegExp(
          `^${escapeRegex(value)}$`,
          "i"
        );

      const filter = {
        distributorId,
        firmId,

        /*
        * This permits old Purchase records where
        * isActive was not explicitly stored.
        */
        isActive: {
          $ne: false,
        },
      };

      /* =====================================================
        DATE FILTER
        ===================================================== */

      if (fromDate || toDate) {
        filter.invoiceDate = {};

        if (fromDate) {
          filter.invoiceDate.$gte =
            fromDate;
        }

        if (toDate) {
          filter.invoiceDate.$lte =
            toDate;
        }
      }

      /* =====================================================
        EXACT AND TEXT FILTERS
        ===================================================== */

      if (vouSer) {
        filter.vouSer =
          exactRegex(vouSer);
      }

      if (supplierCode) {
        filter.supplierCode =
          exactRegex(supplierCode);
      }

      if (supplierName) {
        filter.supplierName =
          containsRegex(supplierName);
      }

      if (company) {
        const companyRegex =
          containsRegex(company);

        /*
        * Purchase records store company in
        * companyCode and companyName.
        *
        * Some old records may contain company,
        * so that field is also checked.
        */
        filter.$and =
          filter.$and || [];

        filter.$and.push({
          $or: [
            {
              companyCode:
                companyRegex,
            },
            {
              companyName:
                companyRegex,
            },
            {
              company:
                companyRegex,
            },
          ],
        });
      }

      if (gdCode) {
        filter.gdCode =
          exactRegex(gdCode);
      }

      if (godownName) {
        filter.godownName =
          containsRegex(godownName);
      }

      if (invoiceNumber) {
        filter.invoiceNumber =
          containsRegex(invoiceNumber);
      }

      /* =====================================================
        AMOUNT RANGE
        ===================================================== */

      const minAmount =
        Number(minAmountText);

      const maxAmount =
        Number(maxAmountText);

      if (
        (
          minAmountText &&
          Number.isFinite(minAmount)
        ) ||
        (
          maxAmountText &&
          Number.isFinite(maxAmount)
        )
      ) {
        filter.netAmt = {};

        if (
          minAmountText &&
          Number.isFinite(minAmount)
        ) {
          filter.netAmt.$gte =
            minAmount;
        }

        if (
          maxAmountText &&
          Number.isFinite(maxAmount)
        ) {
          filter.netAmt.$lte =
            maxAmount;
        }
      }

      /* =====================================================
        GENERAL SEARCH
        ===================================================== */

      if (search) {
        const searchRegex =
          containsRegex(search);

        const numericSearch =
          Number(search);

        const searchConditions = [
          {
            vouSer:
              searchRegex,
          },
          {
            vno:
              searchRegex,
          },
          {
            supplierCode:
              searchRegex,
          },
          {
            supplierName:
              searchRegex,
          },
          {
            company:
              searchRegex,
          },
          {
            gdCode:
              searchRegex,
          },
          {
            godownName:
              searchRegex,
          },
          {
            invoiceNumber:
              searchRegex,
          },
          {
            narration:
              searchRegex,
          },
          {
            firmName:
              searchRegex,
          },
        ];

        /*
        * Voucher number and amount are numeric fields.
        * Search them only when entered text is numeric.
        */
        if (
          Number.isFinite(
            numericSearch
          )
        ) {
          searchConditions.push(
            {
              vouNo:
                numericSearch,
            },
            {
              netAmt:
                numericSearch,
            }
          );
        }

        filter.$and =
          filter.$and || [];

        filter.$and.push({
          $or:
            searchConditions,
        });
      }

      /* =====================================================
        COUNT ALL MATCHING RECORDS
        ===================================================== */

      const loadPurchasePage = (pageToLoad) => PurchaseHeader.find(filter)
        .select({ items: 0, historicalSnapshot: 0, desktopImportStockKeys: 0 })
        .sort({ invoiceDate: -1, vouNo: -1, _id: -1 })
        .skip((pageToLoad - 1) * limit)
        .limit(limit)
        .lean();
      const [totalRecords, requestedPurchases] = await Promise.all([
        PurchaseHeader.countDocuments(filter),
        loadPurchasePage(page),
      ]);

      const totalPages =
        Math.max(
          1,
          Math.ceil(
            totalRecords /
            limit
          )
        );

      /*
      * Protect against an invalid page after deletion.
      *
      * Example:
      * User deletes the only record on page 4.
      * The backend safely returns page 3.
      */
      const currentPage =
        Math.min(
          page,
          totalPages
        );

      const skip =
        (
          currentPage -
          1
        ) *
        limit;

      /* =====================================================
        LOAD ONLY THE CURRENT PAGE
        ===================================================== */

      // A list row excludes line items and snapshots. If deletion reduced the
      // page count, repeat only the page query for the corrected page.
      const purchases = currentPage === page
        ? requestedPurchases
        : await loadPurchasePage(currentPage);

      /* =====================================================
        RESPONSE
        ===================================================== */

      return res.json({
        success: true,

        purchases,

        count:
          purchases.length,

        pagination: {
          currentPage,

          page:
            currentPage,

          limit,

          totalRecords,

          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip +
                purchases.length,
                totalRecords
              ),
        },
      });
    } catch (error) {
      console.error(
        "Purchase list pagination error:",
        error
      );

      return res.status(500).json({
        success: false,

        message:
          "Failed to load purchase bills",

        error:
          error.message,
      });
    }
  }
)

