app.get(
  "/api/purchase/find-bill",
  ensureConnection,
  async (req, res) => {
    try {
      const {
        distributorId,
        firmId,
        vouSer = "",
        vouNo = "",
      } = req.query;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      if (
        vouNo === null ||
        vouNo === undefined ||
        String(vouNo).trim() === ""
      ) {
        return res.status(400).json({
          success: false,
          message:
            "Purchase Bill Number is required",
        });
      }

      const numericVouNo =
        Number(String(vouNo).trim());

      if (!Number.isFinite(numericVouNo)) {
        return res.status(400).json({
          success: false,
          message:
            "Purchase Bill Number must be numeric",
        });
      }

      const purchase = await PurchaseHeader.findOne({
        distributorId:
          String(distributorId).trim(),

        firmId:
          String(firmId).trim(),

        vouSer:
          String(vouSer || "").trim(),

        vouNo:
          numericVouNo,

        isActive: true,
      }).lean();

      if (!purchase) {
        return res.status(404).json({
          success: false,
          message:
            "Purchase Bill not found for the entered series and number.",
        });
      }

      const purchaseItems =
        Array.isArray(purchase.items)
          ? purchase.items
          : [];

      return res.json({
        success: true,

        purchase,
        bill: purchase,
        items: purchaseItems,

        count:
          purchaseItems.length,
      });
    } catch (error) {
      console.error(
        "Purchase Bill lookup error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Purchase Bill",
        error:
          error.message,
      });
    }
  }
)

