  "/api/sales",
  ensureConnection,
  securityRouter.authorizeRequest(
    "SALES",
    "SALES_BILLING",
    "add"
  ),
  async (req, res) => {
    const session =
      await mongoose.startSession();

    try {
      session.startTransaction();

      const {
        distributorId,
        firmId,
        firmName,

        BillDate,
        Godown,
        GDCode,

        CompanyCode,
        CompanyName,

        AreaCode,
        AreaName,

        PartyCode,
        PartyName,

        BillSeries = "",
        BillNo,
        BillType,
        SalesEntryType,
        DueDate,

        SalesmanCode,
        SalesmanName,

        Narration,

        items = [],
      } = req.body;

      /* =====================================================
         BASIC VALIDATION
      ===================================================== */

      if (
        !distributorId ||
        !firmId
      ) {
        throw new Error(
          "Distributor/Firm not found"
