app.get(
  "/api/sales/list",
  ensureConnection,
  securityRouter.authorizeRequest(
    "SALES",
    "SALES_BILLING",
    "view"
  ),
  async (req, res) => {
    try {
      /* =====================================================
        REQUEST PARAMETERS
        ===================================================== */

      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const fromDate = String(
        req.query.fromDate || ""
      ).trim();

      const toDate = String(
        req.query.toDate || ""
      ).trim();

      const billSeries = String(
        req.query.billSeries || ""
      ).trim();

      const billType = String(
        req.query.billType || ""
      ).trim();

      const salesEntryType = String(
        req.query.salesEntryType || ""
      ).trim();

      const companyCode = String(
        req.query.companyCode ||
        req.query.company ||
        ""
      ).trim();

      const partyCode = String(
        req.query.partyCode || ""
      ).trim();

      const partyName = String(
        req.query.partyName ||
        req.query.party ||
        ""
      ).trim();

      const salesmanCode = req.auth.role === "SALESMAN"
        ? (req.auth.salesmanCode || "__UNASSIGNED__")
        : String(req.query.salesmanCode || "").trim();

      const salesmanName = String(
        req.query.salesmanName ||
        req.query.salesman ||
        ""
      ).trim();

      const areaCode = String(
        req.query.areaCode || ""
      ).trim();

      const areaName = String(
        req.query.areaName ||
        req.query.area ||
        ""
      ).trim();

      const godownCode = String(
        req.query.godownCode ||
        req.query.gdCode ||
        ""
      ).trim();

      /*
      * Load filters.
      */
      const loadSeries = String(
        req.query.loadSeries || ""
      ).trim();

      const loadNoText = String(
        req.query.loadNo ||
        req.query.loadNumber ||
        ""
      ).trim();

      /*
      * User who added the Sales Bill.
      */
      const addUser = String(
        req.query.addUser ||
        req.query.createdBy ||
        ""
      ).trim();

      const paymentStatus = String(
        req.query.paymentStatus || ""
      ).trim();

      const minAmountText = String(
        req.query.minAmount || ""
      ).trim();

      const maxAmountText = String(
        req.query.maxAmount || ""
      ).trim();

      /* =====================================================
        PAGINATION PARAMETERS
        ===================================================== */

      const requestedPage = Number.parseInt(
        req.query.page,
        10
      );

      const requestedLimit = Number.parseInt(
        req.query.limit,
        10
      );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 20;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      /* =====================================================
        HELPER FUNCTIONS
        ===================================================== */

      const escapeRegex = (value) =>
        String(value || "").replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      /*
      * Creates an exact, case-insensitive
      * regular expression.
      *
      * Example:
      * CAD will match CAD, cad and Cad,
      * but it will not match CADBURY.
      */
      const createExactRegex = (value) =>
        new RegExp(
          `^${escapeRegex(
            String(value || "").trim()
          )}$`,
          "i"
        );

      /*
      * All independent field filters are added
      * to the same $and array.
      *
      * This permits:
      * Company + Area + Salesman + Load Series
      * + Load No + Party at the same time.
      */
      const andConditions = [];

      /* =====================================================
        BASE FILTER
        ===================================================== */

      const filter = {
        distributorId,
        firmId,

        /*
        * Include active records and old records
        * where isActive was never stored.
        */
        isActive: {
          $ne: false,
        },
      };

      if (salesEntryType) {
        const normalizedEntryType =
          normalizeSalesEntryType(
            salesEntryType
          );

        andConditions.push(
          buildSalesEntryTypeFilter(
            normalizedEntryType
          )
        );
      }

      /* =====================================================
        DATE FILTER
        ===================================================== */

      if (fromDate || toDate) {
        const billDateFilter = {};

        if (fromDate) {
          const startDate = new Date(
            `${fromDate}T00:00:00.000Z`
          );

          if (
            !Number.isNaN(
              startDate.getTime()
            )
          ) {
            billDateFilter.$gte =
              startDate;
          }
        }

        if (toDate) {
          const endDate = new Date(
            `${toDate}T23:59:59.999Z`
          );

          if (
            !Number.isNaN(
              endDate.getTime()
            )
          ) {
            billDateFilter.$lte =
              endDate;
          }
        }

        if (
          Object.keys(
            billDateFilter
          ).length > 0
        ) {
          andConditions.push({
            $or: [
              {
                BillDate:
                  billDateFilter,
              },
              {
                billDate:
                  billDateFilter,
              },
            ],
          });
        }
      }

      /* =====================================================
        BILL SERIES FILTER
        ===================================================== */

      if (billSeries) {
        const billSeriesRegex =
          createExactRegex(
            billSeries
          );

        andConditions.push({
          $or: [
            {
              BillSeries:
                billSeriesRegex,
            },
            {
              billSeries:
                billSeriesRegex,
            },
            {
              TrnSeries:
                billSeriesRegex,
            },
            {
              trnSeries:
                billSeriesRegex,
            },
          ],
        });
      }

      /* =====================================================
        BILL TYPE FILTER
        ===================================================== */

      if (billType) {
        const billTypeRegex =
          createExactRegex(
            billType
          );

        andConditions.push({
          $or: [
            {
              BillType:
                billTypeRegex,
            },
            {
              billType:
                billTypeRegex,
            },
            {
              InvoiceType:
                billTypeRegex,
            },
            {
              invoiceType:
                billTypeRegex,
            },
          ],
        });
      }

      /* =====================================================
        COMPANY FILTER
        ===================================================== */

      if (companyCode) {
        const companyRegex =
          createExactRegex(
            companyCode
          );

        andConditions.push({
          $or: [
            /*
            * Correct code fields.
            */
            {
              CompanyCode:
                companyRegex,
            },
            {
              companyCode:
                companyRegex,
            },
            {
              CompCode:
                companyRegex,
            },
            {
              compCode:
                companyRegex,
            },

            /*
            * Fallback for cases where the frontend
            * option contains a company name because
            * an old master has no company code.
            */
            {
              CompanyName:
                companyRegex,
            },
            {
              companyName:
                companyRegex,
            },
          ],
        });
      }

      /* =====================================================
        PARTY CODE FILTER
        ===================================================== */

      if (partyCode) {
        const partyCodeRegex =
          createExactRegex(
            partyCode
          );

        andConditions.push({
          $or: [
            {
              PartyCode:
                partyCodeRegex,
            },
            {
              partyCode:
                partyCodeRegex,
            },
            {
              AccountCode:
                partyCodeRegex,
            },
            {
              accountCode:
                partyCodeRegex,
            },
          ],
        });
      }

      /* =====================================================
        PARTY NAME FILTER
        ===================================================== */

      if (partyName) {
        const partyNameRegex =
          new RegExp(
            escapeRegex(
              partyName
            ),
            "i"
          );

        andConditions.push({
          $or: [
            {
              PartyName:
                partyNameRegex,
            },
            {
              partyName:
                partyNameRegex,
            },
            {
              party:
                partyNameRegex,
            },
            {
              AccountName:
                partyNameRegex,
            },
            {
              accountName:
                partyNameRegex,
            },
          ],
        });
      }

      /* =====================================================
        SALESMAN CODE FILTER
        ===================================================== */

      if (salesmanCode) {
        const salesmanCodeRegex =
          createExactRegex(
            salesmanCode
          );

        andConditions.push({
          $or: [
            {
              SalesmanCode:
                salesmanCodeRegex,
            },
            {
              salesmanCode:
                salesmanCodeRegex,
            },
            {
              SmanCode:
                salesmanCodeRegex,
            },
            {
              smanCode:
                salesmanCodeRegex,
            },

            /*
            * Fallback when the dropdown value is
            * salesman name rather than code.
            */
            {
              SalesmanName:
                salesmanCodeRegex,
            },
            {
              salesmanName:
                salesmanCodeRegex,
            },
          ],
        });
      }

      /* =====================================================
        SALESMAN NAME FILTER
        ===================================================== */

      if (salesmanName) {
        const salesmanNameRegex =
          new RegExp(
            escapeRegex(
              salesmanName
            ),
            "i"
          );

        andConditions.push({
          $or: [
            {
              SalesmanName:
                salesmanNameRegex,
            },
            {
              salesmanName:
                salesmanNameRegex,
            },
            {
              salesman:
                salesmanNameRegex,
            },
          ],
        });
      }

      /* =====================================================
        AREA CODE FILTER
        ===================================================== */

      if (areaCode) {
        const areaCodeRegex =
          createExactRegex(
            areaCode
          );

        andConditions.push({
          $or: [
            {
              AreaCode:
                areaCodeRegex,
            },
            {
              areaCode:
                areaCodeRegex,
            },

            /*
            * Fallback for old master records where
            * the dropdown value may contain the name.
            */
            {
              AreaName:
                areaCodeRegex,
            },
            {
              areaName:
                areaCodeRegex,
            },
          ],
        });
      }

      /* =====================================================
        AREA NAME FILTER
        ===================================================== */

      if (areaName) {
        const areaNameRegex =
          new RegExp(
            escapeRegex(
              areaName
            ),
            "i"
          );

        andConditions.push({
          $or: [
            {
              AreaName:
                areaNameRegex,
            },
            {
              areaName:
                areaNameRegex,
            },
            {
              area:
                areaNameRegex,
            },
          ],
        });
      }

      /* =====================================================
        GODOWN FILTER
        ===================================================== */

      if (godownCode) {
        const godownCodeRegex =
          createExactRegex(
            godownCode
          );

        andConditions.push({
          $or: [
            {
              GDCode:
                godownCodeRegex,
            },
            {
              gdCode:
                godownCodeRegex,
            },
            {
              GodownCode:
                godownCodeRegex,
            },
            {
              godownCode:
                godownCodeRegex,
            },
          ],
        });
      }

      /* =====================================================
        LOAD SERIES FILTER
        ===================================================== */

      if (loadSeries) {
        const loadSeriesRegex =
          createExactRegex(
            loadSeries
          );

        andConditions.push({
          $or: [
            {
              LoadSeries:
                loadSeriesRegex,
            },
            {
              loadSeries:
                loadSeriesRegex,
            },
            {
              LoadSer:
                loadSeriesRegex,
            },
            {
              loadSer:
                loadSeriesRegex,
            },
          ],
        });
      }

      /* =====================================================
        LOAD NUMBER FILTER
        ===================================================== */

      if (loadNoText) {
        const numericLoadNo =
          Number(loadNoText);

        const loadNoConditions = [
          /*
          * String representations.
          */
          {
            LoadNo:
              loadNoText,
          },
          {
            loadNo:
              loadNoText,
          },
          {
            LoadNumber:
              loadNoText,
          },
          {
            loadNumber:
              loadNoText,
          },
        ];

        /*
        * MongoDB documents may store LoadNo as
        * a numeric value instead of a string.
        */
        if (
          Number.isFinite(
            numericLoadNo
          )
        ) {
          loadNoConditions.push(
            {
              LoadNo:
                numericLoadNo,
            },
            {
              loadNo:
                numericLoadNo,
            },
            {
              LoadNumber:
                numericLoadNo,
            },
            {
              loadNumber:
                numericLoadNo,
            }
          );
        }

        andConditions.push({
          $or:
            loadNoConditions,
        });
      }

      /* =====================================================
        ADD USER FILTER
        ===================================================== */

      if (addUser) {
        const addUserRegex =
          createExactRegex(
            addUser
          );

        andConditions.push({
          $or: [
            {
              CreatedBy:
                addUserRegex,
            },
            {
              createdBy:
                addUserRegex,
            },
            {
              AddUser:
                addUserRegex,
            },
            {
              addUser:
                addUserRegex,
            },
            {
              UserName:
                addUserRegex,
            },
            {
              userName:
                addUserRegex,
            },
          ],
        });
      }

      /* =====================================================
        AMOUNT RANGE FILTER
        ===================================================== */

      const minAmount =
        Number(minAmountText);

      const maxAmount =
        Number(maxAmountText);

      if (
        minAmountText !== "" &&
        Number.isFinite(minAmount)
      ) {
        andConditions.push({
          $or: [
            {
              NetAmount: {
                $gte:
                  minAmount,
              },
            },
            {
              netAmount: {
                $gte:
                  minAmount,
              },
            },
            {
              amount: {
                $gte:
                  minAmount,
              },
            },
          ],
        });
      }

      if (
        maxAmountText !== "" &&
        Number.isFinite(maxAmount)
      ) {
        andConditions.push({
          $or: [
            {
              NetAmount: {
                $lte:
                  maxAmount,
              },
            },
            {
              netAmount: {
                $lte:
                  maxAmount,
              },
            },
            {
              amount: {
                $lte:
                  maxAmount,
              },
            },
          ],
        });
      }

      /* =====================================================
        PAYMENT STATUS FILTER
        ===================================================== */

      if (
        paymentStatus &&
        paymentStatus.toLowerCase() !==
        "all"
      ) {
        const normalizedStatus =
          paymentStatus.toLowerCase();

        if (
          normalizedStatus ===
          "paid"
        ) {
          andConditions.push({
            $or: [
              {
                PaymentStatus: {
                  $regex:
                    /^paid$/i,
                },
              },
              {
                paymentStatus: {
                  $regex:
                    /^paid$/i,
                },
              },
              {
                BalanceAmount: {
                  $lte: 0,
                },
              },
              {
                balanceAmount: {
                  $lte: 0,
                },
              },
            ],
          });
        } else if (
          normalizedStatus ===
          "pending"
        ) {
          andConditions.push({
            $or: [
              {
                PaymentStatus: {
                  $regex:
                    /pending|unpaid/i,
                },
              },
              {
                paymentStatus: {
                  $regex:
                    /pending|unpaid/i,
                },
              },
              {
                BalanceAmount: {
                  $gt: 0,
                },
              },
              {
                balanceAmount: {
                  $gt: 0,
                },
              },
            ],
          });
        } else if (
          normalizedStatus ===
          "partial"
        ) {
          andConditions.push({
            $or: [
              {
                PaymentStatus: {
                  $regex:
                    /partial/i,
                },
              },
              {
                paymentStatus: {
                  $regex:
                    /partial/i,
                },
              },
            ],
          });
        } else {
          const statusRegex =
            createExactRegex(
              paymentStatus
            );

          andConditions.push({
            $or: [
              {
                PaymentStatus:
                  statusRegex,
              },
              {
                paymentStatus:
                  statusRegex,
              },
            ],
          });
        }
      }

      /* =====================================================
        GENERAL SEARCH
        ===================================================== */

      if (search) {
        const searchRegex =
          new RegExp(
            escapeRegex(
              search
            ),
            "i"
          );

        const searchConditions = [
          {
            BillSeries:
              searchRegex,
          },
          {
            billSeries:
              searchRegex,
          },
          {
            PartyCode:
              searchRegex,
          },
          {
            partyCode:
              searchRegex,
          },
          {
            PartyName:
              searchRegex,
          },
          {
            partyName:
              searchRegex,
          },
          {
            CompanyCode:
              searchRegex,
          },
          {
            companyCode:
              searchRegex,
          },
          {
            CompanyName:
              searchRegex,
          },
          {
            companyName:
              searchRegex,
          },
          {
            SalesmanCode:
              searchRegex,
          },
          {
            salesmanCode:
              searchRegex,
          },
          {
            SalesmanName:
              searchRegex,
          },
          {
            salesmanName:
              searchRegex,
          },
          {
            AreaCode:
              searchRegex,
          },
          {
            areaCode:
              searchRegex,
          },
          {
            AreaName:
              searchRegex,
          },
          {
            areaName:
              searchRegex,
          },
          {
            GDCode:
              searchRegex,
          },
          {
            gdCode:
              searchRegex,
          },
          {
            Godown:
              searchRegex,
          },
          {
            godown:
              searchRegex,
          },
          {
            BillType:
              searchRegex,
          },
          {
            billType:
              searchRegex,
          },
          {
            LoadSeries:
              searchRegex,
          },
          {
            loadSeries:
              searchRegex,
          },
          {
            CreatedBy:
              searchRegex,
          },
          {
            createdBy:
              searchRegex,
          },
          {
            AddUser:
              searchRegex,
          },
          {
            addUser:
              searchRegex,
          },
          {
            Narration:
              searchRegex,
          },
          {
            narration:
              searchRegex,
          },
        ];

        /*
        * BillNo and LoadNo may be stored as numbers.
        */
        const numericSearch =
          Number(search);

        if (
          Number.isFinite(
            numericSearch
          )
        ) {
          searchConditions.push(
            {
              BillNo:
                numericSearch,
            },
            {
              billNo:
                numericSearch,
            },
            {
              LoadNo:
                numericSearch,
            },
            {
              loadNo:
                numericSearch,
            }
          );
        }

        /*
        * Also allow string LoadNo searches.
        */
        searchConditions.push(
          {
            LoadNo:
              search,
          },
          {
            loadNo:
              search,
          }
        );

        andConditions.push({
          $or:
            searchConditions,
        });
      }

      /* =====================================================
        APPLY ALL COMBINED CONDITIONS
        ===================================================== */

      if (
        andConditions.length > 0
      ) {
        filter.$and =
          andConditions;
      }

      /* =====================================================
        COUNT AND PAGINATION
        ===================================================== */

      const loadSalesPage = (pageToLoad) => SalesHeader.find(filter)
        .select({ items: 0, Items: 0 })
        .sort({ BillDate: -1, BillNo: -1, _id: -1 })
        .skip((pageToLoad - 1) * limit)
        .limit(limit)
        .lean();
      const [totalRecords, requestedSales] = await Promise.all([
        SalesHeader.countDocuments(filter),
        loadSalesPage(page),
      ]);

      const totalPages = Math.max(
        1,
        Math.ceil(
          totalRecords /
          limit
        )
      );

      /*
      * If a deletion reduced the number of pages,
      * move the request to the final available page.
      */
      const currentPage = Math.min(
        page,
        totalPages
      );

      const skip =
        (currentPage - 1) *
        limit;

      /* =====================================================
        LOAD SALES LIST
        ===================================================== */

      // Keep the existing page clamp after a deletion while loading the
      // normal requested page alongside the count.
      const sales = currentPage === page
        ? requestedSales
        : await loadSalesPage(currentPage);

      /* =====================================================
        RESPONSE
        ===================================================== */

      return res.json({
        success: true,

        sales,

        count:
          sales.length,

        pagination: {
          currentPage,
          page:
            currentPage,
          limit,
          totalRecords,
          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip +
                sales.length,
                totalRecords
              ),
        },

        appliedFilters: {
          search,
          fromDate,
          toDate,
          billSeries,
          billType,

          companyCode,

          partyCode,
          partyName,

          salesmanCode,
          salesmanName,

          areaCode,
          areaName,

          godownCode,

          loadSeries,
          loadNo:
            loadNoText,

          addUser,

          paymentStatus,

          minAmount:
            minAmountText,

          maxAmount:
            maxAmountText,
        },
      });
    } catch (error) {
      console.error(
        "Sales Billing paginated list error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Sales Billing list",
        error:
          error.message,
      });
    }
  }
