app.get(
  "/api/sales/list",
  ensureConnection,
  securityRouter.authorizeRequest(
    "SALES",
    "SALES_BILLING",
    "view"
  ),
  async (req, res) => {
    try {
      /* =====================================================
        REQUEST PARAMETERS
        ===================================================== */

      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const fromDate = String(
        req.query.fromDate || ""
      ).trim();

      const toDate = String(
        req.query.toDate || ""
      ).trim();

      const billSeries = String(
        req.query.billSeries || ""
      ).trim();

