          );

        andConditions.push(
          buildSalesEntryTypeFilter(
            normalizedEntryType
          )
        );
      }

      /* =====================================================
        DATE FILTER
        ===================================================== */

      if (fromDate || toDate) {
        const billDateFilter = {};

        if (fromDate) {
          const startDate = new Date(
            `${fromDate}T00:00:00.000Z`
          );

          if (
            !Number.isNaN(
              startDate.getTime()
            )
          ) {
            billDateFilter.$gte =
              startDate;
          }
        }

        if (toDate) {
          const endDate = new Date(
            `${toDate}T23:59:59.999Z`
          );

          if (
            !Number.isNaN(
              endDate.getTime()
            )
          ) {
            billDateFilter.$lte =
              endDate;
          }
        }

        if (
          Object.keys(
            billDateFilter
          ).length > 0
        ) {
          andConditions.push({
            $or: [
              {
                BillDate:
                  billDateFilter,
              },
              {
                billDate:
                  billDateFilter,
              },
            ],
          });
        }
      }

      /* =====================================================
        BILL SERIES FILTER
        ===================================================== */

      if (billSeries) {
        const billSeriesRegex =
          createExactRegex(
            billSeries
          );

        andConditions.push({
          $or: [
            {
              BillSeries:
                billSeriesRegex,
            },
            {
              billSeries:
                billSeriesRegex,
            },
            {
              TrnSeries:
                billSeriesRegex,
            },
            {
              trnSeries:
                billSeriesRegex,
            },
          ],
        });
      }

      /* =====================================================
        BILL TYPE FILTER
        ===================================================== */

      if (billType) {
        const billTypeRegex =
          createExactRegex(
            billType
          );

        andConditions.push({
          $or: [
            {
              BillType:
                billTypeRegex,
            },
            {
              billType:
                billTypeRegex,
            },
            {
              InvoiceType:
                billTypeRegex,
            },
            {
              invoiceType:
                billTypeRegex,
            },
          ],
        });
      }

      /* =====================================================
        COMPANY FILTER
        ===================================================== */

      if (companyCode) {
        const companyRegex =
          createExactRegex(
            companyCode
          );

        andConditions.push({
          $or: [
            /*
            * Correct code fields.
            */
            {
              CompanyCode:
                companyRegex,
            },
            {
              companyCode:
                companyRegex,
            },
            {
              CompCode:
                companyRegex,
            },
            {
              compCode:
                companyRegex,
            },

            /*
            * Fallback for cases where the frontend
            * option contains a company name because
            * an old master has no company code.
            */
            {
              CompanyName:
                companyRegex,
            },
            {
              companyName:
                companyRegex,
            },
          ],
        });
      }

      /* =====================================================
        PARTY CODE FILTER
        ===================================================== */

      if (partyCode) {
        const partyCodeRegex =
          createExactRegex(
            partyCode
          );

        andConditions.push({
          $or: [
            {
              PartyCode:
                partyCodeRegex,
            },
            {
              partyCode:
                partyCodeRegex,
            },
            {
              AccountCode:
                partyCodeRegex,
            },
            {
              accountCode:
                partyCodeRegex,
            },
          ],
        });
      }

      /* =====================================================
        PARTY NAME FILTER
        ===================================================== */

      if (partyName) {
        const partyNameRegex =
          new RegExp(
            escapeRegex(
              partyName
            ),
            "i"
          );

        andConditions.push({
          $or: [
            {
              PartyName:
                partyNameRegex,
            },
            {
              partyName:
                partyNameRegex,
            },
            {
              party:
                partyNameRegex,
            },
            {
              AccountName:
                partyNameRegex,
            },
            {
              accountName:
                partyNameRegex,
            },
          ],
        });
      }

      /* =====================================================
        SALESMAN CODE FILTER
        ===================================================== */

      if (salesmanCode) {
        const salesmanCodeRegex =
          createExactRegex(
            salesmanCode
          );

        andConditions.push({
          $or: [
            {
              SalesmanCode:
                salesmanCodeRegex,
            },
            {
              salesmanCode:
                salesmanCodeRegex,
            },
            {
              SmanCode:
                salesmanCodeRegex,
            },
            {
              smanCode:
                salesmanCodeRegex,
            },

            /*
            * Fallback when the dropdown value is
            * salesman name rather than code.
            */
            {
              SalesmanName:
                salesmanCodeRegex,
            },
            {
              salesmanName:
                salesmanCodeRegex,
            },
          ],
        });
      }

      /* =====================================================
        SALESMAN NAME FILTER
        ===================================================== */

      if (salesmanName) {
        const salesmanNameRegex =
          new RegExp(
            escapeRegex(
              salesmanName
            ),
            "i"
          );

        andConditions.push({
          $or: [
            {
              SalesmanName:
                salesmanNameRegex,
            },
            {
              salesmanName:
                salesmanNameRegex,
            },
            {
              salesman:
                salesmanNameRegex,
            },
          ],
        });
      }

      /* =====================================================
        AREA CODE FILTER
        ===================================================== */

      if (areaCode) {
        const areaCodeRegex =
          createExactRegex(
            areaCode
          );

        andConditions.push({
          $or: [
            {
              AreaCode:
                areaCodeRegex,
            },
            {
              areaCode:
                areaCodeRegex,
            },

            /*
            * Fallback for old master records where
            * the dropdown value may contain the name.
            */
            {
              AreaName:
                areaCodeRegex,
            },
            {
              areaName:
                areaCodeRegex,
            },
          ],
        });
      }

      /* =====================================================
        AREA NAME FILTER
        ===================================================== */

      if (areaName) {
        const areaNameRegex =
          new RegExp(
            escapeRegex(
              areaName
            ),
            "i"
          );

        andConditions.push({
          $or: [
            {
              AreaName:
                areaNameRegex,
            },
            {
              areaName:
                areaNameRegex,
            },
            {
              area:
                areaNameRegex,
            },
          ],
        });
      }

      /* =====================================================
        GODOWN FILTER
        ===================================================== */

      if (godownCode) {
        const godownCodeRegex =
          createExactRegex(
            godownCode
          );

        andConditions.push({
          $or: [
            {
              GDCode:
                godownCodeRegex,
            },
            {
              gdCode:
                godownCodeRegex,
            },
            {
              GodownCode:
                godownCodeRegex,
            },
            {
              godownCode:
                godownCodeRegex,
            },
          ],
        });
      }

      /* =====================================================
        LOAD SERIES FILTER
        ===================================================== */

      if (loadSeries) {
        const loadSeriesRegex =
          createExactRegex(
            loadSeries
          );

        andConditions.push({
          $or: [
            {
              LoadSeries:
                loadSeriesRegex,
            },
            {
              loadSeries:
                loadSeriesRegex,
            },
            {
              LoadSer:
                loadSeriesRegex,
            },
            {
              loadSer:
                loadSeriesRegex,
            },
          ],
        });
      }

      /* =====================================================
        LOAD NUMBER FILTER
        ===================================================== */

      if (loadNoText) {
        const numericLoadNo =
          Number(loadNoText);

        const loadNoConditions = [
          /*
          * String representations.
          */
          {
            LoadNo:
              loadNoText,
          },
          {
            loadNo:
              loadNoText,
          },
          {
            LoadNumber:
              loadNoText,
          },
          {
            loadNumber:
              loadNoText,
          },
        ];

        /*
        * MongoDB documents may store LoadNo as
        * a numeric value instead of a string.
        */
        if (
          Number.isFinite(
            numericLoadNo
          )
        ) {
          loadNoConditions.push(
            {
              LoadNo:
                numericLoadNo,
            },
            {
              loadNo:
                numericLoadNo,
            },
            {
              LoadNumber:
                numericLoadNo,
            },
            {
              loadNumber:
                numericLoadNo,
            }
          );
        }

        andConditions.push({
          $or:
            loadNoConditions,
        });
      }

      /* =====================================================
        ADD USER FILTER
        ===================================================== */

      if (addUser) {
        const addUserRegex =
          createExactRegex(
            addUser
          );

        andConditions.push({
          $or: [
            {
              CreatedBy:
                addUserRegex,
            },
            {
              createdBy:
                addUserRegex,
            },
            {
              AddUser:
                addUserRegex,
            },
            {
              addUser:
                addUserRegex,
            },
            {
              UserName:
                addUserRegex,
            },
            {
              userName:
                addUserRegex,
            },
          ],
        });
      }

      /* =====================================================
        AMOUNT RANGE FILTER
        ===================================================== */

      const minAmount =
        Number(minAmountText);

      const maxAmount =
        Number(maxAmountText);

      if (
        minAmountText !== "" &&
        Number.isFinite(minAmount)
      ) {
        andConditions.push({
          $or: [
            {
              NetAmount: {
                $gte:
                  minAmount,
              },
            },
            {
              netAmount: {
                $gte:
                  minAmount,
              },
            },
            {
              amount: {
                $gte:
                  minAmount,
              },
            },
          ],
        });
      }

      if (
        maxAmountText !== "" &&
        Number.isFinite(maxAmount)
      ) {
        andConditions.push({
          $or: [
            {
              NetAmount: {
                $lte:
                  maxAmount,
              },
            },
            {
              netAmount: {
                $lte:
                  maxAmount,
              },
            },
            {
              amount: {
                $lte:
                  maxAmount,
              },
            },
          ],
        });
      }

      /* =====================================================
