              },
              {
                balanceAmount: {
                  $lte: 0,
                },
              },
            ],
          });
        } else if (
          normalizedStatus ===
          "pending"
        ) {
          andConditions.push({
            $or: [
              {
                PaymentStatus: {
                  $regex:
                    /pending|unpaid/i,
