            }
          );
        }

        /*
        * Also allow string LoadNo searches.
        */
        searchConditions.push(
          {
            LoadNo:
              search,
          },
          {
            loadNo:
              search,
          }
        );

        andConditions.push({
          $or:
            searchConditions,
        });
      }

      /* =====================================================
        APPLY ALL COMBINED CONDITIONS
        ===================================================== */

      if (
        andConditions.length > 0
      ) {
        filter.$and =
          andConditions;
      }

      /* =====================================================
