        1,
        Math.ceil(
          totalRecords /
          limit
        )
      );

      /*
      * If a deletion reduced the number of pages,
      * move the request to the final available page.
      */
      const currentPage = Math.min(
        page,
        totalPages
      );

      const skip =
        (currentPage - 1) *
        limit;

      /* =====================================================
        LOAD SALES LIST
        ===================================================== */

      // Keep the existing page clamp after a deletion while loading the
