app.get(
  "/api/stock/credit-note-batches",
  ensureConnection,
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const gdCode = String(
        req.query.gdCode || ""
      ).trim();

      const prodCode = String(
        req.query.prodCode || ""
      ).trim();

      const trnType = String(
        req.query.trnType || "GDR"
      )
        .trim()
        .toUpperCase();

      const includeLocked = String(
        req.query.includeLocked || "N"
      )
        .trim()
        .toUpperCase();

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      if (!prodCode) {
        return res.status(400).json({
          success: false,
          message: "Product code is required",
        });
      }

      if (!["GDR", "DGR"].includes(trnType)) {
        return res.status(400).json({
          success: false,
          message:
            "Transaction type must be GDR or DGR",
        });
      }

      const StockCollection =
        trnType === "DGR"
          ? DamStock
          : Stock;

      const filter = {
        distributorId,
        firmId,
        ProdCode: prodCode,

        $and: [
          {
            $or: [
              { isActive: true },
              { isActive: { $exists: false } },
            ],
          },
        ],
      };

      /*
      * Apply godown only when it is available.
      * This also supports old stock records where GDCode
      * may not have been stored.
      */
      if (gdCode) {
        filter.$and.push({
          $or: [
            { GDCode: gdCode },
            { GDCode: "" },
            { GDCode: null },
            { GDCode: { $exists: false } },
          ],
        });
      }

      if (includeLocked !== "Y") {
        filter.$and.push({
          $or: [
            { IsLocked: { $ne: "Y" } },
            { IsLocked: { $exists: false } },
          ],
        });
      }

      const rows = await StockCollection.find(
        filter
      )
        .sort({
          ExpDt: 1,
          Batch: 1,
          MRP: 1,
        })
        .lean();

      const batches = rows.map((stockRow) => ({
        id: stockRow._id,

        batchNo:
          stockRow.Batch ||
          stockRow.batchNo ||
          ".",

        batch:
          stockRow.Batch ||
          stockRow.batchNo ||
          ".",

        mrp: Number(
          stockRow.MRP ||
          stockRow.mrp ||
          0
        ),

        salesRate: Number(
          stockRow.SRate ||
          stockRow.salesRate ||
          stockRow.Rate ||
          stockRow.rate ||
          0
        ),

        sRate: Number(
          stockRow.SRate ||
          stockRow.salesRate ||
          stockRow.Rate ||
          stockRow.rate ||
          0
        ),

        purchaseRate: Number(
          stockRow.PRate ||
          stockRow.purchaseRate ||
          0
        ),

        stockQty: Number(
          stockRow.Qty ||
          stockRow.stockQty ||
          0
        ),

        qty: Number(
          stockRow.Qty ||
          stockRow.stockQty ||
          0
        ),

        gdCode:
          stockRow.GDCode || "",

        prodCode:
          stockRow.ProdCode || "",

        mfgDate:
          stockRow.MfgDt ||
          stockRow.mfgDate ||
          "",

        expDate:
          stockRow.ExpDt ||
          stockRow.expDate ||
          "",

        boxPack: Number(
          stockRow.BoxPack || 1
        ),

        inboxPack: Number(
          stockRow.InBoxPack || 1
        ),

        isLocked:
          stockRow.IsLocked || "N",

        sourceCollection:
          trnType === "DGR"
            ? "MAS_DAMSTOCK"
            : "MAS_STOCK",
      }));

      res.json({
        success: true,
        transactionType: trnType,

        sourceCollection:
          trnType === "DGR"
            ? "MAS_DAMSTOCK"
            : "MAS_STOCK",

        count: batches.length,
        batches,
      });
    } catch (error) {
      console.error(
        "Credit Note batch load error:",
        error
      );

      res.status(500).json({
        success: false,
        message:
          "Failed to load Credit Note batches",
        error: error.message,
      });
    }
  }
)

