app.get(
  "/api/quotation/list",
  ensureConnection,
  securityRouter.authorizeRequest("SALES", "QUOTATION", "view"),
  async (req, res) => {
    try {
      /* =====================================================
        REQUEST PARAMETERS
        ===================================================== */

      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const fromDate = String(
        req.query.fromDate || ""
      ).trim();

      const toDate = String(
        req.query.toDate || ""
      ).trim();

      const billSeries = String(
        req.query.billSeries || ""
      ).trim();

      const billType = String(
        req.query.billType || ""
      ).trim();

      const companyCode = String(
        req.query.companyCode ||
        req.query.company ||
        ""
      ).trim();

      const partyCode = String(
        req.query.partyCode || ""
      ).trim();

      const partyName = String(
        req.query.partyName ||
        req.query.party ||
        ""
      ).trim();

      const salesmanCode = String(
        req.query.salesmanCode || ""
      ).trim();

      const salesmanName = String(
        req.query.salesmanName ||
        req.query.salesman ||
        ""
      ).trim();

      const areaCode = String(
        req.query.areaCode || ""
      ).trim();

      const areaName = String(
        req.query.areaName ||
        req.query.area ||
        ""
      ).trim();

      const godownCode = String(
        req.query.godownCode ||
        req.query.gdCode ||
        ""
      ).trim();

      const addUser = String(
        req.query.addUser ||
        req.query.createdBy ||
        ""
      ).trim();

      const minAmountText = String(
        req.query.minAmount || ""
      ).trim();

      const maxAmountText = String(
        req.query.maxAmount || ""
      ).trim();

      /* =====================================================
        PAGINATION
        ===================================================== */

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 20;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      /* =====================================================
        HELPERS
        ===================================================== */

      const escapeRegex = (value) =>
        String(value || "").replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      const exactRegex = (value) =>
        new RegExp(
          `^${escapeRegex(
            String(value || "").trim()
          )}$`,
          "i"
        );

      const andConditions = [];

      /* =====================================================
        BASE FILTER
        ===================================================== */

      const filter = {
        distributorId,
        firmId,

        /*
        * Include active quotations and older records
        * where isActive is not present.
        */
        isActive: {
          $ne: false,
        },
      };

      /* =====================================================
        DATE FILTER
        ===================================================== */

      if (fromDate || toDate) {
        const dateCondition = {};

        if (fromDate) {
          const startDate = new Date(
            `${fromDate}T00:00:00.000Z`
          );

          if (
            !Number.isNaN(
              startDate.getTime()
            )
          ) {
            dateCondition.$gte =
              startDate;
          }
        }

        if (toDate) {
          const endDate = new Date(
            `${toDate}T23:59:59.999Z`
          );

          if (
            !Number.isNaN(
              endDate.getTime()
            )
          ) {
