      }

      /* =====================================================
        COUNT RECORDS
        ===================================================== */

      const totalRecords =
        await QuotationHeader.countDocuments(
          filter
        );

      const totalPages = Math.max(
        1,
        Math.ceil(
          totalRecords /
          limit
        )
      );

      const currentPage = Math.min(
        page,
        totalPages
      );

      const skip =
        (currentPage - 1) *
        limit;

      /* =====================================================
        LOAD CURRENT PAGE
        ===================================================== */

      const quotations =
        await QuotationHeader.find(
          filter
        )
          /*
          * Do not return quotation product items
          * in the list API.
          */
          .select({
            items: 0,
            Items: 0,
          })
          .sort({
            BillDate: -1,
            BillNo: -1,
            _id: -1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      /* =====================================================
        RESPONSE
        ===================================================== */

      return res.json({
        success: true,

        quotations,

        count:
          quotations.length,

        pagination: {
          currentPage,
          page:
            currentPage,
          limit,
          totalRecords,
          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip +
                quotations.length,
                totalRecords
              ),
        },

        appliedFilters: {
          search,
          fromDate,
          toDate,
          billSeries,
          billType,

          companyCode,

          partyCode,
          partyName,

          salesmanCode,
          salesmanName,

          areaCode,
          areaName,

          godownCode,
          addUser,

          minAmount:
            minAmountText,

          maxAmount:
            maxAmountText,
        },
      });
    } catch (error) {
      console.error(
        "Quotation paginated list error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Quotation list",
        error:
          error.message,
      });
    }
  }
)

