app.get(
  "/api/create-load/sales-bills",
  ensureConnection,
  async (req, res) => {
    try {
      const {
        distributorId,
        firmId,
        company = "",
        salesmen = "",
        fromDate = "",
        toDate = "",
        editLoadId = "",
      } = req.query;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      if (
        !company ||
        !salesmen ||
        !fromDate ||
        !toDate
      ) {
        return res.json({
          success: true,
          count: 0,
          bills: [],
        });
      }

      const salesmanList =
        String(salesmen)
          .split(",")
          .map((value) =>
            value.trim()
          )
          .filter(Boolean);

      const companyValue =
        String(company).trim();

      let editingLoad = null;

      if (
        editLoadId &&
        mongoose.Types.ObjectId.isValid(
          editLoadId
        )
      ) {
        editingLoad =
          await LoadHeader.findOne({
            _id: editLoadId,
            DistributorId:
              distributorId,
            FirmId: firmId,
            IsCancelled: {
              $ne: true,
            },
          }).lean();
      }

      /*
      * Normal create:
      * only bills not assigned to any load.
      *
      * Edit:
      * unloaded bills plus bills assigned to
      * the load currently being edited.
      */
      const loadAvailabilityConditions = [
        {
          IsLoaded: {
            $ne: true,
          },
        },
        {
          LoadNo: null,
        },
        {
          LoadNo: {
            $exists: false,
          },
        },
        {
          LoadNo: 0,
        },
      ];

      if (editingLoad) {
        loadAvailabilityConditions.push({
          LoadSeries:
            editingLoad.LoadSeries,
          LoadNo:
            Number(
              editingLoad.LoadNo
            ),
        });
      }

      const filter = {
        distributorId,
        firmId,
        isActive: true,

        BillDate: {
          $gte:
            String(fromDate).trim(),
          $lte:
            String(toDate).trim(),
        },

        $and: [
          {
            $or: [
              {
                CompanyName:
                  companyValue,
              },
              {
                CompanyCode:
                  companyValue,
              },
            ],
          },

          {
            $or:
              loadAvailabilityConditions,
          },
        ],
      };

      if (salesmanList.length > 0) {
        filter.$and.push({
          $or: [
            {
              SalesmanName: {
                $in: salesmanList,
              },
            },
            {
              SalesmanCode: {
                $in: salesmanList,
              },
            },
          ],
        });
      }

      const bills =
        await SalesHeader.find(filter)
          .sort({
            BillDate: 1,
            BillNo: 1,
          })
          .lean();

      res.json({
        success: true,
        count: bills.length,
        bills,
      });
    } catch (error) {
      console.error(
        "Create Load sales bills error:",
        error
      );

      res.status(500).json({
        success: false,
        message:
          "Failed to load sales bills for create load",
        error: error.message,
      });
    }
  }
)

