app.put(
  "/api/create-load/:id",
  ensureConnection,
  securityRouter.authorizeRequest("SALES", "CREATE_LOAD", "edit"),
  async (req, res) => {
    const session =
      await mongoose.startSession();

    try {
      session.startTransaction();

      const { id } = req.params;

      const {
        LoadSeries = "",
        LoadNo,
        LoadDate = "",

        CompanyCode = "",
        CompanyName = "",

        DeliveryBoyCode = "",
        DeliveryBoyName = "",
        DeliveryBy = "",

        VehicleNo = "",
        DriverMobile = "",

        SalesmanCode = "",
        SalesmanName = "",

        SelectedSalesmen = [],
        SelectedAreas = [],

        BillFromDate = "",
        BillToDate = "",

        Narration = "",
        Remarks = "",

        Bills = [],

        TotalBills = 0,
        TotalParties = 0,
        TotalSalesmen = 0,
        TotalAreas = 0,
        TotalAmount = 0,

        LoadSummary = {},

        DistributorId,
        FirmId,
        FirmName = "",

        UpdatedBy = "ADMIN",
      } = req.body;

      if (!DistributorId || !FirmId) {
        throw new Error(
          "Distributor/Firm not found"
        );
      }

      if (
        !mongoose.Types.ObjectId.isValid(id)
      ) {
        throw new Error(
          "Invalid Create Load ID"
        );
      }

      const existingLoad =
        await LoadHeader.findOne({
          _id: id,
          DistributorId,
          FirmId,
          IsCancelled: {
            $ne: true,
          },
        }).session(session);

      if (!existingLoad) {
        throw new Error(
          "Create Load not found"
        );
      }

      const cleanLoadSeries =
        String(LoadSeries).trim();

      const cleanLoadNo =
        Number(LoadNo || 0);

      if (!cleanLoadSeries) {
        throw new Error(
          "Load Series is required"
        );
      }

      if (!cleanLoadNo) {
        throw new Error(
          "Load No is required"
        );
      }

      if (
        !Array.isArray(Bills) ||
        Bills.length === 0
      ) {
        throw new Error(
          "Select at least one bill"
        );
      }

      /*
      * Prevent duplicate Load Series + Load No,
      * excluding the current record.
      */
      const duplicateLoad =
        await LoadHeader.findOne({
          _id: {
            $ne: id,
          },

          DistributorId,
          FirmId,

          LoadSeries:
            cleanLoadSeries,

          LoadNo:
            cleanLoadNo,

          IsCancelled: {
            $ne: true,
          },
        }).session(session);

      if (duplicateLoad) {
        throw new Error(
          "This Load Series and Load No already exists."
        );
      }

      const oldBillConditions = (
        existingLoad.Bills || []
      )
        .map(buildCreateLoadBillCondition)
        .filter(Boolean);

      /*
      * First release every bill from the old load.
      */
      if (
        oldBillConditions.length > 0
      ) {
        await SalesHeader.updateMany(
          {
            distributorId:
              DistributorId,

            firmId: FirmId,

            isActive: true,

            $or:
              oldBillConditions,
          },

          {
            $set: {
              IsLoaded: false,
              LoadSeries: "",
              LoadNo: null,
            },
          },

          {
            session,
          }
        );
      }

      const cleanBills = Bills.map(
        (bill, index) => {
          const salesBillId = String(
            bill.SalesBillId ||
            bill.salesBillId ||
            bill._id ||
            ""
          ).trim();

          const billSeries = String(
            bill.BillSeries ??
            bill.Series ??
            bill.billSeries ??
            ""
          ).trim();

          return {
            ...bill,

            Sl: index + 1,
            Selected: true,

            SalesBillId:
              salesBillId,

            BillDate:
              bill.BillDate ||
              bill.billDate ||
              "",

            Series: billSeries,
            BillSeries: billSeries,

            BillNo: Number(
              bill.BillNo ??
              bill.billNo ??
              0
            ),

            BillType:
              bill.BillType ||
              bill.billType ||
              "Credit",

            PartyCode:
              bill.PartyCode ||
              bill.partyCode ||
              "",

            PartyName:
              bill.PartyName ||
              bill.partyName ||
              "",

            SalesmanCode:
              bill.SalesmanCode ||
              bill.salesmanCode ||
              "",

            SalesmanName:
              bill.SalesmanName ||
              bill.salesmanName ||
              bill.salesman ||
              "",

            AreaCode:
              bill.AreaCode ||
              bill.areaCode ||
              "",

            AreaName:
              bill.AreaName ||
              bill.areaName ||
              bill.area ||
              "",

            Amount: Number(
              bill.Amount ??
              bill.amount ??
              bill.billAmount ??
              0
            ),
          };
        }
      ).filter((bill) => {
        const hasMongoId =
          bill.SalesBillId &&
          mongoose.Types.ObjectId.isValid(
            bill.SalesBillId
          );

        const hasBillNo =
          Number(bill.BillNo || 0) > 0;

        return hasMongoId || hasBillNo;
      });

      if (cleanBills.length === 0) {
        throw new Error(
          "No valid bill found in the load"
        );
      }

      const billConditions = cleanBills
        .map(buildCreateLoadBillCondition)
        .filter(Boolean);

      if (billConditions.length === 0) {
        throw new Error(
          "Selected bills do not contain a valid Bill No or Sales Bill ID"
        );
      }
      /*
      * Ensure another active load has not taken
      * one of these bills.
      */
      const conflictingBills =
        await SalesHeader.find({
          distributorId:
            DistributorId,

          firmId: FirmId,

          isActive: true,

          IsLoaded: true,

          $or:
            billConditions,

          $nor: [
            {
              LoadSeries:
                existingLoad.LoadSeries,

              LoadNo:
                existingLoad.LoadNo,
            },
          ],
        })
          .session(session)
          .lean();

      if (conflictingBills.length > 0) {
        throw new Error(
          "One or more selected bills are already assigned to another load."
        );
      }

      const uniqueParties =
        new Set(
          cleanBills
            .map(
              (bill) =>
                bill.PartyCode ||
                bill.PartyName
            )
            .filter(Boolean)
        );

      const uniqueSalesmen =
        new Set(
          cleanBills
            .map(
              (bill) =>
                bill.SalesmanCode ||
                bill.SalesmanName
            )
            .filter(Boolean)
        );

      const uniqueAreas =
        new Set(
          cleanBills
            .map(
              (bill) =>
                bill.AreaCode ||
                bill.AreaName
            )
            .filter(Boolean)
        );

      const calculatedTotal =
        cleanBills.reduce(
          (total, bill) =>
            total +
            Number(
              bill.Amount || 0
            ),
          0
        );

      const finalSummary = {
        totalBills:
          cleanBills.length,

        totalParties:
          uniqueParties.size,

        totalSalesmen:
          uniqueSalesmen.size,

        totalAreas:
          uniqueAreas.size,

        totalAmount:
          calculatedTotal,
      };

      const updatedLoad =
        await LoadHeader.findOneAndUpdate(
          { _id: id, DistributorId: req.auth.distributorId, FirmId: req.auth.firmId },

          {
            $set: {
              LoadSeries:
                cleanLoadSeries,

              LoadNo:
                cleanLoadNo,

              LoadDate,

              CompanyCode:
                String(
                  CompanyCode || ""
                ).trim(),

              CompanyName:
                String(
                  CompanyName || ""
                ).trim(),

              DeliveryBoyCode:
                String(
                  DeliveryBoyCode || ""
                ).trim(),

              DeliveryBoyName:
                String(
                  DeliveryBoyName || ""
                ).trim(),

              DeliveryBy:
                String(
                  DeliveryBy ||
                  DeliveryBoyName ||
                  ""
                ).trim(),

              VehicleNo:
                String(
                  VehicleNo || ""
                )
                  .trim()
                  .toUpperCase(),

              DriverMobile:
                String(
                  DriverMobile || ""
                ).trim(),

              SalesmanCode:
                String(
                  SalesmanCode || ""
                ).trim(),

              SalesmanName:
                String(
                  SalesmanName || ""
                ).trim(),

              SelectedSalesmen:
                Array.isArray(
                  SelectedSalesmen
                )
                  ? SelectedSalesmen
                  : [],

              SelectedAreas:
                Array.isArray(
                  SelectedAreas
                )
                  ? SelectedAreas
                  : [],

              BillFromDate,
