              Narration:
                String(
                  Narration || ""
                ).trim(),

              Remarks:
                String(
                  Remarks || ""
                ).trim(),

              Bills:
                cleanBills,

              TotalBills:
                finalSummary.totalBills,

              TotalParties:
                finalSummary.totalParties,

              TotalSalesmen:
