app.get(
  "/api/create-load/list",
  ensureConnection,
  securityRouter.authorizeRequest("SALES", "CREATE_LOAD", "view"),
  async (req, res) => {
    try {
      /* =====================================================
        REQUEST VALUES
        ===================================================== */

      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const fromDate = String(
        req.query.fromDate || ""
      ).trim();

      const toDate = String(
        req.query.toDate || ""
      ).trim();

      const loadSeries = String(
        req.query.loadSeries || ""
      ).trim();

      const loadNoText = String(
        req.query.loadNo || ""
      ).trim();

      const companyCode = String(
        req.query.companyCode ||
        req.query.company ||
        ""
      ).trim();

      const salesmanCode = String(
        req.query.salesmanCode ||
        req.query.salesman ||
        ""
      ).trim();

      const deliveryBy = String(
        req.query.deliveryBy ||
        req.query.deliveryBoy ||
        ""
      ).trim();

      const vehicleNo = String(
        req.query.vehicleNo || ""
      ).trim();

      const status = String(
        req.query.status || ""
      ).trim();

      const createdBy = String(
        req.query.createdBy ||
        req.query.addUser ||
        ""
      ).trim();

      const minAmountText = String(
        req.query.minAmount || ""
      ).trim();

      const maxAmountText = String(
        req.query.maxAmount || ""
      ).trim();

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 10;

      if (
        !distributorId ||
        !firmId
      ) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      /* =====================================================
        REGEX HELPERS
        ===================================================== */

      const escapeRegex = (value) =>
        String(value || "").replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      const createExactRegex = (
        value
      ) =>
        new RegExp(
          `^${escapeRegex(
            String(value || "").trim()
          )}$`,
          "i"
        );

      const createContainsRegex = (
        value
      ) =>
        new RegExp(
          escapeRegex(
            String(value || "").trim()
          ),
          "i"
        );

      /* =====================================================
        BASE FILTER
        ===================================================== */

      const filter = {
        DistributorId:
          distributorId,

        FirmId:
          firmId,

        IsCancelled: {
          $ne: true,
        },
      };

      const andConditions = [];

      /* =====================================================
        LOAD DATE
        ===================================================== */

      if (fromDate || toDate) {
        const dateCondition = {};

        if (fromDate) {
          const startDate =
            new Date(
              `${fromDate}T00:00:00.000Z`
            );

          if (
            !Number.isNaN(
              startDate.getTime()
            )
          ) {
            dateCondition.$gte =
              startDate;
          }
        }

        if (toDate) {
          const endDate =
            new Date(
              `${toDate}T23:59:59.999Z`
            );

          if (
            !Number.isNaN(
              endDate.getTime()
            )
          ) {
            dateCondition.$lte =
              endDate;
          }
        }

        if (
          Object.keys(
            dateCondition
          ).length > 0
        ) {
          andConditions.push({
            $or: [
              {
                LoadDate:
                  dateCondition,
              },
              {
                loadDate:
                  dateCondition,
              },
            ],
          });
        }
      }

      /* =====================================================
        LOAD SERIES
        ===================================================== */

      if (loadSeries) {
        const regex =
          createExactRegex(
            loadSeries
          );

        andConditions.push({
          $or: [
            {
              LoadSeries:
                regex,
            },
            {
              loadSeries:
                regex,
            },
          ],
        });
      }

      /* =====================================================
        LOAD NUMBER
        ===================================================== */

      if (loadNoText) {
        const numericLoadNo =
          Number(loadNoText);

        const conditions = [
          {
            LoadNo:
              createExactRegex(
                loadNoText
              ),
          },
          {
            loadNo:
              createExactRegex(
                loadNoText
              ),
          },
        ];

        if (
          Number.isFinite(
            numericLoadNo
          )
        ) {
          conditions.push(
            {
              LoadNo:
                numericLoadNo,
            },
            {
              loadNo:
                numericLoadNo,
            }
          );
        }

        andConditions.push({
          $or:
            conditions,
        });
      }

      /* =====================================================
        COMPANY
        ===================================================== */

      if (companyCode) {
        const regex =
          createExactRegex(
            companyCode
          );

        andConditions.push({
          $or: [
            {
              CompanyCode:
                regex,
            },
            {
              companyCode:
                regex,
            },
            {
              CompanyName:
                regex,
            },
            {
              companyName:
                regex,
            },
          ],
        });
      }

      /* =====================================================
        SALESMAN
        ===================================================== */

      if (salesmanCode) {
        const exactRegex =
          createExactRegex(
            salesmanCode
          );

        const containsRegex =
          createContainsRegex(
            salesmanCode
          );

        andConditions.push({
          $or: [
            {
              SalesmanCode:
                containsRegex,
            },
            {
              salesmanCode:
                containsRegex,
            },
            {
              SalesmanName:
                containsRegex,
            },
            {
              salesmanName:
                containsRegex,
            },
            {
              "SelectedSalesmen.salesmanCode":
                exactRegex,
            },
            {
              "SelectedSalesmen.salesmanName":
                exactRegex,
            },
          ],
        });
      }

      /* =====================================================
        DELIVERY BY
        ===================================================== */

      if (deliveryBy) {
        const regex =
          createContainsRegex(
            deliveryBy
          );

        andConditions.push({
          $or: [
            {
              DeliveryBy:
                regex,
            },
            {
              deliveryBy:
                regex,
            },
            {
              DeliveryBoyCode:
                regex,
            },
            {
              deliveryBoyCode:
                regex,
            },
            {
              DeliveryBoyName:
                regex,
            },
            {
              deliveryBoyName:
                regex,
            },
          ],
        });
      }

      /* =====================================================
        VEHICLE
        ===================================================== */

      if (vehicleNo) {
        const regex =
          createContainsRegex(
            vehicleNo
          );

        andConditions.push({
          $or: [
            {
              VehicleNo:
                regex,
            },
            {
              vehicleNo:
                regex,
            },
          ],
        });
      }

      /* =====================================================
        STATUS
        ===================================================== */

      if (status) {
        const regex =
          createExactRegex(
            status
          );

        const statusConditions = [
          {
            Status:
              regex,
          },
          {
