        throw new Error(
          "Please select at least one bill"
        );
      }

      const duplicateLoad =
        await LoadHeader.findOne({
          DistributorId,
          FirmId,
          LoadSeries: cleanLoadSeries,
          LoadNo: cleanLoadNo,
          IsCancelled: {
            $ne: true,
          },
        }).session(session);

      if (duplicateLoad) {
        throw new Error(
