          const salesBillId = String(
            bill.SalesBillId ||
            bill.salesBillId ||
            bill._id ||
            ""
          ).trim();

          const billSeries = String(
            bill.BillSeries ??
            bill.Series ??
            bill.billSeries ??
            ""
          ).trim();

          return {
            ...bill,

            Sl: Number(
              bill.Sl ||
              bill.sr ||
              index + 1
            ),

            Selected:
              bill.Selected !== false,

            SalesBillId:
              salesBillId,

            BillDate:
              bill.BillDate ||
              bill.billDate ||
              "",

            /*
            * An empty series is valid.
            */
            Series: billSeries,
            BillSeries: billSeries,

            BillNo: Number(
              bill.BillNo ??
              bill.billNo ??
              0
            ),

            BillType: String(
              bill.BillType ||
              bill.billType ||
              "Credit"
            ).trim(),

            PartyCode: String(
              bill.PartyCode ||
              bill.partyCode ||
              ""
            ).trim(),

            PartyName: String(
              bill.PartyName ||
              bill.partyName ||
              ""
            ).trim(),

