            TotalAreas:
              finalSummary.totalAreas,

            TotalAmount:
              finalSummary.totalAmount,

            LoadSummary: finalSummary,

            DistributorId,
            FirmId,
            FirmName,

            Status: "ACTIVE",
            IsCancelled: false,
            IsLocked: false,

            CreatedBy,
            UpdatedBy,
          },
        ],
        {
          session,
        }
      );

