        {
          distributorId: DistributorId,
          firmId: FirmId,
          isActive: true,
          $or: billConditions,
        },
        {
          $set: {
            IsLoaded: true,
            LoadSeries: cleanLoadSeries,
            LoadNo: cleanLoadNo,
          },
        },
        {
          session,
        }
      );

      await commitTransactionReliably(session);

      res.status(201).json({
        success: true,
        message:
          "Load created successfully",

        data: savedLoad[0],
      });
    } catch (error) {
      await session.abortTransaction();

      console.error(
        "Create Load Error:",
        error
      );

      const duplicateError =
        error?.code === 11000;

      res
