      LoadNo: loadNo,
      IsCancelled: { $ne: true },
    };

    if (loadSeries) {
      filter.LoadSeries = loadSeries;
    }

    const load = await LoadHeader.findOne(filter).lean();

    if (!load) {
      return res.status(404).json({
        success: false,
        message: "Load not found for entered Load Series and Load No",
      });
    }

