      success: true,
      load: {
        id: load._id,
        loadSeries: load.LoadSeries || "",
        loadNo: load.LoadNo || "",
        loadDate: load.LoadDate || "",
        narration: load.Narration || "",
        items: load.Bills || [],
      },
    });
  } catch (error) {
    console.error("Settle Load API error:", error);
    res.status(500).json({
      success: false,
      message: "Failed to load settle load bills",
      error: error.message,
    });
  }
})

