              totalCancelBills:
                Number(
                  summary.totalCancelBills ??
                  totalCancelBills
                ),

              status: "SETTLED",
              isActive: true,
              bills: normalizedItems,
            },
          },
          {
            new: true,
            upsert: true,
            session,
            setDefaultsOnInsert: true,
          }
        );

      /*
      * Create or update Receipt records only now.
      */
      const receiptItems =
        normalizedItems.filter(
          (item) =>
            item.cancel !== "Y" &&
            item.pending !== "Y" &&
            Number(item.receiptAmount || 0) >
            0
        );

      for (const item of receiptItems) {
        let receiptNumber = Number(
          item.receiptNo || 0
        );

        if (!receiptNumber) {
          const lastReceipt =
            await Receipt.findOne({
              distributorId,
              firmId,
            })
              .sort({
                rno: -1,
              })
              .session(session)
              .lean();

          receiptNumber =
            Number(lastReceipt?.rno || 0) +
            1;
        }

        await Receipt.findOneAndUpdate(
          {
            distributorId,
            firmId,
            billSeries:
              item.billSeries,
            billNo:
              item.billNo,
          },
          {
            $set: {
              firmName,

              receiptDate:
                item.receiptDate ||
                settlementDate,

              receiptSeries:
                item.receiptSeries ||
                "RC",

              rno: receiptNumber,

              billSeries:
                item.billSeries,

              billNo:
                item.billNo,

              billDate:
                item.billDate,

              partyName:
                item.partyName,

              salesman:
                item.salesman,

              narration:
                item.receiptNarration ||
                narration,

              bankCode:
                item.bankCode || "",

              bankCash:
                item.bankCash ||
                item.bankName ||
                "",
              drawerBank:
                item.drawerBank || "",
              loadSeries:
                cleanLoadSeries,

              loadNo:
                cleanLoadNo,

              receiptAmount:
                Number(
                  item.receiptAmount || 0
                ),

              chequeNo:
                item.chequeNo || "",

              chequeDate:
                item.chequeDate || "",

              micr:
                item.micr || "",

              receiptSource:
                "SETTLE_LOAD",

              addUser:
                req.body.userName ||
                "ADMIN",

              receiptBills: [
                {
                  trnSeries:
                    item.billSeries,

                  trnNo:
                    item.billNo,

                  trnDate:
                    item.billDate,

                  amount:
                    item.originalBillAmount,

                  adjustAmt:
                    Number(
                      item.receiptAmount ||
                      0
                    ),

                  balanceAmt:
                    Number(
                      item.pendingAmount ||
                      0
                    ),

                  nowAdjust:
                    Number(
                      item.receiptAmount ||
                      0
                    ),

                  remark:
                    item.receiptNarration ||
                    "",
                },
              ],
            },
          },
          {
            upsert: true,
            new: true,
            session,
          }
        );
      }

      /*
      * Remove receipts when user changed a bill to
      * Pending or Cancel before saving.
      */
      const noReceiptItems =
        normalizedItems.filter(
          (item) =>
            item.cancel === "Y" ||
            item.pending === "Y" ||
            Number(item.receiptAmount || 0) <=
            0
        );

      for (const item of noReceiptItems) {
        await Receipt.updateMany(
          {
            distributorId,
            firmId,
            billSeries:
              item.billSeries,
            billNo:
              item.billNo,
            receiptSource:
              "SETTLE_LOAD",
          },
          { $set: { status: "REVERSED", reversedAt: new Date(), reversedBy: req.auth.userId, reversalReason: "Settlement allocation removed" } },
          { session }
        );
      }

      /*
      * Pending bills become available in Create Load.
      */
      const pendingConditions =
        normalizedItems
          .filter(
            (item) =>
              item.pending === "Y" ||
              item.transferToNextLoad ===
              true
          )
          .map((item) => ({
            BillSeries:
              item.billSeries,

            BillNo: Number(
              item.billNo || 0
            ),
          }))
          .filter(
            (item) =>
              item.BillNo
          );

      if (pendingConditions.length > 0) {
        await SalesHeader.updateMany(
          {
            distributorId,
            firmId,
            isActive: true,
            $or: pendingConditions,
          },
          {
            $set: {
              IsLoaded: false,
              LoadSeries: "",
              LoadNo: null,
            },
          },
          {
            session,
          }
        );
      }

      /*
      * Receipt, Adjust and Cancel bills remain processed
      * and must not appear in Create Load.
      */
      const completedConditions =
        normalizedItems
          .filter(
            (item) =>
              item.pending !== "Y" &&
              item.transferToNextLoad !==
              true
          )
          .map((item) => ({
            BillSeries:
              item.billSeries,

            BillNo: Number(
              item.billNo || 0
            ),
          }))
          .filter(
            (item) =>
              item.BillNo
          );

      if (
        completedConditions.length > 0
      ) {
        await SalesHeader.updateMany(
          {
            distributorId,
            firmId,
            isActive: true,
            $or: completedConditions,
          },
          {
            $set: {
              IsLoaded: true,
              LoadSeries:
                cleanLoadSeries,
              LoadNo:
                Number(cleanLoadNo),
            },
          },
          {
            session,
          }
        );
      }

      /*
      * Save F4 Bill Type changes only now.
      */
      for (const item of normalizedItems) {
        await SalesHeader.updateOne(
          {
            distributorId,
            firmId,
            isActive: true,
            BillSeries:
              item.billSeries,
            BillNo:
              Number(item.billNo || 0),
          },
          {
            $set: {
              BillType:
                item.billType ||
                "Credit",
            },
          },
          {
            session,
          }
        );
      }

      /*
      * Update original Load only after Save.
      */
      load.Bills = normalizedItems
        .filter(
          (item) =>
            item.cancel !== "Y" &&
            item.pending !== "Y"
        )
        .map((item, index) => ({
          Sl: index + 1,
          Selected: true,

          BillDate:
            item.billDate,

          Series:
            item.billSeries,

          BillSeries:
            item.billSeries,

          BillNo:
            Number(item.billNo || 0),

          BillType:
            item.billType,

          PartyCode:
            item.partyCode,

          PartyName:
            item.partyName,

          SalesmanName:
            item.salesman,

          Amount:
            Number(
              item.billAmount || 0
            ),

          ReceiptAmount:
            Number(
              item.receiptAmount || 0
            ),

          Adjust:
            item.adjust,

          Pending:
            item.pending,

          Status:
            item.status,

          ReceiptSeries:
            item.receiptSeries,

          ReceiptNo:
            item.receiptNo,

          ReceiptMode:
            item.receiptMode,

          ChequeNo:
            item.chequeNo,

          ChequeDate:
            item.chequeDate,

          BankName:
            item.bankName,

          MICR:
            item.micr,
        }));

      load.CancelledBills =
        normalizedItems.filter(
          (item) =>
            item.cancel === "Y"
        );

      load.PendingBills =
        normalizedItems.filter(
          (item) =>
            item.pending === "Y"
        );

      load.TotalBills =
        load.Bills.length;

      load.TotalAmount =
        load.Bills.reduce(
          (total, bill) =>
            total +
            Number(bill.Amount || 0),
          0
        );

      load.SettlementDate =
        settlementDate;

      load.SettlementNarration =
        narration;

      load.Status = "SETTLED";
      load.IsSettled = true;

      await load.save({
        session,
      });

      await commitTransactionReliably(session);

      return res.json({
        success: true,
        message:
          "Settle Load and all bill changes saved successfully",
        data: settleLoad,
      });
    } catch (error) {
      await session.abortTransaction();

      console.error(
        "Settle Load transaction error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          error.message ||
          "Settle Load save failed",
      });
    } finally {
      session.endSession();
    }
  }
)

