app.get(
  "/api/debit-note/next-no",
  ensureConnection,
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const debitNoteSeries =
        String(
          req.query.debitNoteSeries ||
          "DH"
        )
          .trim()
          .toUpperCase();

      if (
        !distributorId ||
        !firmId
      ) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required.",
        });
      }

      if (!debitNoteSeries) {
        return res.status(400).json({
          success: false,
          message:
            "Debit Note Series is required.",
        });
      }

      const lastDebitNote =
        await DebitNote.findOne({
          distributorId,
          firmId,

          DebitNoteSeries:
            debitNoteSeries,

          isActive: true,
        })
          .sort({
            DebitNoteNo: -1,
          })
          .select({
            DebitNoteNo: 1,
          })
          .lean();

      const nextDebitNoteNo =
        Number(
          lastDebitNote?.DebitNoteNo ||
          0
        ) + 1;

      return res.json({
        success: true,

        debitNoteSeries,

        nextDebitNoteNo,
      });
    } catch (error) {
      console.error(
        "Debit Note next number error:",
        error
      );

      return res.status(500).json({
        success: false,

        message:
          "Unable to generate next Debit Note number.",

        error:
          error.message,
      });
    }
  }
)

