app.get(
  "/api/debit-note/list",
  ensureConnection,
  securityRouter.authorizeRequest("VOUCHERS", "DEBIT_NOTE", "view"),   // ADD THIS
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const fromDate = String(
        req.query.fromDate || ""
      ).trim();

      const toDate = String(
        req.query.toDate || ""
      ).trim();

      const debitNoteSeries = String(
        req.query.debitNoteSeries ||
        req.query.vouSer ||
        ""
      ).trim();

      const supplierCode = String(
        req.query.supplierCode ||
        req.query.partyCode ||
        ""
      ).trim();

      const supplierName = String(
        req.query.supplierName ||
        req.query.partyName ||
        ""
      ).trim();

      const company = String(
        req.query.company || ""
      ).trim();

      const gdCode = String(
        req.query.gdCode || ""
      ).trim();

      const godownName = String(
        req.query.godownName || ""
      ).trim();

      const salesmanCode = String(
        req.query.salesmanCode || ""
      ).trim();

      const salesmanName = String(
        req.query.salesmanName || ""
      ).trim();

      const referenceBillSeries = String(
        req.query.referenceBillSeries || ""
      ).trim();

      const referenceBillNo = String(
        req.query.referenceBillNo || ""
      ).trim();

      const returnType = String(
        req.query.returnType || ""
      ).trim();

      const status = String(
        req.query.status || ""
      ).trim();

      const createdBy = String(
        req.query.createdBy || ""
      ).trim();

      const minAmountText = String(
        req.query.minAmount || ""
      ).trim();

      const maxAmountText = String(
        req.query.maxAmount || ""
      ).trim();

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(
          requestedPage
        ) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(
          requestedLimit
        ) &&
          requestedLimit > 0
          ? Math.min(
            requestedLimit,
            100
          )
          : 10;

      if (
        !distributorId ||
        !firmId
      ) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required.",
        });
      }

      const escapeRegex = (
        value
      ) =>
        String(value || "").replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      const containsRegex = (
        value
      ) =>
        new RegExp(
          escapeRegex(value),
          "i"
        );

      const exactRegex = (
        value
      ) =>
        new RegExp(
          `^${escapeRegex(
            value
          )}$`,
          "i"
        );

      const filter = {
        distributorId,
        firmId,

        isActive: {
          $ne: false,
        },
      };

      /*
      * Every grouped OR condition is pushed
      * into this array so none overwrite another.
      */
      const andConditions = [];

      /* =========================================
        DATE
        ========================================= */

      if (
        fromDate ||
        toDate
      ) {
        filter.VDate = {};

        if (fromDate) {
          filter.VDate.$gte =
            fromDate;
        }

        if (toDate) {
          filter.VDate.$lte =
            toDate;
        }
      }

      /* =========================================
        DEBIT NOTE SERIES
        ========================================= */

      if (debitNoteSeries) {
        filter.DebitNoteSeries =
          exactRegex(
            debitNoteSeries
          );
      }

      /* =========================================
        SUPPLIER
        ========================================= */

      if (supplierCode) {
        filter.SupplierCode =
          exactRegex(
            supplierCode
          );
      }

      if (supplierName) {
        filter.SupplierName =
          containsRegex(
            supplierName
          );
      }

      /* =========================================
        COMPANY
        ========================================= */

      if (company) {
        const companyRegex =
          containsRegex(
            company
          );

        andConditions.push({
          $or: [
            {
              CompanyCode:
                companyRegex,
            },
            {
              CompanyName:
                companyRegex,
            },
            {
              companyCode:
                companyRegex,
            },
            {
              companyName:
                companyRegex,
            },
          ],
        });
      }

      /* =========================================
        GODOWN
        ========================================= */

      if (gdCode) {
        filter.GDCode =
          exactRegex(
            gdCode
          );
      }

      if (godownName) {
        filter.Godown =
          containsRegex(
            godownName
          );
      }

      /* =========================================
        SALESMAN
        ========================================= */

      if (salesmanCode) {
        filter.SalesmanCode =
          exactRegex(
            salesmanCode
          );
      }

      if (salesmanName) {
        filter.SalesmanName =
          containsRegex(
            salesmanName
          );
      }

      /* =========================================
        REFERENCED PURCHASE BILL
        ========================================= */

      if (referenceBillSeries) {
        filter.BillSeries =
          exactRegex(
            referenceBillSeries
          );
      }

      if (referenceBillNo) {
        const numericBillNo =
          Number(
            referenceBillNo
          );

        if (
          Number.isFinite(
            numericBillNo
          )
        ) {
          filter.BillNo =
            numericBillNo;
        }
      }

      /* =========================================
        RETURN TYPE / STATUS / USER
        ========================================= */

      if (returnType) {
        filter.ReturnType =
          exactRegex(
            returnType
          );
      }

      if (status) {
        filter.Status =
          exactRegex(status);
      }

      if (createdBy) {
        filter.CreatedBy =
          containsRegex(
            createdBy
          );
      }

      /* =========================================
        AMOUNT RANGE
        ========================================= */

      const minAmount =
        Number(minAmountText);

      const maxAmount =
        Number(maxAmountText);

      if (
        (
          minAmountText &&
          Number.isFinite(
            minAmount
          )
        ) ||
        (
          maxAmountText &&
          Number.isFinite(
            maxAmount
          )
        )
      ) {
        filter.NetAmount = {};

        if (
          minAmountText &&
          Number.isFinite(
            minAmount
          )
        ) {
          filter.NetAmount.$gte =
            minAmount;
        }

        if (
          maxAmountText &&
          Number.isFinite(
            maxAmount
          )
        ) {
          filter.NetAmount.$lte =
            maxAmount;
        }
      }

      /* =========================================
        GENERAL SEARCH
        ========================================= */

      if (search) {
        const searchRegex =
          containsRegex(search);

        const numericSearch =
          Number(search);

        const searchConditions = [
          {
            DebitNoteSeries:
              searchRegex,
          },
          {
            BillSeries:
              searchRegex,
          },
          {
            SupplierCode:
              searchRegex,
          },
          {
            SupplierName:
              searchRegex,
          },
          {
            CompanyCode:
              searchRegex,
          },
          {
            CompanyName:
              searchRegex,
          },
          {
            GDCode:
              searchRegex,
          },
          {
            Godown:
              searchRegex,
          },
          {
            SalesmanCode:
              searchRegex,
          },
          {
            SalesmanName:
              searchRegex,
          },
          {
            ReturnType:
              searchRegex,
          },
          {
            Status:
              searchRegex,
          },
          {
            CreatedBy:
              searchRegex,
          },
          {
            Narration:
              searchRegex,
          },
        ];

        if (
          Number.isFinite(
            numericSearch
          )
        ) {
          searchConditions.push(
            {
              DebitNoteNo:
                numericSearch,
            },
            {
              VNo:
                numericSearch,
            },
            {
              BillNo:
                numericSearch,
            },
            {
              NetAmount:
                numericSearch,
            }
          );
        }

        andConditions.push({
          $or:
            searchConditions,
        });
      }

      if (
        andConditions.length > 0
      ) {
        filter.$and =
          andConditions;
      }

      const totalRecords =
        await DebitNote
          .countDocuments(
            filter
          );

      const totalPages =
        Math.max(
          1,
          Math.ceil(
            totalRecords /
            limit
          )
        );

      const currentPage =
        Math.min(
          page,
          totalPages
        );

      const skip =
        (
          currentPage -
          1
        ) *
        limit;

      const debitNotes =
        await DebitNote.find(
          filter
        )
          .sort({
            VDate: -1,
            DebitNoteNo: -1,
            _id: -1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res.json({
        success: true,

        debitNotes,

        count:
          debitNotes.length,

        pagination: {
          currentPage,

          page:
            currentPage,

          limit,

          totalRecords,

          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip +
                debitNotes.length,
                totalRecords
              ),
        },
      });
    } catch (error) {
      console.error(
        "Debit Note pagination error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Debit Notes.",
        error:
          error.message,
      });
    }
  }
)

