          maxAmountText &&
          Number.isFinite(
            maxAmount
          )
        )
      ) {
        filter.NetAmount = {};

        if (
          minAmountText &&
          Number.isFinite(
            minAmount
          )
        ) {
          filter.NetAmount.$gte =
            minAmount;
        }

        if (
          maxAmountText &&
          Number.isFinite(
            maxAmount
          )
        ) {
          filter.NetAmount.$lte =
            maxAmount;
        }
      }

      /* =========================================
        GENERAL SEARCH
        ========================================= */

      if (search) {
        const searchRegex =
          containsRegex(search);

        const numericSearch =
          Number(search);

        const searchConditions = [
          {
            DebitNoteSeries:
              searchRegex,
          },
          {
            BillSeries:
              searchRegex,
          },
          {
            SupplierCode:
              searchRegex,
          },
          {
            SupplierName:
              searchRegex,
          },
          {
            CompanyCode:
              searchRegex,
          },
          {
            CompanyName:
              searchRegex,
          },
          {
            GDCode:
              searchRegex,
          },
          {
            Godown:
              searchRegex,
          },
          {
            SalesmanCode:
              searchRegex,
          },
          {
            SalesmanName:
              searchRegex,
          },
          {
            ReturnType:
              searchRegex,
          },
          {
            Status:
              searchRegex,
          },
          {
            CreatedBy:
              searchRegex,
          },
          {
            Narration:
              searchRegex,
          },
        ];

        if (
          Number.isFinite(
            numericSearch
          )
        ) {
          searchConditions.push(
            {
              DebitNoteNo:
                numericSearch,
            },
            {
              VNo:
                numericSearch,
            },
            {
              BillNo:
                numericSearch,
            },
            {
              NetAmount:
                numericSearch,
            }
          );
        }

        andConditions.push({
          $or:
            searchConditions,
        });
      }

      if (
        andConditions.length > 0
      ) {
        filter.$and =
          andConditions;
      }

      const totalRecords =
        await DebitNote
          .countDocuments(
            filter
          );

      const totalPages =
        Math.max(
          1,
          Math.ceil(
            totalRecords /
            limit
          )
        );

      const currentPage =
        Math.min(
          page,
          totalPages
        );

      const skip =
        (
          currentPage -
          1
        ) *
        limit;

      const debitNotes =
        await DebitNote.find(
          filter
        )
          .sort({
            VDate: -1,
            DebitNoteNo: -1,
            _id: -1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res.json({
        success: true,

        debitNotes,

        count:
          debitNotes.length,

        pagination: {
          currentPage,

          page:
            currentPage,

          limit,

          totalRecords,

          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                skip +
                debitNotes.length,
                totalRecords
              ),
        },
      });
    } catch (error) {
      console.error(
        "Debit Note pagination error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Debit Notes.",
        error:
          error.message,
      });
    }
  }
)

