app.put(
  "/api/debit-note/:id",
  ensureConnection,
  securityRouter.authorizeRequest("VOUCHERS", "DEBIT_NOTE", "edit"),   // ADD THIS
  async (req, res) => {
    const session =
      await mongoose.startSession();

    try {
      session.startTransaction();

      const id =
        String(
          req.params.id || ""
        ).trim();

      const distributorId = String(req.auth.distributorId || "").trim();

      const firmId = String(req.auth.firmId || "").trim();

      const firmName = String(
        req.body.firmName || ""
      ).trim();

      if (
        !mongoose.Types.ObjectId
          .isValid(id)
      ) {
        throw new Error(
          "Invalid Debit Note ID."
        );
      }

      const oldDebitNote =
        await DebitNote.findOne({
          _id:
            id,

          distributorId,
          firmId,

          isActive:
            true,
        }).session(session);

      if (!oldDebitNote) {
        throw new Error(
          "Debit Note not found."
        );
      }

