              PRate: Number(
                item.PRate ??
                item.purchaseRate ??
                0
              ),

              BoxPack: Number(
                item.BoxPack ??
                item.boxPack ??
                1
              ),

              InBoxPack: Number(
                item.InBoxPack ??
                item.inBoxPack ??
                item.inboxPack ??
                1
              ),

              totalStockQty,
            };
