app.get(
  "/api/credit-note/list",
  ensureConnection,                                                    // 1st
  securityRouter.authorizeRequest("VOUCHERS", "CREDIT_NOTE", "view"),  // 2nd
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const fromDate = String(
        req.query.fromDate || ""
      ).trim();

      const toDate = String(
        req.query.toDate || ""
      ).trim();

      const creditNoteSeries = String(
        req.query.creditNoteSeries ||
        req.query.vouSer ||
        ""
      ).trim();

      const partyCode = String(
        req.query.partyCode || ""
      ).trim();

      const partyName = String(
        req.query.partyName || ""
      ).trim();

      const company = String(
        req.query.company || ""
      ).trim();

      const gdCode = String(
        req.query.gdCode || ""
      ).trim();

      const godownName = String(
        req.query.godownName || ""
      ).trim();

      const salesmanCode = String(
        req.query.salesmanCode || ""
      ).trim();

      const salesmanName = String(
        req.query.salesmanName || ""
      ).trim();

      const referenceBillSeries = String(
        req.query.referenceBillSeries || ""
      ).trim();

      const referenceBillNo = String(
        req.query.referenceBillNo || ""
      ).trim();

      const status = String(
        req.query.status || ""
      ).trim();

      const createdBy = String(
        req.query.createdBy || ""
      ).trim();

      const minAmountText = String(
        req.query.minAmount || ""
      ).trim();

      const maxAmountText = String(
        req.query.maxAmount || ""
      ).trim();

      const requestedPage = Number.parseInt(
        req.query.page,
        10
      );

      const requestedLimit = Number.parseInt(
        req.query.limit,
        10
      );

      const page =
        Number.isFinite(requestedPage) &&
          requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
          requestedLimit > 0
          ? Math.min(requestedLimit, 100)
          : 10;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      const escapeRegex = (value) =>
        String(value || "").replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      const containsRegex = (value) =>
        new RegExp(
          escapeRegex(value),
          "i"
        );

      const exactRegex = (value) =>
        new RegExp(
          `^${escapeRegex(value)}$`,
          "i"
        );

      const filter = {
        distributorId,
        firmId,

        isActive: {
          $ne: false,
        },
      };

      /*
      * Use $and so multiple groups of $or
      * conditions do not overwrite one another.
      */
      const andConditions = [];

      /* =========================================
        DATE FILTER
        ========================================= */

      if (fromDate || toDate) {
        const dateFilter = {};

        if (fromDate) {
          dateFilter.$gte =
            fromDate;
        }

        if (toDate) {
          dateFilter.$lte =
            toDate;
        }

        filter.VDate =
          dateFilter;
      }

      /* =========================================
        CREDIT NOTE SERIES
        ========================================= */

      if (creditNoteSeries) {
        filter.CreditNoteSeries =
          exactRegex(
            creditNoteSeries
          );
      }

      /* =========================================
        PARTY FILTERS
        ========================================= */

      if (partyCode) {
        filter.PartyCode =
          exactRegex(
            partyCode
          );
      }

      if (partyName) {
        filter.PartyName =
          containsRegex(
            partyName
          );
      }

      /* =========================================
        COMPANY FILTER
        ========================================= */

      if (company) {
        const companyRegex =
          containsRegex(
            company
          );

        andConditions.push({
          $or: [
            {
              CompanyCode:
                companyRegex,
            },
            {
              CompanyName:
                companyRegex,
            },
            {
              companyCode:
                companyRegex,
            },
            {
              companyName:
                companyRegex,
            },
          ],
        });
      }

      /* =========================================
        GODOWN FILTERS
        ========================================= */

      if (gdCode) {
        filter.GDCode =
          exactRegex(
            gdCode
          );
      }

      if (godownName) {
        filter.Godown =
          containsRegex(
            godownName
          );
      }

      /* =========================================
        SALESMAN FILTERS
        ========================================= */

      if (salesmanCode) {
        filter.SalesmanCode =
          exactRegex(
            salesmanCode
          );
      }

      if (salesmanName) {
        filter.SalesmanName =
          containsRegex(
            salesmanName
          );
      }

      /* =========================================
        ORIGINAL SALES BILL REFERENCE
        ========================================= */

      if (referenceBillSeries) {
        filter.BillSeries =
          exactRegex(
            referenceBillSeries
          );
      }

      if (referenceBillNo) {
