app.get(
  "/api/quotation/:id",
  ensureConnection,
  securityRouter.authorizeRequest("SALES", "QUOTATION", "view"),
  async (req, res) => {
    try {
      const quotationId = String(
        req.params.id || ""
      ).trim();

      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      if (
        !quotationId ||
        !mongoose.Types.ObjectId.isValid(
          quotationId
        )
      ) {
        return res.status(400).json({
          success: false,
          message:
            "Invalid quotation ID",
        });
      }

      /*
      * IMPORTANT:
      * Your actual model is QuotationHeader,
      * not Quotation.
      */
      const quotation =
        await QuotationHeader.findOne({
          _id: quotationId,
          distributorId,
          firmId,
          isActive: true,
        }).lean();

      if (!quotation) {
        return res.status(404).json({
          success: false,
          message:
            "Quotation not found for this firm",
        });
      }

      return res.json({
        success: true,
        quotation,
      });
    } catch (error) {
      console.error(
        "GET QUOTATION FOR EDIT ERROR:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          error.message ||
          "Failed to load quotation",
      });
    }
  }
)

