              sgst:
                Number(
                  item.sgst || 0
                ),

              cgst:
                Number(
                  item.cgst || 0
                ),

              igst:
                Number(
                  item.igst || 0
                ),

              amount:
                Number(
                  item.amount || 0
                ),
            };
          }
        );

      const updateData = {
        firmName:
          String(
            firmName || ""
          ).trim(),

        BillDate,
        Godown,
        GDCode,

        CompanyCode:
          String(
            CompanyCode || ""
          ).trim(),

        CompanyName:
          String(
            CompanyName || ""
          ).trim(),

        AreaCode:
          String(
            AreaCode || ""
          ).trim(),

        AreaName:
          String(
            AreaName || ""
          ).trim(),

        PartyCode:
          String(
            PartyCode || ""
          ).trim(),

        PartyName:
          String(
            PartyName || ""
          ).trim(),

        BillSeries:
          String(
            BillSeries || ""
          ).trim(),

        BillNo:
          Number(BillNo),

        BillType:
          BillType || "Credit",

        DueDate,

        SalesmanCode:
          String(
            SalesmanCode || ""
          ).trim(),

        SalesmanName:
          String(
            SalesmanName || ""
          ).trim(),

        Narration:
          String(
            Narration || ""
          ).trim(),

        GrossAmount:
          Number(
            req.body.GrossAmount || 0
          ),

        TPRAmount:
          Number(
            req.body.TPRAmount || 0
          ),

        SchemeAmount:
          Number(
            req.body.SchemeAmount || 0
          ),

        StarDiscountAmount:
          Number(
            req.body
              .StarDiscountAmount ||
            0
          ),

        CashDiscountAmount:
          Number(
            req.body
              .CashDiscountAmount ||
            0
          ),

        DisplayAmount:
          Number(
            req.body.DisplayAmount || 0
          ),

        CouponAmount:
          Number(
            req.body.CouponAmount || 0
          ),

        AddLessAmount:
          Number(
            req.body.AddLessAmount || 0
          ),

        TaxableValue:
          Number(
            req.body.TaxableValue || 0
          ),

        SGSTAmount:
          Number(
            req.body.SGSTAmount || 0
          ),

        CGSTAmount:
          Number(
            req.body.CGSTAmount || 0
          ),

        IGSTAmount:
          Number(
            req.body.IGSTAmount || 0
          ),

        OriginalNetAmount:
          Number(
            req.body
              .OriginalNetAmount ??
            req.body.NetAmount ??
            0
          ),

        NetAmount:
          Number(
            req.body.NetAmount || 0
          ),

        TotalQty:
          Number(
            req.body.TotalQty ||
            normalizedItems.reduce(
              (
                total,
                item
              ) =>
                total +
                Number(
                  item.qty || 0
                ),
              0
            )
          ),

        TotalFreeQty:
          Number(
            req.body.TotalFreeQty ||
            normalizedItems.reduce(
              (
                total,
                item
              ) =>
                total +
                Number(
                  item.free || 0
                ),
              0
            )
          ),

        TotalItems:
          normalizedItems.length,

        items:
          normalizedItems,

        isActive: true,
      };

      const updatedQuotation =
        await QuotationHeader.findOneAndUpdate(
          {
            _id: quotationId,
            distributorId:
              String(
                distributorId
              ).trim(),
            firmId:
              String(
                firmId
              ).trim(),
          },
          {
            $set: updateData,
          },
          {
            new: true,
            runValidators: true,
          }
        ).lean();

      if (!updatedQuotation) {
        return res.status(404).json({
          success: false,
          message:
            "Quotation not found during update",
        });
      }

      return res.json({
        success: true,
        message:
          "Quotation updated successfully",

        quotation:
          updatedQuotation,

        data: {
          header:
            updatedQuotation,
        },
      });
    } catch (error) {
      console.error(
        "UPDATE QUOTATION ERROR:",
        error
      );

      if (error?.code === 11000) {
        return res.status(409).json({
          success: false,
          message:
            "Quotation Series and Bill No already exist",
        });
      }

      return res.status(500).json({
        success: false,
        message:
          error.message ||
          "Quotation update failed",
      });
    }
  }
)

