app.get(
  "/api/bill-print/load-details",
  ensureConnection,
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const loadSeries = String(
        req.query.loadSeries || ""
      )
        .trim()
        .toUpperCase();

      const loadNo = String(
        req.query.loadNo || ""
      ).trim();

      if (
        !distributorId ||
        !firmId ||
        !loadSeries ||
        !loadNo
      ) {
        return res.status(400).json({
          success: false,
          message:
            "Distributor, Firm, Load Series and Load No are required.",
        });
      }

      /*
      * Your LoadHeader schema uses:
      * DistributorId
      * FirmId
      * LoadSeries
      * LoadNo
      */
      const load = await LoadHeader.findOne({
        DistributorId: distributorId,
        FirmId: firmId,
        LoadSeries: loadSeries,
        LoadNo: Number(loadNo),
        IsCancelled: {
          $ne: true,
        },
      }).lean();

      if (!load) {
        return res.status(404).json({
          success: false,
          message: `Load ${loadSeries}-${loadNo} not found.`,
        });
      }

      const loadBills = Array.isArray(load.Bills)
        ? load.Bills
        : [];

      if (loadBills.length === 0) {
        return res.status(404).json({
          success: false,
          message:
            "No bills are available in the selected load.",
        });
      }

      const salesBillIds = loadBills
        .map((bill) =>
          String(
            bill.SalesBillId ||
            bill.salesBillId ||
            ""
          ).trim()
        )
        .filter((id) =>
          mongoose.Types.ObjectId.isValid(id)
        );

      const billConditions = loadBills
        .map((bill) => {
          const BillSeries = String(
            bill.BillSeries ||
            bill.Series ||
            bill.billSeries ||
            ""
          ).trim();

          const BillNo = Number(
            bill.BillNo ||
            bill.billNo ||
            0
          );

          if (!BillNo) {
            return null;
          }

          return {
            BillSeries,
            BillNo,
          };
        })
        .filter(Boolean);

      const salesQueryConditions = [];

      if (salesBillIds.length > 0) {
        salesQueryConditions.push({
          _id: {
            $in: salesBillIds,
          },
        });
      }

      if (billConditions.length > 0) {
        salesQueryConditions.push({
          $or: billConditions,
        });
      }

      let bills = [];

      if (salesQueryConditions.length > 0) {
        bills = await SalesHeader.find({
          distributorId,
          firmId,
          isActive: {
            $ne: false,
          },
          $or: salesQueryConditions,
        })
          .sort({
            BillSeries: 1,
            BillNo: 1,
          })
          .lean();
      }

      /*
      * Use the bills stored inside the load if older
      * loads do not contain SalesBillId references.
      */
      if (bills.length === 0) {
        bills = loadBills.map((bill) => ({
          ...bill,

          BillSeries:
            bill.BillSeries ||
            bill.Series ||
            bill.billSeries ||
            "",

          BillNo:
            bill.BillNo ||
            bill.billNo ||
            "",

          BillDate:
            bill.BillDate ||
            bill.billDate ||
            "",

          PartyCode:
            bill.PartyCode ||
            bill.partyCode ||
            "",

          PartyName:
            bill.PartyName ||
            bill.partyName ||
            "",

          NetAmount: Number(
            bill.Amount ||
            bill.billAmount ||
            bill.NetAmount ||
            0
          ),

          items:
            bill.items ||
            bill.Items ||
            bill.products ||
            [],
        }));
      }

      const sortedBillNumbers = bills
        .map((bill) =>
          Number(
            bill.BillNo ||
            bill.billNo ||
            0
          )
        )
        .filter((number) => number > 0)
        .sort((a, b) => a - b);

      const transactionSeries =
        String(
          bills[0]?.BillSeries ||
          bills[0]?.billSeries ||
          loadBills[0]?.BillSeries ||
          loadBills[0]?.Series ||
          ""
        ).trim();

      const totalAmount = bills.reduce(
        (sum, bill) =>
          sum +
          Number(
            bill.NetAmount ||
            bill.netAmount ||
            bill.Amount ||
            bill.billAmount ||
            0
          ),
        0
      );

      const uniqueParties = new Set(
        bills
          .map(
            (bill) =>
              bill.PartyCode ||
              bill.partyCode ||
              bill.PartyName ||
              bill.partyName
          )
          .filter(Boolean)
      );

      const firm = await Register.findOne({
        distributorId,
        firmId,
        isActive: true,
      })
        .select(
          "firmName address1 address2 city pinCode state phoneNo mobileNo gstNo email"
        )
        .lean();

      return res.json({
        success: true,

        header: {
          LoadSeries:
            load.LoadSeries || loadSeries,

          LoadNo:
            load.LoadNo || Number(loadNo),

          LoadDate:
            load.LoadDate || "",

          TrnSeries: transactionSeries,

          FromTrnNo:
            sortedBillNumbers.length > 0
              ? sortedBillNumbers[0]
              : "",

          ToTrnNo:
            sortedBillNumbers.length > 0
              ? sortedBillNumbers[
              sortedBillNumbers.length - 1
              ]
              : "",

          TotalBills: bills.length,

          TotalParties: uniqueParties.size,

          TotalAmount: totalAmount,

          Narration:
            load.Narration || "",
        },

        firm: {
          firmName:
            firm?.firmName ||
            load.FirmName ||
            "",

          address1: firm?.address1 || "",
          address2: firm?.address2 || "",
          city: firm?.city || "",
          pinCode: firm?.pinCode || "",
          state: firm?.state || "",
          phoneNo:
            firm?.phoneNo ||
            firm?.mobileNo ||
            "",
          gstNo: firm?.gstNo || "",
          email: firm?.email || "",
        },

        bills,
      });
    } catch (error) {
      console.error(
        "Bill Print load-details error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          error.message ||
          "Failed to load Bill Print data.",
      });
    }
  }
)

