app.get(
  "/api/sales/:id/print-details",
  ensureConnection,
  async (req, res) => {
    try {
      res.setHeader(
        "Cache-Control",
        "no-store"
      );

      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const salesId = String(req.params.id || "").trim();

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required.",
        });
      }

      if (!mongoose.Types.ObjectId.isValid(salesId)) {
        return res.status(400).json({
          success: false,
          message: "Invalid Sales Bill ID.",
        });
      }

      const bill = await SalesHeader.findOne({
        _id: salesId,
        distributorId,
        firmId,
        isActive: true,
      }).lean();

      if (!bill) {
        return res.status(404).json({
          success: false,
          message: "Sales bill not found.",
        });
      }

      const [firm, party, salesman, area] =
        await Promise.all([
          Register.findOne({
            distributorId,
            firmId,
            isActive: true,
          }).lean(),

          Account.findOne({
            distributorId,
            firmId,
            $or: [
              {
                accountCode: String(
                  bill.PartyCode || ""
                ).trim(),
              },
              {
                accountName: String(
                  bill.PartyName || ""
                ).trim(),
              },
            ],
            // Account Master also treats legacy records without isActive as active.
            isActive: { $ne: false },
          }).lean(),

          Salesman.findOne({
            distributorId,
            firmId,
            $or: [
              {
                salesmanCode: String(
                  bill.SalesmanCode || ""
                ).trim(),
              },
              {
                salesmanName: String(
                  bill.SalesmanName || ""
                ).trim(),
              },
            ],
            isActive: true,
          }).lean(),

          Area.findOne({
            distributorId,
            firmId,
            $or: [
              {
                areaCode: String(
                  bill.AreaCode || ""
                ).trim(),
              },
              {
                areaName: String(
                  bill.AreaName || ""
                ).trim(),
              },
            ],
            isActive: true,
          }).lean(),
        ]);

      /*
      * Get bank details from Other Account.
      * Change accountGroup values here if your bank group
      * uses another name.
      */
      const bank = await OtherAccount.findOne({
        distributorId,
        firmId,
        isActive: true,
        $or: [
          {
            accountGroup: {
              $regex: /bank/i,
            },
          },
          {
            bankAccountNo: {
              $nin: ["", null],
            },
          },
        ],
      })
        .sort({ createdAt: 1 })
        .lean();

      const normalizedItems = (
        Array.isArray(bill.items)
          ? bill.items
          : []
      ).map((item, index) => {
        const qty = Number(
          item.qty ??
          item.Qty ??
          item.quantity ??
          0
        );

        const free = Number(
          item.free ??
          item.Free ??
          0
        );

        const rate = Number(
          item.rate ??
          item.Rate ??
          item.salesRate ??
          0
        );

        const grossAmount = Number(
          item.grossAmount ??
          item.GrossAmount ??
          item.gross ??
          qty * rate
        );

        const schemePercent = Number(
          item.schemePct ??
          item.schemePercent ??
          item.SchemePercent ??
          0
        );

        const schemeAmount = Number(
          item.schemeAmt ??
          item.schemeAmount ??
          item.SchemeAmount ??
          0
        );

        const cashDiscountPercent = Number(
          item.cdPct ??
          item.cashDiscountPercent ??
          item.CashDiscountPercent ??
          0
        );

        const cashDiscountAmount = Number(
          item.cdAmt ??
          item.cashDiscountAmount ??
          item.CashDiscountAmount ??
          0
        );

        const taxableAmount = Number(
          item.taxable ??
          item.taxableAmount ??
          item.TaxableAmount ??
          grossAmount -
          schemeAmount -
          cashDiscountAmount
        );

        const gstPercent = Number(
          item.gst ??
          item.gstPercent ??
          item.GSTPercent ??
          0
        );

        const cgstPercent = Number(
          item.cgstPercent ??
          item.CGSTPercent ??
          gstPercent / 2
        );

        const sgstPercent = Number(
          item.sgstPercent ??
          item.SGSTPercent ??
          gstPercent / 2
        );

