app.get(
  "/api/sales/:id/print-details",
  ensureConnection,
  async (req, res) => {
    try {
      res.setHeader(
        "Cache-Control",
        "no-store"
      );

      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const salesId = String(req.params.id || "").trim();

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required.",
        });
      }

      if (!mongoose.Types.ObjectId.isValid(salesId)) {
        return res.status(400).json({
          success: false,
          message: "Invalid Sales Bill ID.",
        });
      }

      const bill = await SalesHeader.findOne({
        _id: salesId,
        distributorId,
        firmId,
        isActive: true,
      }).lean();

      if (!bill) {
        return res.status(404).json({
          success: false,
          message: "Sales bill not found.",
        });
      }

      const [firm, party, salesman, area] =
        await Promise.all([
          Register.findOne({
            distributorId,
            firmId,
            isActive: true,
          }).lean(),

          Account.findOne({
            distributorId,
            firmId,
            $or: [
              {
                accountCode: String(
                  bill.PartyCode || ""
                ).trim(),
              },
              {
                accountName: String(
                  bill.PartyName || ""
                ).trim(),
              },
            ],
            // Account Master also treats legacy records without isActive as active.
            isActive: { $ne: false },
          }).lean(),

          Salesman.findOne({
            distributorId,
            firmId,
            $or: [
              {
                salesmanCode: String(
                  bill.SalesmanCode || ""
                ).trim(),
              },
              {
                salesmanName: String(
                  bill.SalesmanName || ""
                ).trim(),
              },
            ],
            isActive: true,
          }).lean(),

          Area.findOne({
            distributorId,
            firmId,
            $or: [
              {
                areaCode: String(
                  bill.AreaCode || ""
                ).trim(),
              },
              {
                areaName: String(
                  bill.AreaName || ""
                ).trim(),
              },
            ],
            isActive: true,
          }).lean(),
        ]);

      /*
      * Get bank details from Other Account.
      * Change accountGroup values here if your bank group
      * uses another name.
      */
      const bank = await OtherAccount.findOne({
        distributorId,
        firmId,
        isActive: true,
        $or: [
          {
            accountGroup: {
              $regex: /bank/i,
            },
          },
          {
            bankAccountNo: {
              $nin: ["", null],
            },
          },
        ],
      })
        .sort({ createdAt: 1 })
        .lean();

      const normalizedItems = (
        Array.isArray(bill.items)
          ? bill.items
          : []
      ).map((item, index) => {
        const qty = Number(
          item.qty ??
          item.Qty ??
          item.quantity ??
          0
        );

        const free = Number(
          item.free ??
          item.Free ??
          0
        );

        const rate = Number(
          item.rate ??
          item.Rate ??
          item.salesRate ??
          0
        );

        const grossAmount = Number(
          item.grossAmount ??
          item.GrossAmount ??
          item.gross ??
          qty * rate
        );

        const schemePercent = Number(
          item.schemePct ??
          item.schemePercent ??
          item.SchemePercent ??
          0
        );

        const schemeAmount = Number(
          item.schemeAmt ??
          item.schemeAmount ??
          item.SchemeAmount ??
          0
        );

        const cashDiscountPercent = Number(
          item.cdPct ??
          item.cashDiscountPercent ??
          item.CashDiscountPercent ??
          0
        );

        const cashDiscountAmount = Number(
          item.cdAmt ??
          item.cashDiscountAmount ??
          item.CashDiscountAmount ??
          0
        );

        const taxableAmount = Number(
          item.taxable ??
          item.taxableAmount ??
          item.TaxableAmount ??
          grossAmount -
          schemeAmount -
          cashDiscountAmount
        );

        const gstPercent = Number(
          item.gst ??
          item.gstPercent ??
          item.GSTPercent ??
          0
        );

        const cgstPercent = Number(
          item.cgstPercent ??
          item.CGSTPercent ??
          gstPercent / 2
        );

        const sgstPercent = Number(
          item.sgstPercent ??
          item.SGSTPercent ??
          gstPercent / 2
        );

        const igstPercent = Number(
          item.igstPercent ??
          item.IGSTPercent ??
          0
        );

        const cgstAmount = Number(
          item.cgst ??
          item.cgstAmount ??
          item.CGSTAmount ??
          0
        );

        const sgstAmount = Number(
          item.sgst ??
          item.sgstAmount ??
          item.SGSTAmount ??
          0
        );

        const igstAmount = Number(
          item.igst ??
          item.igstAmount ??
          item.IGSTAmount ??
          0
        );

        const netAmount = Number(
          item.amount ??
          item.netAmount ??
          item.NetAmount ??
          taxableAmount +
          cgstAmount +
          sgstAmount +
          igstAmount
        );

        return {
          srNo: index + 1,

          productCode:
            item.productCode ||
            item.ProdCode ||
            item.productId ||
            "",

          productName:
            item.productName ||
            item.ProdName ||
            item.name ||
            item.product ||
            "",

          hsn:
            item.hsn ||
            item.hsnCode ||
            item.HSN ||
            item.HSNCode ||
            "",

          batchNo:
            item.batchNo ||
            item.batch ||
            item.Batch ||
            item.selectedBatch?.batchNo ||
            "",

          mrp: Number(
            item.mrp ??
            item.MRP ??
            0
          ),

          unit:
            item.units ||
            item.unit ||
            item.basicUnit ||
            item.Unit ||
            "PCS",

          pack:
            item.pack ??
            item.Pack ??
            item.packing ??
            item.Packing ??
            item.packSize ??
            item.PackSize ??
            item.boxPack ??
            item.BoxPack ??
            item.unitQty ??
            item.UnitQty ??
            "",

          qty,
          free,
          rate,
          grossAmount,
          taxableAmount,

          schemePercent,
          schemeAmount,

          cashDiscountPercent,
          cashDiscountAmount,

          cgstPercent,
          cgstAmount,

          sgstPercent,
          sgstAmount,

          igstPercent,
          igstAmount,

          netAmount,
        };
      });

      return res.json({
        success: true,

        bill: {
          ...bill,
          items: normalizedItems,
        },

        firm: {
          firmName:
            firm?.firmName ||
            bill.firmName ||
            "",

          address1: firm?.address1 || "",
          address2: firm?.address2 || "",
          city: firm?.city || "",
          pinCode: firm?.pinCode || "",
          state: firm?.state || "",
          stateCode:
            firm?.stateCode ||
            "",

          phoneNo: firm?.phoneNo || "",
          mobileNo: firm?.mobileNo || "",
          email:
            firm?.email ||
            firm?.emailId ||
            "",

          gstNo: firm?.gstNo || "",
          panNo:
            firm?.panNo ||
            "",
        },

        party: {
          partyCode:
            party?.accountCode ||
            bill.PartyCode ||
            "",

          partyName:
            party?.accountName ||
            bill.PartyName ||
            "",

          address:
            party?.address ||
            "",

          address2:
            party?.add2 ||
            party?.billToAdd1 ||
            "",

          town:
            party?.town ||
            "",

          pinCode:
            party?.pinCode ||
            "",

          state:
            party?.state ||
            "",

          stateCode:
            party?.stateCode ||
            "",

          phoneNo:
            party?.phoneNo ||
            "",

          mobileNo:
            party?.mobileNo ||
            "",

          email:
            party?.emailId ||
            "",

          gstNo:
            party?.gstNo ||
            "",

          panNo:
            party?.panNo ||
            "",
        },

        salesman: {
          salesmanCode:
            salesman?.salesmanCode ||
            bill.SalesmanCode ||
            "",

          salesmanName:
            salesman?.salesmanName ||
            bill.SalesmanName ||
            "",

          mobileNo:
            salesman?.mobileNo ||
            salesman?.phoneNo ||
            "",
        },

        area: {
          areaCode:
            area?.areaCode ||
            bill.AreaCode ||
            "",

          areaName:
            area?.areaName ||
            bill.AreaName ||
            "",
        },

        bank: {
          bankName:
            bank?.accountName ||
            "",

          accountName:
            firm?.firmName ||
            bill.firmName ||
            "",

          accountNo:
            bank?.bankAccountNo ||
            "",

          ifscCode:
            bank?.ifscCode ||
            "",

          branch:
            bank?.branchName ||
            bank?.branch ||
            "",

          accountType:
            bank?.accountType ||
            "",
        },
      });
    } catch (error) {
      console.error(
        "Sales print-details error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          error.message ||
          "Failed to load Sales Bill print data.",
      });
    }
  }
)

