app.get(
  "/api/sales/find-bill",
  ensureConnection,
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const billSeries = String(
        req.query.billSeries || ""
      ).trim();

      const billNo = Number(
        req.query.billNo || 0
      );

      const companyCode = String(
        req.query.companyCode || ""
      ).trim();

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      if (!billNo) {
        return res.status(400).json({
          success: false,
          message: "Bill number is required",
        });
      }

      const filter = {
        distributorId,
        firmId,
        BillNo: billNo,
        isActive: true,
      };

      /*
      * Bill Series is optional because old bills
      * can contain blank series.
      */
      if (billSeries) {
        filter.$and = [
          {
            $or: [
              { BillSeries: billSeries },
              { billSeries },
              { Series: billSeries },
            ],
          },
        ];
      } else {
        filter.$and = [
          {
            $or: [
              { BillSeries: "" },
              { BillSeries: null },
              {
                BillSeries: {
                  $exists: false,
                },
              },

              { billSeries: "" },
              { billSeries: null },
              {
                billSeries: {
                  $exists: false,
                },
              },

              { Series: "" },
              { Series: null },
              {
                Series: {
                  $exists: false,
                },
              },
            ],
          },
        ];
      }

      /*
      * Company is checked when selected.
      */
      if (companyCode) {
        filter.$and.push({
          $or: [
            { CompanyCode: companyCode },
            { companyCode },
            { Company: companyCode },
            { company: companyCode },
          ],
        });
      }

      const bill =
        await SalesHeader.findOne(filter)
          .lean();

      if (!bill) {
        return res.status(404).json({
          success: false,
          message:
            `Sales bill not found for ` +
            `${companyCode || "selected company"}, ` +
            `${billSeries || "blank series"}-${billNo}`,
        });
      }

      res.json({
        success: true,
        bill,
      });

    } catch (error) {
      console.error(
        "Sales bill lookup error:",
        error
      );

      res.status(500).json({
        success: false,
        message:
          "Sales bill load failed",
        error: error.message,
      });
    }
  }
)

