app.get(
  "/api/reports/product-sales/criteria",
  ensureConnection,
  securityRouter.authorizeRequest("REPORTS", "PRODUCT_WISE_SALES", "view"),
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const companyCode = String(
        req.query.companyCode || ""
      ).trim();

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message: "distributorId and firmId are required.",
        });
      }

      const baseFilter = {
        distributorId,
        firmId,
        isActive: true,
      };

      // Get companies
      const companies = await Company.find(baseFilter)
        .select({
          _id: 1,
          companyCode: 1,
          companyName: 1,
        })
        .sort({
          companyName: 1,
          companyCode: 1,
        })
        .lean();

      // Get products - filter by company if provided
      const productFilter = {
        ...baseFilter,
      };

      if (companyCode) {
        productFilter.$or = [
          { companyCode: companyCode },
          { companyId: companyCode },
        ];
      }

      const products = await Product.find(productFilter)
        .select({
          _id: 1,
          productCode: 1,
          productName: 1,
          group: 1,
          category: 1,
          brand: 1,
        })
        .sort({
          productName: 1,
          productCode: 1,
        })
        .lean();

      return res.json({
        success: true,
        companies,
        products,
      });
    } catch (error) {
      console.error("Product sales criteria error:", error);
      return res.status(500).json({
        success: false,
        message: "Failed to load product sales criteria.",
        error: error.message,
      });
    }
  }
)

