        req.query.receiptType || ""
      )
        .trim()
        .toLowerCase();

      const party = String(
        req.query.party || ""
      ).trim();

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(
          requestedPage
        ) &&
        requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(
          requestedLimit
        ) &&
        requestedLimit > 0
          ? Math.min(
              requestedLimit,
              100
            )
          : 10;

      if (
        !distributorId ||
        !firmId
      ) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      const escapeRegex = (
        value
      ) =>
        String(value || "").replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      const filter = {
        distributorId,
        firmId,
      };

      const andConditions = [];

      /* =====================================================
         DATE FILTER
         Receipt dates are currently stored as YYYY-MM-DD strings.
         ===================================================== */

      if (
        fromDate ||
        toDate
      ) {
        const receiptDateCondition =
          {};

        if (fromDate) {
          receiptDateCondition.$gte =
            fromDate;
        }

        if (toDate) {
          receiptDateCondition.$lte =
            toDate;
        }

        andConditions.push({
          receiptDate:
            receiptDateCondition,
        });
      }

      /* =====================================================
         PARTY FILTER
         ===================================================== */

      if (party) {
        const partyRegex =
          new RegExp(
            escapeRegex(party),
            "i"
          );

        andConditions.push({
          $or: [
            {
              partyName:
                partyRegex,
            },
            {
              partyId:
                partyRegex,
            },
          ],
        });
      }

      /* =====================================================
         RECEIPT TYPE FILTER
         Supports the existing Cash/Cheque filter.
         ===================================================== */

      if (
        receiptType === "cash"
      ) {
        andConditions.push({
          $or: [
            {
              bankCash: {
                $regex:
                  /^cash$/i,
              },
            },
            {
              bankCash: {
                $regex:
                  /cash/i,
              },
            },
          ],
        });
      }

      if (
        receiptType ===
          "cheque" ||
        receiptType ===
          "bank"
      ) {
        andConditions.push({
          $or: [
            {
              bankCash: {
                $regex:
                  /bank|cheque/i,
              },
            },
            {
              chequeNo: {
                $exists:
                  true,
                $nin: [
                  "",
                  null,
                  "-",
                  "0",
                ],
              },
            },
          ],
        });
      }

      /* =====================================================
         MAIN SEARCH
         ===================================================== */

      if (search) {
        const searchRegex =
          new RegExp(
            escapeRegex(search),
            "i"
          );

        const numericSearch =
          Number(search);

        const searchConditions = [
          {
            receiptDate:
              searchRegex,
          },

          {
            billSeries:
              searchRegex,
          },

          {
            billNo:
              searchRegex,
          },

          {
            partyId:
              searchRegex,
          },

          {
            partyName:
              searchRegex,
          },

          {
            salesmanId:
              searchRegex,
          },

          {
            salesmanName:
              searchRegex,
          },

          {
            bankCash:
              searchRegex,
          },

          {
            chequeNo:
              searchRegex,
          },

          {
            chequeDate:
              searchRegex,
          },

          {
            drawerBankId:
              searchRegex,
          },

          {
            drawerBankName:
              searchRegex,
          },

          {
            micr:
              searchRegex,
          },

          {
            narration:
              searchRegex,
          },

          {
            "receiptBills.trnSeries":
              searchRegex,
          },

          {
            "receiptBills.trnNo":
              searchRegex,
          },

          {
            "receiptBills.remark":
              searchRegex,
          },
        ];

        /*
         * Add numeric fields only when the
         * search value is a valid number.
         */
        if (
          search !== "" &&
          Number.isFinite(
            numericSearch
          )
        ) {
          searchConditions.push(
            {
              rno:
                numericSearch,
            },
            {
              receiptAmount:
                numericSearch,
            }
          );
        }

        andConditions.push({
          $or:
            searchConditions,
        });
      }

      if (
        andConditions.length > 0
      ) {
        filter.$and =
          andConditions;
      }

      /* =====================================================
         COUNT RECORDS
         ===================================================== */

      const totalRecords =
        await Receipt.countDocuments(
          filter
        );

      const totalPages =
        Math.max(
          1,
          Math.ceil(
            totalRecords /
              limit
          )
        );

      /*
       * If deletion reduces the available pages,
       * return the final valid page.
       */
      const currentPage =
        Math.min(
          page,
          totalPages
        );

      const skip =
        (
          currentPage -
          1
        ) *
        limit;

      /* =====================================================
         LOAD CURRENT PAGE ONLY
         ===================================================== */

      const receipts =
        await Receipt.find(
          filter
        )
          .sort({
            receiptDate: -1,
            rno: -1,
            createdAt: -1,
            _id: -1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res.json({
        success: true,

        /*
         * Both names are returned for safe frontend use.
         */
        receipts,

        data:
          receipts,

        count:
          receipts.length,

        pagination: {
          currentPage,

          page:
            currentPage,

          limit,

          totalRecords,

          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                  skip +
                    receipts.length,
                  totalRecords
                ),
        },

        appliedFilters: {
          search,
          fromDate,
          toDate,
          receiptType,
          party,
        },
      });
    } catch (error) {
      console.error(
        "Receipt list pagination error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Failed to load Receipt list",
        error:
          error.message,
      });
    }
  }
)

