router.get(
  "/cheque-bounce-next-no/:series",
  async (req, res) => {
    try {
      const series = String(
        req.params.series || ""
      )
        .toUpperCase()
        .trim();

      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      if (!series) {
        return res.status(400).json({
          success: false,
          message:
            "Transaction series is required.",
        });
      }

      const filter = {
        trnSeries: series,
      };

      if (distributorId) {
        filter.distributorId =
          distributorId;
      }

      if (firmId) {
        filter.firmId =
          firmId;
      }

      const lastRecord =
        await ChequeBounce.findOne(
          filter
        )
          .sort({
            trnNo: -1,
            createdAt: -1,
          })
          .lean();

      const nextNo = lastRecord
        ? Number(lastRecord.trnNo || 0) +
          1
        : 1;

      return res.json({
        success: true,
        series,
        isNewSeries: !lastRecord,
        lastNo: lastRecord
          ? Number(lastRecord.trnNo) || 0
          : 0,
        nextNo,
      });
    } catch (error) {
      console.error(
        "Cheque Bounce next number error:",
        error
      );

      return res.status(500).json({
        success: false,
        message:
          "Unable to generate next Cheque Bounce number.",
        error: error.message,
      });
    }
  }
)

