router.get(
  "/cheque-bounce/list",
  securityRouter.authorizeRequest("TRANSACTIONS", "CHEQUE_BOUNCE", "view"),
  async (req, res) => {
    try {
      const distributorId = String(
        req.query.distributorId || ""
      ).trim();

      const firmId = String(
        req.query.firmId || ""
      ).trim();

      const search = String(
        req.query.search || ""
      ).trim();

      const fromDate = String(
        req.query.fromDate || ""
      ).trim();

      const toDate = String(
        req.query.toDate || ""
      ).trim();

      const party = String(
        req.query.party || ""
      ).trim();

      const bank = String(
        req.query.bank || ""
      ).trim();

      const chequeNo = String(
        req.query.chequeNo || ""
      ).trim();

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(requestedPage) &&
        requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(requestedLimit) &&
        requestedLimit > 0
          ? Math.min(
              requestedLimit,
              100
            )
          : 10;

      if (!distributorId || !firmId) {
        return res.status(400).json({
          success: false,
          message:
            "distributorId and firmId are required",
        });
      }

      const escapeRegex = (value) =>
        String(value || "").replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      /*
       * New records are filtered by distributor and firm.
       *
       * The empty-field conditions temporarily keep old
       * Cheque Bounce records visible because older records
       * were saved before these fields were added.
       */
      const filter = {
        $and: [
          {
            $or: [
              {
                distributorId,
              },
              {
                distributorId: "",
              },
              {
                distributorId: {
                  $exists: false,
                },
              },
            ],
          },

          {
            $or: [
              {
                firmId,
              },
              {
                firmId: "",
              },
