router.put(
  "/pdc-docket/:id",
  securityRouter.authorizeRequest(
    "TRANSACTIONS",
    "PDC_DOCKET",
    "edit"
  ),
  async (req, res) => {
    try {
      const pdcId = String(req.params.id || "").trim();

      if (!mongoose.Types.ObjectId.isValid(pdcId)) {
        return res.status(400).json({
          success: false,
          message: "Invalid PDC Docket ID."
        });
      }

      const existing = await PDCDocket.findOne(tenantFilter(req, { _id: pdcId }));

      if (!existing) {
        return res.status(404).json({
          success: false,
          message: "PDC Docket not found."
        });
      }

      const body = req.body || {};

      const distributorId =
        body.distributorId ||
        existing.distributorId;

      const firmId =
        body.firmId ||
        existing.firmId;

      const docSeries = String(
        body.docSeries || ""
      ).trim();

      const docVNo =
        Number(body.docVNo) || 0;

      const duplicate =
        await PDCDocket.findOne({
          _id: { $ne: pdcId },

          distributorId,
          firmId,

          docSeries,
          docVNo
        });

      if (duplicate) {
        return res.status(400).json({
          success: false,
          message:
            `${docSeries}-${docVNo} already exists.`
        });
      }

      const updateData = {
        ...body,

        distributorId,
        firmId,

        docSeries,
        docVNo,

        totalAmount:
          Number(body.totalAmount) || 0,

        totalCheques:
          Number(body.totalCheques) || 0,

        cheques:
          Array.isArray(body.cheques)
            ? body.cheques
            : []
      };

      delete updateData._id;
      delete updateData.id;

      const updated =
        await PDCDocket.findOneAndUpdate(
          tenantFilter(req, { _id: pdcId }),
          updateData,
          {
            new: true,
            runValidators: true
          }
        );

      res.json({
        success: true,
        message:
          "PDC Docket Updated Successfully",
        data: updated
      });

    } catch (err) {

      console.error(err);

      res.status(500).json({
        success: false,
        message: err.message
      });

    }
  }
)

