router.get(
  "/contra/list",
  securityRouter.authorizeRequest("TRANSACTIONS", "CONTRA", "view"),
  async (req, res) => {
    try {
      const distributorId =
        String(
          req.query.distributorId ||
          ""
        ).trim();

      const firmId =
        String(
          req.query.firmId ||
          ""
        ).trim();

      const search =
        String(
          req.query.search ||
          ""
        ).trim();

      const fromDate =
        String(
          req.query.fromDate ||
          ""
        ).trim();

      const toDate =
        String(
          req.query.toDate ||
          ""
        ).trim();

      const transactionType =
        String(
          req.query.transactionType ||
          ""
        ).trim();

      const voucherNo =
        String(
          req.query.voucherNo ||
          ""
        ).trim();

      const narration =
        String(
          req.query.narration ||
          ""
        ).trim();

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(
          requestedPage
        ) &&
        requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(
          requestedLimit
        ) &&
        requestedLimit > 0
          ? Math.min(
              requestedLimit,
              100
            )
          : 10;

      if (
        !distributorId ||
        !firmId
      ) {
        return res
          .status(400)
          .json({
            success: false,
            message:
              "distributorId and firmId are required",
          });
      }

      const escapeRegex = (
        value
      ) =>
        String(
          value || ""
        ).replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      /*
       * Blank tenant values are temporarily
       * allowed so old Contra records remain
       * visible after adding these new fields.
       */
      const filter = {
        $and: [
          {
            $or: [
              {
                distributorId,
              },
              {
                distributorId: "",
              },
              {
                distributorId: {
                  $exists: false,
                },
              },
            ],
          },

          {
            $or: [
              {
                firmId,
              },
              {
                firmId: "",
              },
              {
                firmId: {
                  $exists: false,
                },
              },
            ],
          },
        ],
      };

      const andConditions = [];

      /* =========================
         TRANSACTION DATE FILTER
         ========================= */

      if (
        fromDate ||
        toDate
      ) {
        const dateCondition = {};

        if (fromDate) {
          dateCondition.$gte =
            fromDate;
        }

        if (toDate) {
          dateCondition.$lte =
            toDate;
        }

        andConditions.push({
          transactionDate:
            dateCondition,
        });
      }

      /* =========================
         TRANSACTION TYPE FILTER
         ========================= */

      if (transactionType) {
        andConditions.push({
          transactionType: {
            $regex:
              escapeRegex(
                transactionType
              ),
            $options: "i",
          },
        });
      }

      /* =========================
         VOUCHER NUMBER FILTER
         ========================= */

      if (voucherNo) {
        const numericVoucherNo =
          Number(voucherNo);

        if (
          Number.isFinite(
            numericVoucherNo
          )
        ) {
          andConditions.push({
            tranVNo:
              numericVoucherNo,
          });
        } else {
          /*
           * tranVNo is numeric, so a
           * non-numeric voucher filter
           * cannot match any record.
           */
          andConditions.push({
            _id: null,
          });
        }
      }

      /* =========================
         NARRATION FILTER
         ========================= */

      if (narration) {
        andConditions.push({
          narration: {
            $regex:
              escapeRegex(
                narration
              ),
            $options: "i",
          },
        });
      }

      /* =========================
         MAIN SEARCH
         ========================= */

      if (search) {
        const searchRegex =
          new RegExp(
            escapeRegex(search),
            "i"
          );

        const numericSearch =
          Number(search);

        const searchConditions = [
          {
            transactionDate:
              searchRegex,
          },

          {
            transactionType:
              searchRegex,
          },

          {
            narration:
              searchRegex,
          },

          {
            companyId:
              searchRegex,
          },

          {
            companyName:
              searchRegex,
          },

          {
            status:
              searchRegex,
          },
        ];

        if (
          Number.isFinite(
            numericSearch
          )
        ) {
          searchConditions.push(
            {
              tranVNo:
                numericSearch,
            },
            {
              amount:
                numericSearch,
            }
          );
        }

        andConditions.push({
          $or:
            searchConditions,
        });
      }

      if (
        andConditions.length > 0
      ) {
        filter.$and.push(
          ...andConditions
        );
      }

      /* =========================
         COUNT RECORDS
         ========================= */

      const totalRecords =
        await Contra.countDocuments(
          filter
        );

      const totalPages =
        Math.max(
          1,
          Math.ceil(
            totalRecords /
            limit
          )
        );

      const currentPage =
        Math.min(
          page,
          totalPages
        );

      const skip =
        (
          currentPage -
          1
        ) *
        limit;

      /* =========================
         LOAD CURRENT PAGE
         ========================= */

      const records =
        await Contra.find(
          filter
        )
          .sort({
            transactionDate: -1,
            tranVNo: -1,
            createdAt: -1,
            _id: -1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res.json({
        success: true,

        records,

        data: records,

        count:
          records.length,

        pagination: {
          currentPage,

          page:
            currentPage,

          limit,

          totalRecords,

          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                  skip +
                  records.length,
                  totalRecords
                ),
        },

        appliedFilters: {
          search,
          fromDate,
          toDate,
          transactionType,
          voucherNo,
          narration,
        },
      });
    } catch (error) {
      console.error(
        "Contra pagination error:",
        error
      );

      return res
        .status(500)
        .json({
          success: false,
          message:
            "Failed to load Contra list",
          error:
            error.message,
        });
    }
  }
)

