router.put(
  "/collection-voucher/:id",
  securityRouter.authorizeRequest(
    "TRANSACTIONS",
    "COLLECTION_VOUCHER",
    "edit"
  ),
  async (req, res) => {
    try {
      const voucherId = String(req.params.id || "").trim();

      if (!mongoose.Types.ObjectId.isValid(voucherId)) {
        return res.status(400).json({
          success: false,
          message: "Invalid Collection Voucher ID."
        });
      }

      const existing =
        await CollectionVoucher.findOne(tenantFilter(req, { _id: voucherId }));

      if (!existing) {
        return res.status(404).json({
          success: false,
          message: "Collection Voucher not found."
        });
      }

      const body = req.body || {};

      const distributorId =
        body.distributorId ||
        existing.distributorId;

      const firmId =
        body.firmId ||
        existing.firmId;

      const colVNo =
        Number(body.colVNo) || 0;

      const duplicate =
        await CollectionVoucher.findOne({
          _id: { $ne: voucherId },

          distributorId,
          firmId,

          colVNo
        });

      if (duplicate) {
        return res.status(400).json({
          success: false,
          message:
            `Collection Voucher No ${colVNo} already exists.`
        });
      }

      const updateData = {
        ...body,

        distributorId,
        firmId,

        colVNo,

        bills:
          Array.isArray(body.bills)
            ? body.bills
            : []
      };

      delete updateData._id;
      delete updateData.id;

      const updated =
        await CollectionVoucher.findOneAndUpdate(
          tenantFilter(req, { _id: voucherId }),
          updateData,
          {
            new: true,
            runValidators: true
          }
        );

      res.json({
        success: true,
        message:
          "Collection Voucher Updated Successfully",
        data: updated
      });

    } catch (error) {

      console.error(error);

      res.status(500).json({
        success: false,
        message: error.message
      });

    }
  }
)

