router.get(
  "/collection-voucher/list",
  securityRouter.authorizeRequest("TRANSACTIONS", "COLLECTION_VOUCHER", "view"),
  async (req, res) => {
    try {
      const distributorId =
        String(
          req.query.distributorId ||
          ""
        ).trim();

      const firmId =
        String(
          req.query.firmId ||
          ""
        ).trim();

      const search =
        String(
          req.query.search ||
          ""
        ).trim();

      const fromDate =
        String(
          req.query.fromDate ||
          ""
        ).trim();

      const toDate =
        String(
          req.query.toDate ||
          ""
        ).trim();

      const collectionType =
        String(
          req.query.collectionType ||
          ""
        ).trim();

      const voucherNo =
        String(
          req.query.voucherNo ||
          ""
        ).trim();

      const minimumAmount =
        String(
          req.query.minimumAmount ||
          ""
        ).trim();

      const requestedPage =
        Number.parseInt(
          req.query.page,
          10
        );

      const requestedLimit =
        Number.parseInt(
          req.query.limit,
          10
        );

      const page =
        Number.isFinite(
          requestedPage
        ) &&
        requestedPage > 0
          ? requestedPage
          : 1;

      const limit =
        Number.isFinite(
          requestedLimit
        ) &&
        requestedLimit > 0
          ? Math.min(
              requestedLimit,
              100
            )
          : 10;

      if (
        !distributorId ||
        !firmId
      ) {
        return res
          .status(400)
          .json({
            success: false,
            message:
              "distributorId and firmId are required",
          });
      }

      const escapeRegex = (
        value
      ) =>
        String(
          value || ""
        ).replace(
          /[.*+?^${}()|[\]\\]/g,
          "\\$&"
        );

      /*
       * Old records with blank tenant fields
       * remain visible during migration.
       */
      const filter = {
        $and: [
          {
            $or: [
              {
                distributorId,
              },
              {
                distributorId: "",
              },
              {
                distributorId: {
                  $exists: false,
                },
              },
            ],
          },

          {
            $or: [
              {
                firmId,
              },
              {
                firmId: "",
              },
              {
                firmId: {
                  $exists: false,
                },
              },
            ],
          },
        ],
      };

      const andConditions = [];

      /* =========================
         COLLECTION DATE FILTER
         ========================= */

      if (
        fromDate ||
        toDate
      ) {
        const dateCondition = {};

        if (fromDate) {
          dateCondition.$gte =
            fromDate;
        }

        if (toDate) {
          dateCondition.$lte =
            toDate;
        }

        andConditions.push({
          collectionDate:
            dateCondition,
        });
      }

      /* =========================
         COLLECTION TYPE FILTER
         ========================= */

      if (collectionType) {
        andConditions.push({
          collectionType: {
            $regex:
              escapeRegex(
                collectionType
              ),
            $options: "i",
          },
        });
      }

      /* =========================
         VOUCHER NUMBER FILTER
         ========================= */

      if (voucherNo) {
        const numericVoucherNo =
          Number(voucherNo);

        if (
          Number.isFinite(
            numericVoucherNo
          )
        ) {
          andConditions.push({
            colVNo:
              numericVoucherNo,
          });
        } else {
          andConditions.push({
            _id: null,
          });
        }
      }

      /* =========================
         MINIMUM AMOUNT FILTER
         ========================= */

      if (minimumAmount) {
        const numericMinimumAmount =
          Number(minimumAmount);

        if (
          Number.isFinite(
            numericMinimumAmount
          )
        ) {
          andConditions.push({
            totalCollectionAmount: {
              $gte:
                numericMinimumAmount,
            },
          });
        }
      }

      /* =========================
         MAIN SEARCH
         ========================= */

      if (search) {
        const searchRegex =
          new RegExp(
            escapeRegex(search),
            "i"
          );

        const numericSearch =
          Number(search);

        const searchConditions = [
          {
            collectionDate:
              searchRegex,
          },

          {
            collectionType:
              searchRegex,
          },

          {
            narration:
              searchRegex,
          },

          {
            companyId:
              searchRegex,
          },

          {
            companyName:
              searchRegex,
          },

          {
            status:
              searchRegex,
          },

          {
            "bills.billSeries":
              searchRegex,
          },

          {
            "bills.billNo":
              searchRegex,
          },

          {
            "bills.partyCode":
              searchRegex,
          },

          {
            "bills.partyName":
              searchRegex,
          },

          {
            "bills.recSeries":
              searchRegex,
          },

          {
            "bills.recVNo":
              searchRegex,
          },
        ];

        if (
          Number.isFinite(
            numericSearch
          )
        ) {
          searchConditions.push(
            {
              colVNo:
                numericSearch,
            },

            {
              totalCollectionAmount:
                numericSearch,
            },

            {
              totalCashCollection:
                numericSearch,
            },

            {
              totalChequeCollection:
                numericSearch,
            },

            {
              totalBills:
                numericSearch,
            }
          );
        }

        andConditions.push({
          $or:
            searchConditions,
        });
      }

      if (
        andConditions.length > 0
      ) {
        filter.$and.push(
          ...andConditions
        );
      }

      const totalRecords =
        await CollectionVoucher
          .countDocuments(
            filter
          );

      const totalPages =
        Math.max(
          1,
          Math.ceil(
            totalRecords /
            limit
          )
        );

      const currentPage =
        Math.min(
          page,
          totalPages
        );

      const skip =
        (
          currentPage -
          1
        ) *
        limit;

      const records =
        await CollectionVoucher
          .find(filter)
          .sort({
            collectionDate: -1,
            colVNo: -1,
            createdAt: -1,
            _id: -1,
          })
          .skip(skip)
          .limit(limit)
          .lean();

      return res.json({
        success: true,

        records,

        data:
          records,

        count:
          records.length,

        pagination: {
          currentPage,

          page:
            currentPage,

          limit,

          totalRecords,

          totalPages,

          hasPreviousPage:
            currentPage > 1,

          hasNextPage:
            currentPage <
            totalPages,

          startRecord:
            totalRecords === 0
              ? 0
              : skip + 1,

          endRecord:
            totalRecords === 0
              ? 0
              : Math.min(
                  skip +
                  records.length,
                  totalRecords
                ),
        },

        appliedFilters: {
          search,
          fromDate,
          toDate,
          collectionType,
          voucherNo,
          minimumAmount,
        },
      });
    } catch (error) {
      console.error(
        "Collection Voucher pagination error:",
        error
      );

      return res
        .status(500)
        .json({
          success: false,
          message:
            "Failed to load Collection Voucher list",
          error:
            error.message,
        });
    }
  }
)

